(window.GIM_TS=window.GIM_TS||{})["Bava Metzia.4"]={"from":96,"a":[["\u0003שוה שש בחמש, מי נתאנה\u0004 (מי רומה) בכך — ה\u0003מוכר,\u0004 במקרה זה \u0003יד\u0004 ה\u0003מוכר על העליונה. רצה\u0004 המוכר — \u0003אומר לו\u0004 לקונה: \u0003\"תן לי מקחי\", או \"תן לי מה שאוניתני\"\u0004 \u0005[שרימית אותי\u0006 בו\u0005].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים שאלה זו\u0005]:\u0006 אונאה \u0003ב\u0004\u0003פחות משתות לרבנן\u0004 \u0005[מששית ל\u0006דעת \u0005חכמים],\u0006 האם \u0003לאלתר הויא\u0004 \u0005[מיד היא]\u0006 \u0003מחילה\u0004 \u0005[מחילה]\u0006 וחל המקח מיד בזמן המכירה, או גם זה הוא \u0003בכדי\u0004 הזמן \u0003שיראה לתגר או לקרובו? ואם תמצי לומר\u0004 \u0005[ואם תמצא לומר]\u0006 ותחליט כי הכוונה היא שזמנו \u0003בכדי שיראה לתגר או לקרובו,\u0004 אם כן \u0003מאי איכא\u0004 \u0005[מה יש,\u0006 מה ההבדל\u0005]\u0006 \u0003בין שתות\u0004 \u0005[ששית]\u0006 \u0003לפחות משתות\u0004 \u0005[מששית]?\u0006","ומשיבים: \u0003איכא\u0004 \u0005[יש]\u0006 הבדל: ש\u0003אלו שתות\u0004 — \u0003ידו על העליונה, רצה\u0004 — \u0003חוזר, רצה\u0004 — \u0003קונה ומחזיר אונאה.\u0004 ואילו אם היתה ההונאה \u0003פחות משתות\u0004 — \u0003קנה\u0004 מקח ודאי, \u0003ומחזיר\u0004 את סכום ה\u0003אונאה,\u0004 אבל איננו יכול להחזיר את המקח.","ואם כן, \u0003מאי\u0004 \u0005[מה]\u0006 התשובה לשאלה הראשונה בדבר זמן המחילה? ומציעים, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו: \u0003חזרו לדברי חכמים.\u0004","וכדי להבין כיצד הוכיחו מכאן, מסבירים: \u0003סברוה\u0004 \u0005[סברו]\u0006 הלומדים שאמרו זאת כי \u0003פחות משליש\u0004 לדעת \u0003ר' טרפון\u0004 הרי זה \u0003כפחות משתות לרבנן דמי\u0004 \u0005[מששית ל\u0006דעת \u0005חכמים נחשב].\u0006 ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003פחות משתות לרבנן\u0004 \u0005[מששית ל\u0006דעת \u0005חכמים]\u0006 זמנו \u0003בכדי שיראה לתגר או לקרובו,\u0004 ולדעת \u0003ר' טרפון\u0004 זמנו \u0003כל היום, משום הכי\u0004 \u0005[כך]\u0006 \u0003חזרו,\u0004 שהרי לפי זה אינם מרויחים דבר. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003פחות משתות\u0004 \u0005[מששית]\u0006 \u0003לרבנן לאלתר הויא\u0004 \u0005[ל\u0006דעת \u0005חכמים מיד היא]\u0006 \u0003מחילה,\u0004"],["\u0003ולר' טרפון נמי לאלתר הויא\u0004 \u0005[גם כן מיד היא]\u0006 \u0003מחילה\u0004 \u0005[מחילה],\u0006 \u0003אמאי\u0004 \u0005[משום מה]\u0006 \u0003חזרו?\u0004 הלא \u0003ב\u0004אותה הוראה של \u0003ר' טרפון ניחא להו טפי\u0004 \u0005[נוח להם יותר],\u0006 \u0003דמאי דרבנן קא משוי להו\u0004 \u0005[ש\u0006הרי \u0005מה שחכמים מחשיבים]\u0006 \u0003אונאה ל\u0004דעת \u0003ר' טרפון הויא\u0004 \u0005[הרי זו]\u0006 \u0003מחילה,\u0004 ונמצאו מרויחים לפי שיטה זו?","ודוחים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 ש\u0003פחות משליש ל\u0004דעת \u0003ר' טרפון כפחות משתות לרבנן דמי\u0004 \u0005[מששית ל\u0006דעת \u0005חכמים נחשב]?\u0006 \u0003לא, משתות\u0004 \u0005[ששית]\u0006 \u0003ועד שליש ל\u0004שיטת \u0003ר' טרפון\u0004 — \u0003כשתות\u0004 \u0005[כששית]\u0006 \u0003עצמה לרבנן דמי\u0004 \u0005[ל\u0006דעת \u0005חכמים נחשב],\u0006 שמקבל בחזרה את דמי ההונאה. ושואלים: \u0003אי הכי, במאי\u0004 \u0005[אם כך, במה]\u0006 \u0003שמחו מעיקרא\u0004 \u0005[מתחילה],\u0006 הרי נמצא שלא הרוויחו מאומה?","האם \u0003תפשוט\u0004 \u0005[תפתור]\u0006 מכאן את השאלה שנשאלת להלן, ותאמר ש\u0003בטול מקח לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003לעולם חוזר\u0004 ואז אפשר להבין את תגרי לוד, ש\u0003כיון\u0004 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' טרפון הויא\u0004 \u0005[\u0006ש\u0005הוא]\u0006 \u0003אונאה\u0004 \u0003שמחו\u0004 התגרים, \u0003כי\u0004 \u0005[\u0006ו\u0005כאשר]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 שמותר לחזור \u0003כל היום\u0004 — \u0003חזרו.\u0004","\u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003בטול מקח\u0004 לדעת חכמים אף זמנו \u0003בכדי שיראה לתגר או לקרובו במאי\u0004 \u0005[במה]\u0006 אם כן \u0003שמחו\u0004 בשיטת ר' טרפון? ומשיבים: \u0003שמחו בשתות\u0004 \u0005[בששית]\u0006 \u0003עצמה,\u0004 שמחו לענין טעות בשתות בדיוק, שלשיטת \u0003ר' טרפון\u0004 הרי זו \u0003מחילה\u0004 ולדעת חכמים הרי זו \u0003אונאה.\u0004 ומטעם זה רצו לקבל את שיטתו, אלא שלבסוף חזרו בהם.","ומעתה מבררים אותה שאלה שהוזכרה קודם בדרך אגב. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003בטול מקח לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 האם \u0003לעולם חוזר\u0004 בו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 זמנו רק \u0003בכדי שיראה לתגר או לקרובו? ואם תמצא\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 ותגיע למסקנה כי הכוונה היא \u0003בכדי שיראה לתגר או לקרובו,\u0004 יש מקום לשאול: \u0003מה איכא\u0004 \u0005[מה יש,\u0006 הבדל\u0005]\u0006 \u0003בין שתות\u0004 \u0005[ששית]\u0006 \u0003ליתר על שתות\u0004 \u0005[ששית]?\u0006 ומשיבים: \u0003איכא\u0004 \u0005[יש\u0006 הבדל\u0005]:\u0006 ש\u0003אילו שתות\u0004 \u0005[ששית]\u0006 — \u0003מי שנתאנה\u0004 (רומה) הוא בלבד \u0003חוזר, ואילו\u0004 היה \u0003יתר על שתות\u0004 \u0005[ששית]\u0006 — \u0003שניהם חוזרין.\u0004 ומכאן אין להוכיח.","ואנו חוזרים לשאלה הראשונה, \u0003מאי\u0004 \u0005[מה\u0006 פתרונה\u0005]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו שסוחרי לוד \u0003חזרו לדברי חכמים. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003בטול מקח לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 זמנו \u0003בכדי שיראה לתגר או לקרובו, ו\u0004לדעת \u0003ר' טרפון כל היום\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003חזרו. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003בטול מקח לרבנן לעולם חוזר, אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003חזרו\u0004 בהם? הלא בסופו של דבר \u0003ב\u0004שיטת \u0003ר' טרפון ניחא להו טפי\u0004 \u0005[נוח להם יותר]\u0006 משום \u0003דקא משוי להו\u0004 \u0005[שעושה\u0006 \u0003זאת]\u0004 \u0003אונאה כל היום ותו לא\u0004 \u0005[ולא עוד],\u0006 ולא כחכמים שהוא בטול מקח, ולעולם!","ומשיבים: \u0003בטול מקח לא שכיח\u0004 \u0005[אינו מצוי]\u0006 ולא הביאו בחשבון להעמיד את מסחרם בהתחשב בטעויות בלתי מצויות.","ולסיכום הלכתי של השאלות הללו, \u0003אמר רבא: הלכתא\u0004 \u0005[הלכה]\u0006 היא אם היה ההבדל \u0003פחות משתות\u0004 \u0005[מששית]\u0006 — \u0003נקנה\u0004 ה\u0003מקח\u0004 מיד, ואם היה ההבדל \u0003יותר על שתות\u0004 \u0005[ששית]\u0006 — הרי יש בזה \u0003ביטול מקח, שתות\u0004 \u0005[ששית]\u0006 בדיוק — \u0003קנה ומחזיר אונאה, וזה וזה,\u0004 מחילה, ביטול מקח, ואונאה — זמנו \u0003בכדי שיראה לתגר או לקרובו.\u0004","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא:\u0004 אם היתה ה\u0003אונאה פחות משתות\u0004 \u0005[מששית]\u0006 — \u0003נקנה מקח, יתר על שתות\u0004 \u0005[ששית]\u0006 — \u0003בטל מקח, שתות\u0004 \u0005[ששית]\u0006 בדיוק — \u0003קנה ומחזיר אונאה,\u0004 אלו דברי \u0003ר' נתן. ר' יהודה הנשיא אומר: יד\u0004 ה\u0003מוכר על העליונה, רוצה\u0004 — \u0003אומר לו\u0004 המוכר ללוקח: \u0003\"תן לי מקחי\", או\u0004 אומר \u0003\"תן לי מה שאניתני\"\u0004 (רימיתני). ועל כל פנים שיעורם \u0003זה וזה בכדי שיראה לתגר או לקרובו.\u0004","שנינו במשנה \u0003עד מתי מותר להחזיר\u0004 — עד שיראה לתגר או לקרובו. \u0003אמר רב נחמן: לא שנו אלא\u0004 ב\u0003לוקח\u0004 שנתנו לו זמן מוגבל לבדיקה, \u0003אבל מוכר\u0004 — \u0003לעולם חוזר.\u0004 ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[האם נאמר שמסייע לו]\u0006 ממה ששנינו על תגרי לוד אשר \u0003חזרו לדברי חכמים. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003מוכר לעולם חוזר\u0004"],["\u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003חזרו,\u0004 שהרי הם היו המוכרים ולהם מותר לחזור לעולם, ונמצא שר' טרפון הוסיף זמן רק לקונים.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שה\u0003מוכר נמי\u0004 \u0005[גם כן]\u0006 \u0003כלוקח דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 אם כן \u0003מאי נפקא להו מינה\u0004 \u0005[מה יוצא להם מכך]?\u0006 הלא \u0003כי היכי דעבדי ליה רבנן תקנתא\u0004 \u0005[כפי שעשו לו חכמים תקנה]\u0006 \u0003ללוקח, הכי נמי עבדי ליה רבנן תקנתא\u0004 \u0005[כך גם כן עשו לו חכמים תקנה]\u0006 \u0003למוכר,\u0004 וטוב היה להם בשיטת ר' טרפון, שיש להם זמן רב יותר למכור!","ומשיבים: \u0003תגרי לוד לא שכיח דטעו\u0004 \u0005[אינו מצוי ש\u0006הם \u0005טועים]\u0006 ולכן, גם אם יש רק זמן מוגבל לחזרה, עבור המוכר, אינם חוששים לכך.","מסופר: \u0003אושפזיכניה\u0004 \u0005[בעל\u0006 \u0003הבית]\u0004 של \u0003רמי בר חמא זבין חמרא\u0004 \u0005[מכר חמור]\u0006 \u0003וטעה\u0004 במחיר. \u0003אשכחיה דהוה עציב\u0004 \u0005[מצאו\u0006 רמי בר חמא \u0005שהוא עצוב]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי עציבת\u0004 \u0005[מדוע אתה עצוב]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זביני חמרא וטעאי\u0004 \u0005[מכרתי חמור וטעיתי]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל הדר\u0004 \u0005[לך חזור]\u0006 \u0003בך.\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא שהאי לי\u0004 \u0005[הרי שהיתי\u0006 כבר\u0005]\u0006 \u0003יותר מכדי שאראה לתגר או לקרובי! שדריה לקמיה\u0004 \u0005[שלח אותו לפני]\u0006 \u0003רב נחמן,\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003לא שנו\u0004 שנתנו לו שיעור זמן זה \u0003אלא\u0004 לגבי ה\u0003לוקח\u0004 \u0003אבל\u0004 ה\u0003מוכר\u0004 — \u0003לעולם חוזר.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומסבירים: \u0003לוקח מקחו בידו, כל היכא דאזיל מחוי ליה\u0004 \u0005[מקום ש\u0006הוא \u0005הולך\u0006 הוא \u0005מראה אותו]\u0006 \u0003ואמרי ליה אי\u0004 \u0005[ואומרים לו אם]\u0006 \u0003טעה, אי\u0004 \u0005[אם]\u0006 \u0003לא טעה.\u0004 ה\u0003מוכר דלא נקט מקחיה בידיה\u0004 \u0005[שאינו מחזיק את מקחו בידו]\u0006 \u0003עד דמיתרמי ליה\u0004 \u0005[שמזדמנת לו]\u0006 — \u0003זבינתא כזבינתיה\u0004 \u0005[סחורה כסחורתו]\u0006 \u0003וידע אי\u0004 \u0005[ויודע\u0006 הוא \u0005אם]\u0006 \u0003טעה ואי\u0004 \u0005[ואם]\u0006 \u0003לא טעה.\u0004","מסופר: \u0003ההוא גברא דהוה נקט ורשכי לזבוני\u0004 \u0005[אדם אחד שהיה מחזיק רצועות משי למכור].\u0006 \u0003קרי שיתא ושויא חמשא\u0004 \u0005[היה מכריז\u0006 שמוכרם \u0005בששה\u0006 והיו \u0005שוים חמישה],\u0006 \u0003ואי הוו יהבי ליה חמשא ופלגא הוה שקיל\u0004 \u0005[ואם היו נותנים לו חמשה וחצי היה לוקח].\u0006 \u0003אתא ההוא גברא\u0004 \u0005[בא אדם אחד]\u0006 \u0003ואמר\u0004 בלבו: \u0003אי יהיבנא ליה חמשא ופלגא הויא\u0004 \u0005[אם אתן לו חמש וחצי\u0006 הרי \u0005תהא]\u0006 זו \u0003מחילה\u0004 ולא אוכל לקבל את ההבדל במחיר. \u0003אתן ליה שיתא ואתבעיה לדינא\u0004 \u0005[אתן לו ששה ו\u0006אחר כך \u0005אתבענו לדין]\u0006 ואקבל את כל דמי ההונאה בחזרה. ועשה כן. ואחר כך, \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רבא אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שנו אלא בלוקח מן התגר\u0004 יש דין זה בהונאה, \u0003אבל בלוקח מבעל הבית אין לו עליו אונאה.\u0004","כיוצא בו מסופר: \u0003ההוא גברא דהוה נקיט כיפי לזבוני\u0004 \u0005[אדם אחד היה מחזיק תכשיטים למכור]\u0006 \u0003קרי שתין ושוי חמשין\u0004 \u0005[היה מכריז בששים והיו שוים\u0006 באמת \u0005חמישים],\u0006 \u0003ואי הוו יהבי ליה חמשין וחמשא הוה שקיל\u0004 \u0005[ואם היו נותנים לו חמישים וחמישה\u0006 היה \u0005לוקח].\u0006 \u0003אתא ההוא גברא ואמר\u0004 \u0005[בא אדם אחד ואמר\u0006 בלבו\u0005]:\u0006 \u0003אי יהיבנא ליה חמשין וחמשא הויא\u0004 \u0005[אם אתן לו חמשים וחמשה תהא]\u0006 זו \u0003מחילה, אתן ליה שיתין ואתבעיה לדינא\u0004 \u0005[לו ששים ואתבענו לדין].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב חסדא\u0004 לברר מה הדין בכגון זה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שנו אלא בלוקח מן התגר, אבל בלוקח מבעל הבית\u0004 — \u0003אין לו עליו אונאה.\u0004","\u0003אמר ליה רב דימי: ישר,\u0004 כלומר, יפה הדבר. \u0003וכן אמר ר' אלעזר: ישר.\u0004 ושואלים: \u0003והא אנן תנן\u0004 \u0005[הרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003כשם שאונאה להדיוט כך אונאה לתגר. מאן\u0004 \u0005[מי הוא]\u0006 \u0003הדיוט,\u0004 \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה ל\u0003בעל הבית\u0004 סתם, שאיננו תגר מומחה? \u0003אמר רב חסדא:\u0004 שם מדובר \u0003בצדרייתא\u0004 \u0005[בגדי פשתן פשוטים]\u0006 שעושים אותם לשם מכירה. \u0003אבל מאני תשמישתיה דיקירי עליה\u0004 \u0005[חפצי תשמישו\u0006 של בעל הבית \u0005שחשובים עליו]\u0006 \u0003לא מזבין להו אי לאו בדמי יתירי\u0004 \u0005[אינו מוכר אותם אם לא בדמים יתרים],\u0006 שקשה בעיניו למוכרם, וכל הקונה צריך להביא בחשבון שהמוכר מוכרם יותר מכדי שווים האמיתי.","\u0003אחד הלוקח\u0004 (קונה) \u0003ואחד המוכר יש להן\u0004 דין \u0003אונאה. כשם שאונאה להדיוט כך אונאה לתגר. ר' יהודה אומר: אין אונאה לתגר\u0004 לפי שהוא בקי. \u0003מי שהוטל עליו\u0004 (רומה) — \u0003ידו על העליונה, רצה\u0004 — \u0003אומר לו\u0004 לצד השני: \u0003תן לי מעותי\u0004 כולן ויתבטל המקח, \u0003או תן לי מה שאניתני\u0004 (שרימיתני).","שואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שאונאה גם לקונה וגם למוכר? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הכתוב \u0003\"וכי תמכרו ממכר לעמיתך... אל תונו\u0004 איש את אחיו\u0003\"\u0004 (ויקרא כה, יד). מתוך הפסוק \u0003אין לי אלא\u0004 מקרה שבו \u0003נתאנה\u0004 (רומה) \u0003לוקח, נתאנה מוכר מנין? תלמוד לומר: \"או קנה\u0004 מיד עמיתך \u0003אל תונו\"\u0004 (שם).","ומעירים: \u0003ואיצטריך למכתב\u0004 \u0005[וצריך לכתוב]\u0006 ב\u0003לוקח ואיצטריך למכתב\u0004 \u0005[וצריך לכתוב]\u0006 ב\u0003מוכר\u0004 \u0005[והוצרך לכתוב בלוקח והוצרך לכתוב במוכר]\u0006 ואי אפשר ללמוד זה מזה. \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 רק ב\u0003מוכר\u0004 שלא ירמה — \u0003משום דקים ליה בזבינתיה\u0004 \u0005[משום שהוא יודע בסחורתו],\u0006 אבל ה\u0003לוקח\u0004 ש\u0003לא קים ליה בזבינתיה\u0004 \u0005[ברור לו בסחורתו]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 שמא \u0003לא אזהריה רחמנא\u0004 \u0005[הזהירתו התורה]\u0006 \u0003ב\"לא תונו\".\u0004","\u0003ו\u0004להיפך, \u0003אי כתב רחמנא\u0004 \u0005[אילו כתבה התורה]\u0006 איסור רמאות רק ב\u0003לוקח\u0004 — \u0003משום דקא קני\u0004 \u0005[שהוא קונה]\u0006 ונהנה מכך, \u0003דאמרי אינשי:\u0004 אם \u0003זבנית\u0004 \u0005[קנית]\u0006 — \u0003קנית\u0004 לעצמך דבר. \u0003אבל מוכר דאבודי קא מוביד\u0004 \u0005[שמאבד\u0006 במכירתו\u0005],\u0006 \u0003דאמרי אינשי: זבין אוביד\u0004 \u0005[\u0006מי \u0005שמכר איבד],\u0006 \u0003אימא\u0004 \u0005אמור\u0006 שמא \u0003לא אזהריה רחמנא\u0004 \u0005[הזהירתו התורה]\u0006 ב\u0003\"לא תונו\",\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר בשניהם.","שנינו במשנה ש\u0003ר' יהודה אומר: אין אונאה לתגר.\u0004 ושואלים: \u0003משום שהוא תגר אין לו אונאה?\u0004 הלא גם הוא יכול לטעות!","\u0003אמר רב נחמן אמר רב: בתגר ספסר\u0004 \u0005[סרסור]\u0006 \u0003שנו,\u0004 שקונה סחורה וחוזר ומוכרה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003מידע ידע זבינתיה\u0004 \u0005[יודע\u0006 הוא \u0005בקנייתו]\u0006 \u0003כמה שויא\u0004 \u0005[\u0006היא \u0005שווה]\u0006 \u0003ואחולי אחיל גביה\u0004 \u0005[ומחל לו].\u0006 \u0003והאי דזבנא הכי\u0004 \u0005[וזה שמכר אותה כך]\u0006 בפחות משוויה — \u0003משום דאתרמיא ליה זבינתא אחריתי\u0004 \u0005[שנזדמן לו מסחר אחר]\u0006 והיה זקוק לכסף.","ושואלים: \u0003והשתא מיהא קא הדר ביה\u0004 \u0005[ועכשיו\u0006 הרי \u0005מכל מקום חוזר\u0006 הוא \u0005בו]\u0006 והרי זו הוכחה שלא מחל! \u0003רב אשי אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין לתגר אונאה\u0004 — \u0003אינו בתורת אונאה\u0004 כלל, \u0003שאפילו\u0004 ב\u0003פחות מכדי אונאה חוזר.\u0004 שהרי כל רווחו הוא בהבדל הקטן שבין מה שהוא קונה ומוכר, ואם יפסיד ממנו, אינו יכול להתקיים. ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב נחמן,\u0004 \u0003ר' יהודה אומר: תגר אין לו אונאה, מפני שהוא בקי.\u0004","שנינו במשנה: \u0003מי שהוטל עליו ידו על העליונה.\u0004 ושואלים: \u0003מני מתניתין\u0004 \u0005[כמי היא משנתנו]?\u0006 הרי איננה \u0003לא כ\u0004שיטת \u0003ר' נתן ולא כ\u0004שיטת \u0003ר' יהודה הנשיא.\u0004","ומדוע, \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' נתן\u0004 — הלא \u0003במתניתין קתני\u0004 \u0005[במשנתנו שנה]\u0006 \u0003\"רצה\u0004 אומר לו כו' \u0003\",\u0004 \u0003ו\u0004ב\u0003ברייתא לא קתני\u0004 \u0005[שנה]\u0006 \u0003\"רצה\"\u0004 ולכאורה משמע שבמקח נקנה, בבעל כורחו, אף כי יכול לקבל מה שהתאנה בו. \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה הנשיא,\u0004 הלא \u0003מתניתין קתני\u0004 \u0005[\u0006ב\u0005משנתנו שנה]\u0006 \u0003\"לוקח\",\u0004 \u0003ו\u0004ב\u0003ברייתא קתני\u0004 \u0005[שנה]\u0006 \u0003\"מוכר\"\u0004 ולא הזכיר לוקח כלל.","\u0003(סימן ז\"ב ר\"ש\u0004 לחכמים שנתנו תירוץ לקושיה זו: ר' אלע \u0003ז\u0004 ר, ר \u0003ב\u0004ה, \u0003ר\u0004 בא, רב א \u0003ש\u0004י","\u0003). אמר ר' אלעזר:\u0004 דין \u0003אונאה זו\u0004 שבמשנתנו \u0003איני יודע מי שנאה,\u0004 כלומר, הדבר סתום, שלכאורה אינו כשיטת שום חכם. ואלו \u0003רבה אמר: לעולם כ\u0004שיטת \u0003ר' נתן היא\u0004 משנתנו, \u0003ותני נמי\u0004 \u0005[ושנה גם כן]\u0006 \u0003בברייתא\u0004 ותקן: \u0003\"רצה\",\u0004 כמו במשנתנו. \u0003רבא אמר: לעולם כ\u0004שיטת \u0003ר' יהודה הנשיא היא\u0004 משנתנו, \u0003ומאי\u0004 \u0005[ומה]\u0006 ש\u0003שייר במתניתין\u0004 \u0005[במשנתנו]\u0006 \u0003קא מפריש\u0004 \u0005[מפרש]\u0006 \u0003בברייתא,\u0004 שבמשנתנו לא השלים להסביר את כל שיטתו. \u0003אמר רב אשי: דיקא נמי\u0004 \u0005[מדוייק גם\u0006 כן הדבר\u0005]\u0006 בלשון המשנה, \u0003דקתני\u0004 \u0005[ששנה]\u0006 \u0003\"אחד הלוקח ואחד המוכר\", ומפרש ליה\u0004 \u0005[ומפרש אותו]\u0006 את דינו של ה\u0003לוקח,\u0004 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי אכן \u0003שיוריה שייריה\u0004 \u0005[שייר]\u0006 את דינו של ה\u0003מוכר\u0004 ולא פירש את כל פרטיו. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: \u0003האומר לחבירו\u0004 הרי אנחנו עושים מסחר \u0003על מנת שאין לך עלי אונאה,\u0004 שאם יתברר שרומית — לא תוכל לתבוע. \u0003רב אמר:\u0004 אף על פי כן \u0003יש לו עליו אונאה. ושמואל אמר: אין לו עליו אונאה.\u0004 ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003רב\u0004 אמר בענין זה \u0003כ\u0004שיטת \u0003ר' מאיר, ושמואל\u0004 ש\u0003אמר כ\u0004שיטת \u0003ר' יהודה.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לאשה הרי את מקודשת לי על מנת שאין לך עלי\u0004 ההתחייבויות החלות על כל אדם משעת הנישואין של \u0003שאר\u0004 (אוכל), \u0003כסות\u0004 (לבוש), \u0003ועונה\u0004 (חיי אישות) — \u0003הרי זו מקודשת\u0004 כפי שאמר, \u0003ותנאו בטל,\u0004 כ\u0003דברי ר' מאיר.\u0004 שלדעתו אי אפשר לקבוע תנאי המבטל חובה שאדם מצווה עליה מן התורה. \u0003ור' יהודה אומר: בדבר שבממון\u0004 — \u0003תנאו קיים,\u0004 אבל לא בהתחייבות אישית. ולכאורה מחלוקת זו אם בדבר שבממון אפשר להתנות על הכתוב בתורה, היא היא מחלוקת רב ושמואל!","ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב:\u0004 \u0003אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 דברי \u0003אפילו\u0004 לדעת \u0003ר' יהודה\u0004 אמרתי; ואולם, \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהודה התם\u0004 \u0005[שם]\u0006 שתנאי שבממון קיים אלא ש\u0003ידעה\u0004 שהיא מוותרת \u0003וקא\u0004 \u0005[ו\u0006ביודעין \u0005היא]\u0006 \u0003מחלה,\u0004"],["\u0003אבל הכא\u0004 \u0005[כאן]\u0006 כשאומר לו על מנת שאין לו אונאה \u0003מי ידע דמחיל\u0004 \u0005[האם יודע\u0006 הוא בבירור שתהא אונאה \u0005שמוחל]?\u0006 שהרי הוא סבור שמא אין כאן הונאה.","\u0003ושמואל אמר: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי \u0003אפילו ל\u0004שיטת \u0003ר' מאיר\u0004 הם, שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם],\u0006 \u0003אלא\u0004 ש\u0003ודאי קא עקר\u0004 \u0005[הוא עוקר]\u0006 דבר מן התורה בתנאי מפורש, \u0003אבל הכא מי יימר דקא עקר מידי\u0004 \u0005[כאן מי יאמר שהוא עוקר דבר],\u0006 הלא יתכן שלא תהיה הונאה, ואם כן לא נעקר דבר.","\u0003אמר רב ענן: לדידי מפרשא לי מיניה\u0004 \u0005[לי\u0006 עצמי \u0005נתפרש הדבר ממנו]\u0006 מ\u0003מר שמואל\u0004 עצמו: \u0003האומר לחבירו \"על מנת שאין לך עלי אונאה\"\u0004 — \u0003אין לו עליו אונאה,\u0004 שהוא יכול לוותר על האונאה שרימהו חבירו. ואולם אם אמר לשון כללית \u0003\"על מנת שאין בו אונאה\"\u0004 — \u0003הרי יש בו אונאה\u0004 לפי שאינו יכול לבטל את דין התורה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003הנושא והנותן באמנה\u0004 (הסכמי אמנה) שעושה מסחר עבור חבירו לפי הסכם מראש שיקבל אחוז מסויים כרווח, או \u0003האומר לחבירו \"על מנת שאין לך עלי אונאה\"\u0004 — באלה \u0003אין לו עליו אונאה.\u0004 ומעתה \u0003לרב\u0004 ש\u0003אמר:\u0004 \u0003אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי \u0003אפילו\u0004 \u0003ל\u0004דעת \u0003ר' יהודה, הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006","\u0003אמר אביי:\u0004 מכאן \u0003מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 כי \u0003רב אמר כ\u0004שיטת \u0003ר' מאיר, ושמואל אמר כ\u0004שיטת \u0003ר' יהודה.\u0004 וברייתא זו כשיטת ר' יהודה.","\u0003רבא אמר: לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 — \u0003בסתם, כאן\u0004 — \u0003במפרש.\u0004 שאם אומר סתם \"אין לך עלי אונאה\" — יש לו דין אחר, ואם מפרש שיש בדבר זה אונאה — יש בו דין אחר.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 כעין זה: \u0003במה דברים אמורים\u0004 — \u0003בסתם, אבל במפרש,\u0004 כגון \u0003מוכר שאמר ללוקח\u0004 (קונה) \u0003חפץ זה שאני מוכר לך במאתים\u0004 דינרים \u0003יודע אני בו שאינו שוה אלא מנה\u0004 (מאה דינרים), ובכל זאת אני מוכר לך אותו במאתים \u0003על מנת שאין לך עלי אונאה\u0004 — במקרה זה \u0003אין לו עליו אונאה.\u0004 וכן \u0003לוקח שאמר למוכר: חפץ זה שאני לוקח ממך במנה יודע אני בו ששוה מאתים\u0004 דינרים \u0003על מנת שאין לך עלי אונאה\u0004 — \u0003אין לו עליו אונאה.\u0004 ואם כן כשהדבר מפורש — בזה מסכימים הכל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנושא והנותן באמנה, הרי זה לא יחשב את הרע באמנה ואת היפה בשוה\u0004 (כדי שוויו). \u0003אלא, או זה וזה באמנה, או זה וזה בשוה.\u0004","\u0003ונותן לו\u0004 בעל הכספים לאיש שעובד עבורו \u0003שכר כתף\u0004 (סבל), \u0003שכר גמל, שכר פונדק\u0004 שהוציא תוך כדי קניית הסחורה. \u0003שכר עצמו\u0004 עבור טרחתו של העוסק — \u0003אינו נוטל שכבר נתן לו שכרו משלם\u0004 (מלא).","ושואלים: \u0003שכרו משלם מהיכא קא יהיב ליה\u0004 \u0005[מהיכן נותן לו]\u0006 הלא עדיין לא שילם לו? ומשיבים: \u0003אמר רב פפא:\u0004 כאן מדובר \u0003בצדרויי דיהבי\u0004 \u0005[במוכרי בגדים זולים]\u0006 שיש להם שכר קצוב של \u0003ארבע למאה\u0004 עבור המכירה, ואחוז זה נחשב כשכר טרחתו של העוסק.","\u0003כמה תהא\u0004 המטבע של \u0003סלע חסירה\u0004 על ידי שחיקה ושימוש \u0003ולא יהא בה אונאה\u0004 אלא תיחשב כמטבע כשרה? \u0003ר' מאיר אומר: ארבע איסרות\u0004 (איסרים) לסלע, פחת של \u0003איסר לדינר,\u0004 שהוא אחד מעשרים וארבע בו. \u0003ור' יהודה אומר:\u0004 הפחת המותר הוא \u0003ארבע פונדיונות\u0004 (פונדיונים), \u0003פונדיון לדינר\u0004 שהוא פחת של אחד משנים עשר בו. \u0003ור' שמעון אומר:\u0004"],["\u0003שמונה פונדיונות\u0004 (פונדיונים), \u0003שני פונדיונות לדינר,\u0004 והוא כדי ששית מן הערך.","\u0003עד מתי מותר להחזיר\u0004 מטבע שחוקה? \u0003בכרכים\u0004 — \u0003עד כדי שיראה לשולחני\u0004 (מחליף כספים) שהוא בקי בכך, ו\u0003בכפרים\u0004 שאין בהם שולחני — \u0003עד ערבי שבתות,\u0004 שאז כרגיל קונים אנשים צרכי שבת ואז יכול להיות שלא ירצו למכור לו במטבע זו. \u0003אם היה\u0004 נותן המטבע \u0003מכירה,\u0004 את המטבע — \u0003אפילו לאחר שנים עשר חדש מקבלה הימנו\u0004 אם יתברר שהיא פחותה מעט, \u0003ואין לו עליו,\u0004 על הלוקח, \u0003אלא תרעומת,\u0004 על כך שהוא מטריד אותו להחליף לו מטבע הראויה למסחר.","\u0003ונותנה\u0004 את המטבע השחוקה לפדיון \u0003מעשר שני ואינו חושש,\u0004 שכל המחזיר דבר כגון זה \u0003אינו אלא נפש רעה,\u0004 ומטבע זו כשרה לכל שימוש.","במשנה שנינו עד כמה אין בה אונאה, \u0003ורמינהי\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו במקום אחר: \u0003\"עד כמה תהא הסלע חסירה ויהיה בה אונאה\",\u0004 ומונה כמו במשנתנו, משמע שבשיעורים ששנינו יש אונאה, היפך דברי המשנה!","\u0003אמר רב פפא: לא קשיא\u0004 \u0005[אינו קשה];\u0006 ה\u0003תנא דידן\u0004 \u0005[שלנו,\u0006 במשנתנו\u0005]\u0006 \u0003קא חשיב\u0004 \u0005[מונה]\u0006 \u0003ממטה למעלה,\u0004 ומונה עד היכן אין בו הונאה, ואילו ה\u0003תנא ברא קא חשיב\u0004 \u0005[החיצון,\u0006 של הברייתא, \u0005מונה]\u0006 \u0003מלמעלה למטה\u0004 עד היכן הוא גבול האונאה, אבל בגופו של דבר לא נחלקו.","לעצם המחלוקת בדבר ההונאה בסלע שואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003ב\u0004ענין \u0003סלע דפליגי\u0004 \u0005[ש\u0006הם \u0005חלוקים]\u0006 כמה שיעור האונאה, \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003ב\u0004ענין \u0003טלית\u0004 ש\u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 אם האונאה היא שתות או פחות משתות?","\u0003אמר רבא: מאן תנא\u0004 \u0005[מי הוא\u0006 החכם \u0005ששנה]\u0006 \u0003טלית,\u0004 כלומר, שנה את המשניות הקודמות — שיטת \u0003ר' שמעון היא,\u0004 שלדעתו כל אונאה בשתות. ואילו \u0003אביי אמר\u0004 יש הבדל בין הדברים: \u0003טלית\u0004 — \u0003עד שתות\u0004 \u0005[ששית]\u0006 \u0003מחיל איניש\u0004 \u0005[אדם\u0006 עשוי \u0005למחול],\u0006 \u0003דאמרי אינשי\u0004 \u0005[שאומרים אנשים]\u0006 בפתגם עממי: \u0003עשיק לגביך ושוי לכרסיך\u0004 \u0005[צמצם\u0006 וקמץ מרכושך \u0005וקנה\u0006 דבר \u0005עבור גבך\u0006 בגד להתכסות בו, וקנה רק במחיר \u0005שווה עבור כרסך,\u0006 לאכול\u0005],\u0006 וכיון שכדאי לאדם לקנות לעצמו בגדים הגונים, אין הטעות בענין זה נחשבת כל כך. ואילו \u0003סלע, כיון דלא סגי ליה\u0004 \u0005[שאינה מהלכת לה],\u0006 שאינה נסחרת — הריהו \u0003לא מחיל\u0004 \u0005[מוחל]\u0006 אף בשיעור פחות.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה מביאים מן התוספתא: \u0003עד כמה תהא הסלע חסירה ויהא בה אונאה? ר' מאיר אומר: ארבעה איסרות\u0004 (איסרים), \u0003איסר לדינר. ר' יהודה אומר: ארבעה פונדיונות, פונדיון לדינר. ר' שמעון אומר: שמונה פונדיונות, שני פונדיון לדינר.\u0004 אם היתה חסרה \u0003יתר על כן\u0004 — \u0003מוכרה בשויה,\u0004 כשווי המתכת היקרה שבה, ולא לפי ערכה הנקוב.","\u0003עד כמה תיפחת\u0004 המטבע \u0003ויהא רשאי לקיימה\u0004 כמטבע? \u0003בסלע\u0004 אם פחת ערכה — \u0003עד שקל\u0004 שהוא מחצית הסלע. \u0003בדינר\u0004 — \u0003עד רובע,\u0004 ואם פחתה יותר מחצי ערכה \u0003פחות מכן איסר\u0004 — \u0003אסור להוציאה\u0004 להשתמש בה למסחר. ו\u0003הרי זה לא ימכרנה לא לתגר ולא לחרם\u0004 (אדם אלים) \u0003ולא להרג\u0004 (לרוצח) — \u0003מפני שמרמין בה את אחרים\u0004 או כופים אחרים לקבל מהם. \u0003אלא יקבנה\u0004 (יעשה בה נקב) \u0003ויתלנה\u0004 כתכשיט \u0003בצואר בנו או בצואר בתו.\u0004","ובביאור הדברים, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בסלע\u0004 — \u0003עד שקל, בדינר\u0004 — \u0003עד רובע.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[מה\u0006 מדוע, \u0005שונה]\u0006 הדין ש\u0003סלע עד שקל\u0004 שהוא מחצית, \u0003ומאי שנא\u0004 \u0005[במה שונה]\u0006 שאומר \u0003בדינר עד רובע?\u0004","\u0003אמר אביי: מאי\u0004 \u0005[מה הוא]\u0006 \u0003\"רובע\" דקתני\u0004 \u0005[ששנה]\u0006 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003רובע שקל\u0004 שהוא מחצית הדינר ולא רבע ממנו. \u0003אמר רבא: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 דבר זה מן הלשון, \u0003דקא תני\u0004 \u0005[ששנה]\u0006 \u0003\"רובע\", ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"רביע\".\u0004 ומעירים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים: \u0003למה ליה למתלייה\u0004 \u0005[לו לתלות]\u0006 את הדין של ה\u0003דינר\u0004 שחסר בדין ה\u0003שקל,\u0004 ולומר \"עד רובע\" שמשמעו רבע שקל, ומדוע אינו אומר בפשטות: חצי דינר? ומשיבים: \u0003מלתא אגב אורחיה קא משמע לן\u0004 \u0005[דבר בדרך אגב השמיע לנו],\u0006 \u0003דאיכא\u0004 \u0005[ש\u0006פעמים \u0005יש]\u0006 \u0003דינר דאתי\u0004 \u0005[ש\u0006הוא \u0005בא]\u0006 \u0003משקל,\u0004 כלומר, שהיה דינר זה שקל, ופחת עד מחציתו ואינו אלא דינר.","ומעירים: \u0003מסייע\u0004 לו הדבר \u0003לר' אמי.\u0004 ש\u0003אמר ר' אמי: דינר הבא משקל\u0004 — \u0003מותר לקיימו\u0004 ולהשתמש בו כדינר, לפי שלא יבואו לטעות בו, שלפי גודלו וצורתו אין בו מקום לטעות. ואולם \u0003דינר הבא מסלע\u0004 שפחת הסלע עד כדי רבע משקלו — \u0003אסור לקיימו\u0004 כדינר, שלפי שהיה קודם מטבע בגודל של כסלע עלולים לטעות בו ולחשוב שהוא גדול מדינר.","שנינו שאם היה \u0003פחות מכן איסר\u0004 — \u0003אסור להוציאה.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה פירוש הדברים? \u0003אמר אביי, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003פחתה סלע יותר מכדי אונאה\u0004 כדי \u0003איסר\u0004 — \u0003אסור. אמר\u0004 לו \u0003רבא: אי הכי\u0004 \u0005[אם כך]\u0006 שהיה זה יותר מכדי אונאה — \u0003אפילו משהו נמי\u0004 \u0005[גם כן]\u0006 אסור, ולא רק איסר! \u0003אלא אמר רבא,\u0004 כך יש להבין: \u0003פחתה סלע\u0004 כדי שיעור של \u0003איסר לדינר\u0004 — \u0003אסור, וסתמא\u0004 \u0005[סתם]\u0006 ברייתא זו היא \u0003כ\u0004דעת \u0003ר' מאיר\u0004 שאונאה היא באיסר לדינר.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003סלע שנפסלה\u0004 מלשמש כמטבע \u0003והתקינה שיהא שוקל בה משקלות\u0004 — \u0003טמאה\u0004 משום שהיא כלי כשאר המשקלות ומקבלת טומאה. \u0003עד כמה תיפחת ויהא רשאי לקיימה? לסלע\u0004 — \u0003שני דינרים\u0004 (מחצית מערכה), פחתה \u0003פחות מכן\u0004 — \u0003יקוץ\u0004 (יקצוץ) וישתמש במתכת, אבל לא במטבע.","ושואלים: אם \u0003פחתה\u0004 \u0003יתר על כן מאי\u0004 \u0005[מה\u0006 יהא הדין\u0005]?\u0006 \u0003אמר רב הונא: פחות מכן\u0004 — \u0003יקוץ. יתר על כן\u0004 — גם כן \u0003יקוץ. ר' אמי אמר: פחות מכן\u0004 — \u0003יקוץ, יתר על כן\u0004 — \u0003יקיים,\u0004 מפני שאי אפשר לטעות עוד במטבע זו שהתקטנה עד כדי כך.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006"],["\u0003יתר על כן מוכרה בשויה, מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003שפחתה יותר מכדי אונאתה?\u0004 ודוחים: \u0003לא, \"יתירה\"\u0004 כוונתו: יתרה בערכה, \u0003דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא פחתה בכדי אונאתה,\u0004 וזו היא ש\u0003מוכרה בשויה.\u0004","\u0003מתיבי\u0004 \u0005[מקשים]:\u0006 \u0003עד כמה תיפחת\u0004 מטבע, \u0003ויהא רשאי לקיימה? בסלע\u0004 שנפחת — \u0003עד שקל\u0004 (מחצית ערכו). \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003דפחית פורתא פורתא\u0004 \u0005[שפחת\u0006 הסלע \u0005מעט מעט],\u0006 ונמצא שאף שפחת עד כדי חצי שוויו (שהוא הרבה יותר מכדי אונאה) יכול לקיימו, ואין חוששים לטעות! ודוחים: \u0003לא,\u0004 מדובר שם \u0003דנפיל לנורא ואפחות בחדא זימנא\u0004 \u0005[שנפל לאש ונפחת בפעם אחת]\u0006 ולכן אין מקום לטעות.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 שמטבע שנפחתה הרבה, אם ירצה \u0003יקבנה ויתלנה בצואר בנו, או בצואר בתו. ורמינהו\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במקום אחר שמטבע שפחתה, \u0003לא יעשנה משקל בין משקלותיו, ולא יזרקנה בין גרוטותיו\u0004 (שברי מתכת), \u0003ולא יקבנה ויתלנה בצואר בנו ובצואר בתו,\u0004 שמא יבואו להשתמש בה בטעות. \u0003אלא, או ישחוק, או יתוך\u0004 \u0005[יתיך]\u0006 את המתכת לחתיכות, \u0003או יקוץ או יוליך\u0004 ויזרוק אותה \u0003לים המלח!\u0004","\u0003אמר ר' אלעזר, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב הונא אמר ר' אלעזר: לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003כאן\u0004 כשמותר — כשנקב את המטבע \u0003באמצע,\u0004 שאז אין עוד מקום לטעות, \u0003כאן\u0004 — \u0003מן הצד,\u0004 שיש לחשוש שמא יבוא אדם ויחתוך את המטבע מסביב, וישתמש בה, ויטעה בה את הבריות.","שנינו במשנה: \u0003עד מתי מותר להחזיר\u0004 מטבע פחותה? \u0003בכרכים\u0004 — \u0003עד שיראה לשולחני, בכפרים\u0004 — \u0003עד ערבי שבתות.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 הדין \u0003ב\u0004ענין \u0003סלע דמפליג\u0004 \u0005[שמחלק]\u0006 בין כרך לכפר, \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 הדין \u0003ב\u0004ענין \u0003טלית דלא מפליג\u0004 \u0005[שאינו מחלק]?\u0006","\u0003אמר אביי: כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן במשנתנו]\u0006 \u0003ב\u0004ענין \u0003טלית\u0004 — \u0003בכרכין תנן\u0004 \u0005[שנינו]\u0006 אבל בכפר יכול להחזיר לאחר זמן. \u0003רבא אמר:\u0004 יש הבדל בין טלית ומטבע. \u0003טלית, כל איניש קים ליה בגוה\u0004 \u0005[אדם יודע בה]\u0006 בערכה ובשוויה, ומן הסתם יאמרו לו מיד שהוטעה. \u0003סלע, כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003כל איניש קים ליה בגוה\u0004 \u0005[אדם יודע בה]\u0006 \u0003אלא\u0004 ה\u0003שולחני,\u0004 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003בכרכים דאיכא\u0004 \u0005[שיש]\u0006 \u0003שולחני\u0004 במקום — זמנו \u0003עד שיראה לשולחני. בכפרים דליכא\u0004 \u0005[שאין]\u0006 \u0003שולחני\u0004 — זמנו \u0003עד ערבי שבתות דסלקין לשוקא\u0004 \u0005[שהולכים לשוק]\u0006 ואז מתברר שהסלע אינו שוה כפי ששילמו בעדו.","שנינו במשנה: \u0003ואם היה מכירה\u0004 — \u0003אפילו לאחר שנים עשר חדש\u0004 מקבלה ממנו. ושואלים: \u0003היכא\u0004 \u0005[היכן]\u0006 היה הדבר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003בכרכין\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 שהזמן הוא \u0003עד שיראה לשולחני. אי\u0004 \u0005[אם]\u0006 \u0003בכפרים\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 \u0003עד ערבי שבתות!\u0004","\u0003אמר רב חסדא: מידת חסידות שנו כאן,\u0004 שמקבל אפילו לאחר זמן מרובה. ומקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור את סופה]\u0006 של המשנה: \u0003אין לו עליו אלא תרעומת.\u0004 ונברר: \u0003למאן\u0004 \u0005[למי]\u0006 יש תרעומת? \u0003אי\u0004 \u0005[אם]\u0006 \u0003לחסיד\u0004 שקיבל אותה ממנו לפנים משורת הדין ש\u0003לא קבולי ליקבלה מיניה\u0004 \u0005[יקבל ממנו],\u0006 בחזרה \u0003ולא תרעומת תיהוי ליה\u0004 \u0005[ושלא תהיה לו תרעומת],\u0006 שאם רוצה אדם לנהוג בחסידות יעמוד על חובתו, ומה טעם יתרעם על כך? \u0003אלא\u0004 הכוונה היא \u0003להאיך\u0004 \u0005[לזה]\u0006 ש\u0003קבלה,\u0004 את המטבע, \u0003מיניה\u0004 \u0005[ממנו]\u0006 ומתרעם על שנתן לו אותה, הרי יש לשאול: \u0003ולבתר\u0004 \u0005[ולאחר]\u0006 ש\u0003מקבלה מיניה\u0004 \u0005[ממנו]\u0006 מה \u0003תרעומת תיהוי ליה\u0004 \u0005[תהיה לו]?\u0006","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אחר\u0004 שאינו חסיד, \u0003אף על פי שאין מקבלה הימנו\u0004 — \u0003אין לו עליו אלא תרעומת.\u0004 כלומר, אין לכפות על אחר לקבל מטבע זו, משום שאף שהמטבע היא בערכה, לא כל אדם רוצה להתעסק במטבע שיש בה חשש ופקפוק.","שנינו במשנה שמטבע זו \u0003נותנה למעשר שני, ואינו חושש, שאינו אלא נפש רעה. אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 מלשון משנתנו: \u0003האי מאן דמוקים אזוזי\u0004 \u0005[זה שעומד על המטבעות],\u0006 כלומר, המקפיד שכל מטבע תהיה שלמה, ולא יהא בה פגם כלל, \u0003מיקרי\u0004 \u0005[נקרא]\u0006 \u0003נפש רעה.\u0004 ומעירים: \u0003והני מילי הוא דסגי להו\u0004 \u0005[ודברים אלה\u0006 אמורים \u0005כאשר\u0006 המטבע עדיין \u0005מהלכת,\u0006 נסחרת\u0005],\u0006 שאז העומד על קבלת מטבעות מושלמות אינו אלא נפש רעה.","ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 דבר זה לדעת \u0003חזקיה,\u0004 ש\u0003אמר חזקיה: בא לפורטה,\u0004 אם בא אדם לפרוט מטבע פגומה זו — \u0003פורטה בשויה,\u0004 ומקבל בעדה מעט פחות פרוטות, לפי החסרון שחסרה. \u0003בא לחללה,\u0004 להשתמש בה לחילול מעשר שני — \u0003מחללה ביפה,\u0004 כאילו היתה מטבע יפה, שלמה.","ומבררים: \u0003מאי קאמר\u0004 \u0005[מה\u0006 בעצם \u0005אמר]?\u0006 ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אף על פי\u0004 ש\u0003כשבא לפורטה\u0004 לפרוטות, \u0003פורטה בשויה,\u0004 שהיא שווה אז פחות מן הערך הנקוב עליה, מכל מקום \u0003כשהוא מחללה\u0004 על מעשר שני — הריהו \u0003מחללה ביפה.\u0004","ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 מכאן ש\u0003סבר חזקיה דמזלזלינן\u0004 \u0005[שמזלזלים אנו]\u0006 \u0003במעשר שני,\u0004 לפדותו שלא בדיוק בשוויו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003חזקיה\u0004 עצמו: \u0003מעשר שני שאין בו שוה פרוטה,\u0004 וכיון שכך אי אפשר לחללו, שאין מחללים על פחות משווה פרוטה, \u0003אומר: הוא,\u0004 מעשר זה עצמו, \u0003וחומשו,\u0004 שיש להוסיף חומש בשעת חילול מעשר, \u0003מחולל על מעות הראשונות\u0004 על כסף קודם שכבר חיללתי בו מעשר שני קודם לכן. וטעמו — \u0003לפי שאי אפשר לו לאדם לצמצם מעותיו,\u0004 כלומר, לא יתכן שחילול המעשר היה מדוייק בתכלית, ומן הסתם הוסיף קצת על שווי המעשר, ולכן יכול לצרף לחשבון זה עוד כמות קטנה שהיא פחות משווה פרוטה. ומכאן למדים שחזקיה סבור שאין מזלזלים בחילול מעשר שני, שהרי לדעתו מוסיפים עוד עליו!","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ביפה\",\u0004 לא כפי שהבנו, אלא להיפך: \u0003בתורת יפה.\u0004 כלומר, \u0003דתרי זילי לא מזלזלינן ביה\u0004 \u0005[ששני\u0006 אופנים של \u0005זלזול אין מזלזלים בו].\u0006 שאם כי מותר להשתמש במטבע זו לפדיון מעשר, אבל אין מחשיבים את ערכה אלא בשוויה הממשי, ולא על פי הערך הנקוב.","כיון שהוזכרו דברי חזקיה, דנים בהם לגופם. \u0003אמר חזקיה: מעשר שני שאין בו שוה פרוטה, אומר: \"הוא וחומשו מחולל על מעות הראשונות\", לפי שאי אפשר לו לאדם לצמצם מעותיו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך מן המשנה: \u0003התרומה והביכורים\u0004 שאכלם זר (שאינו כהן) \u0003חייבין עליהן מיתה,\u0004 אם אכלם במזיד. ומוסיף \u0003חומש\u0004 אם אכלם בשוגג, שצריך להוסיף ולשלם עוד חמישית כקנס שקצבה התורה."],["\u0003ואסורים\u0004 באכילה \u0003לזרים. והן נכסי כהן,\u0004 שהם נחשבים לכל דבר כרכושו, שרשאי למכור אותם לכהן אחר, או לקדש בהם אשה, \u0003ועולים\u0004 (מתבטלים) אם נתערבו בפירות אחרים, ואינם בטלים ברוב בלבד אלא \u0003באחד ומאה, וטעונין\u0004 לפני אכילתם \u0003רחיצת ידים.\u0004 ואם היה טמא — טבילה \u0003והערב שמש,\u0004 (שאסור בהם עד אחר שתשקע החמה), \u0003הרי\u0004 דינים \u0003אלו בתרומה ובכורים, מה שאין כן במעשר.\u0004","ונדייק: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מה שאין כן במעשר\"\u0004 — \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מלמד \u0003מכלל\u0004 הדברים שה\u0003מעשר בטיל ברובא\u0004 \u0005[בטל ברוב]?\u0006 \u0003ו\u0004אולם \u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לדברי \u0003חזקיה,\u0004 אם כן מעשר \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 \u0003דבר שיש לו מתירין.\u0004 שהרי יכול להתיר כמות קטנה של מעשר אגב מעות אחרות, וכלל הוא: כל \u0003דבר שיש לו מתירין\u0004 בכל אופן שהוא, \u0003אפילו באלף לא בטיל\u0004 \u0005[בטל]!\u0006","ודוחים: \u0003וממאי\u0004 \u0005[וממה,\u0006 מדוע\u0005]\u0006 מסיק אתה שכוונת הדברים \u0003\"מה שאין כן במעשר\"\u0004 כוונתו \u0003דבטיל ברובא\u0004 \u0005[שבטל ברוב]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא שהמעשר שונה מתרומה שהוא \u0003לא בטיל\u0004 \u0005[בטל]\u0006 \u0003כלל!\u0004 ומשיבים: \u0003לא מצית אמרת הכי\u0004 \u0005[אין אתה יכול לומר כך],\u0006 שכן ברשימה זו ש\u0003לגבי תרומה, חומרי\u0004 \u0005[את החומרות]\u0006 שב\u0003תרומה\u0004 – \u0003קתני,\u0004 \u0005[שנה]\u0006 \u0003קולי\u0004 \u0005[את הקולות]\u0006 שב\u0003תרומה לא קתני\u0004 \u0005[שנה],\u0006 ומן הסתם כוונת ברייתא זו להדגיש צדדים חמורים שיש בתרומה, לעומת ההקלה שיש במעשר, ולא להיפך. ומקשים: \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 שם: \u0003והן נכסי כהן,\u0004 הרי שמנה לא רק חומרות של תרומה, אלא גם קולי תרומה!","ודוחים: מעיקר הענין \u0003לא סלקא דעתך\u0004 \u0005[\u0006יכול \u0005לעלות על דעתך],\u0006 \u0003דתניא בהדיא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא \u0005מפורשת]:\u0006 \u0003מעשר שני בטיל ברובא\u0004 \u0005[בטל ברוב].\u0006 \u0003ובאיזה מעשר שני אמרו\u0004 — \u0003במעשר\u0004 שני \u0003שאין בו שוה פרוטה, ושנכנס לירושלים ויצא.\u0004 ומעתה נשאל שוב: \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדברי \u0003חזקיה,\u0004 אם כן, \u0003וניחל ליה\u0004 \u0005[ושיחלל אותו]\u0006 \u0003על מעות הראשונות!\u0004 ומשיבים: מדובר כאן באופן שעדיין \u0003לא פריק\u0004 \u0005[פדה]\u0006 אותו אדם את מעשרו, ולכן אין בידו מעות מעשר לצרף להן.","ושואלים: \u0003וניתי מעשר דאית ליה ונצטרפינהו\u0004 \u0005[ויביא מעשר\u0006 אחר \u0005שיש לו ויצטרפנו]!\u0006 ומשיבים: \u0003דאורייתא ודרבנן לא מצטרפי\u0004 \u0005[\u0006דבר \u0005מן התורה ומדברי חכמים אינם מצטרפים]\u0006 יחד. שמן התורה אף מעשר בטל ברוב, ואין לכך עוד קדושה מן התורה, ומעשר גמור שחילל — מן התורה הוא.","ושואלים: \u0003וניתי\u0004 \u0005[ושיביא]\u0006 לשם כך מעשר שני \u0003דמאי,\u0004 שהוא מעיקרו מדברי חכמים, ויצטרפו! ומשיבים: אין עושים כן לכתחילה, \u0003דלמא אתי לאתויי\u0004 \u0005[שמא יבוא להביא]\u0006 מעשר \u0003ודאי.\u0004 לפי שבכל ענין כמעט, נוהגים בדמאי כפי שנוהגים בוודאי.","ושואלים: \u0003וניתי\u0004 \u0005[ושיביא]\u0006 \u0003שתי פרוטות, ונחלל עלייהו\u0004 \u0005[ויחלל עליהן]\u0006 \u0003מעשר\u0004 ששוויו \u0003פרוטה ומחצה,\u0004 \u0003ונחלל\u0004 מעט המעשר \u0003האי\u0004 \u0005[הזה]\u0006 \u0003על\u0004 חצי \u0003הפרוטה\u0004 \u0003היאך יתירא\u0004 \u0005[הזו היתירה].\u0006 ודוחים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי מעשר ששוויו \u0003פרוטה ומחצה, תפסה\u0004 \u0005[תופס],\u0006 ומתחלל על \u0003שתי פרוטות? לא.\u0004 כך הוא הדבר להלכה: שווה \u0003פרוטה\u0004 אחת \u0003תפסה\u0004 \u0005[תופסת]\u0006 קדושה רק כדי \u0003פרוטה,\u0004 \u0003וחצי פרוטה לא תפסה\u0004 \u0005[אינה תופסת]\u0006 כלל. ואם כן \u0003הדר הויא ליה\u0004 \u0005[חוזר\u0006 הדבר \u0005ונעשה]\u0006 הבדל בין \u0003דאורייתא ודרבנן\u0004 \u0005[\u0006דבר \u0005שמן התורה ושמדברי חכמים].\u0006 \u0003ודאורייתא ודרבנן לא מצטרפי\u0004 \u0005[\u0006ודבר \u0005מן התורה ו\u0006של \u0005דברי חכמים אינם מצטרפים].\u0006","ושואלים: אם כן \u0003וניתי\u0004 \u0005[ושיביא]\u0006 \u0003איסר\u0004 שהוא מטבע אחד גדול (בן שמונה פרוטות), ויפדה בו מעשר שני קרוב לערכו, והכל יתחלל יחד! ומשיבים: חוששים אנו \u0003דלמא אתי לאתויי\u0004 \u0005[שמא יבוא להביא]\u0006 \u0003פרוטות,\u0004 ואז לא תתחלל קדושת המעשר על מחצית פרוטה, ונמצא שלא הועיל כלום.","בברייתא שהבאנו נאמר כי מדובר במעשר שני \u0003ושנכנס לירושלים ויצא.\u0004 ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 בכלל צריך לדבר על ביטולו ברוב, \u0003וליהדר ונעייליה\u0004 \u0005[ושיחזור ויכניסנו]\u0006 לירושלים, ויאכלנו שם! ומשיבים: מדובר ב\u0003שנטמא\u0004 מעשר זה חוץ לירושלים. ושואלים: ואם כן \u0003ונפרקיה\u0004 \u0005[ושיפדנו],\u0006 שהרי \u0003אמר ר' אלעזר: מנין למעשר שני שנטמא, שפודין אותו\u0004"],["\u0003אפילו בירושלים\u0004 עצמה שאין מעשר טהור נפדה שם — \u0003שנאמר: \"כי לא תוכל שאתו...\u0004 ונתת בכסף, וצרת הכסף בידך\u0003\"\u0004 (דברים יד, כד–כה). \u0003ואין\u0004 משמעות לשון \u0003\"שאת\" אלא אכילה, שנאמר: \"וישא משאת מאת פניו\"\u0004 (בראשית מג, לד).","\u0003אלא\u0004 לא זה ההסבר, ויש לומר ששם מדובר \u0003בלקוח\u0004 (קנוי) \u0003בכסף מעשר שני,\u0004 שלא היה פרי זה עצמו מעשר, אלא נקנה בכספי מעשר, ושמא אין קדושתו מרובה דייה שתוכל להתחלל שנית. ומקשים: \u0003לקוח בכסף מעשר נמי ליפרקיה\u0004 \u0005[גם כן שיפדנו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הלקוח בכסף מעשר שני שנטמא\u0004 — \u0003יפדה!\u0004 ומשיבים: השיטה בברייתא שלנו היא \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 שהלקוח בכסף מעשר אם נטמא \u0003יקבר,\u0004 שאין יכולים לפדותו.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע למד דווקא\u0005]\u0006 ב\u0003\"יצא\"? אפילו לא יצא נמי\u0004 \u0005[גם כן]\u0006 זה דינו, שהרי לדעתו מיד כשנטמא, כבר אין לו תקנה, \u0003אלא, לעולם\u0004 יש לומר שהמדובר במעשר שני \u0003טהור, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"יצא\"\u0004 — אין משמעו שיצא ממש, אלא \u0003דנפול\u0004 \u0005[שנפלו]\u0006 \u0003מחיצות\u0004 העיר שנהרסה בינתיים חומת ירושלים, שהיא המחיצה שבתוכה אפשר לאכול מעשר. ולפיכך דינו כיוצא.","ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא:\u0004 דין זה שצריך \u0003מחיצה לאכול\u0004 בתוכה הריהו \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 אולם \u0003מחיצות לקלוט\u0004 לענין זה שיחשב דבר מסויים כקלוט בתוך התחום, הן רק \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 \u0003וכי גזרו רבנן\u0004 \u0005[וכאשר גזרו חכמים]\u0006 בענין מחיצות הקולטות את המעשר, לענין יציאה מן התחום, וכשהייה בתוכו הרי זה \u0003כי איתנהו\u0004 \u0005[כאשר ישנן,\u0006 מצויות\u0005]\u0006 ה\u0003מחיצות.\u0004 אבל \u0003כי ליתנהו\u0004 \u0005[כאשר אין]\u0006 \u0003למחיצות\u0004 — \u0003לא גזרו רבנן\u0004 \u0005[חכמים]!\u0006 ומשיבים: \u0003לא פלוג רבנן\u0004 \u0005[חלקו חכמים]\u0006 בדינם, \u0003בין איתנהו\u0004 \u0005[שיש]\u0006 \u0003למחיצות, בין ליתנהו\u0004 \u0005[שאין]\u0006 \u0003למחיצות,\u0004 שכיון שקבעו חכמים דין מחיצה וקליטה — שוב לא חלקו בפרטים, וגזרו בכל מקרה, זו היתה שיטה אחת של הסבר,","ואילו \u0003רב הונא בר יהודה אמר רב ששת: חדא קתני\u0004 \u0005[\u0006דבר \u0005אחד שנינו]\u0006 בברייתא, שאין שם שני פרטים נבדלים, אלא הלכה אחת היא, וכך יש להבינה: \u0003מעשר שני שאין בו שוה פרוטה שנכנס לירושלים ויצא\u0004 שכיון שהוא פחות משוה פרוטה אין בו דרך פדיון. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003וניהדר ונעייליה וניכליה\u0004 \u0005[שיחזירנו ויכניסנו ויאכלנו]!\u0006 ומשיבים: \u0003דנפול\u0004 \u0005[שנפלו]\u0006 ה\u0003מחיצות.\u0004","ושואלים: \u0003ונפרקיה\u0004 \u0005[ושיפדהו]?\u0006 \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבא: מחיצה לאכול דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003מחיצה לקלוט דרבנן\u0004 \u0005[מדברי חכמים],\u0006 \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003גזרו רבנן\u0004 \u0005[חכמים]\u0006 — \u0003כי איתנהו\u0004 \u0005[כאשר ישנן]\u0006 \u0003למחיצות; כי ליתנהו\u0004 \u0005[\u0006ו\u0005כאשר אין]\u0006 \u0003למחיצות\u0004 — \u0003לא גזרו רבנן\u0004 \u0005[חכמים].\u0006 ומשיבים: \u0003לא פלוג רבנן\u0004 \u0005[חלקו חכמים].\u0006","ומעירים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש ענין זה, אם כן \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 מדובר כאשר \u0003אין בו שוה פרוטה? אפילו יש בו נמי\u0004 \u0005[גם כן]\u0006 יהיה זה דינו! ומשיבים: בסגנון \u0003\"לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003\" קאמר\u0004 \u0005[אמר],\u0006 וכך יש להבין: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר בש \u0003יש בו\u0004 שווה פרוטה שדינו \u0003דקלטן ליה\u0004 \u0005[שקולטות אותו]\u0006 ה\u0003מחיצות\u0004 ואינו ניתן להפדות שנית. \u0003אבל אין בו\u0004 שווה פרוטה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא קלטו ליה\u0004 \u0005[יקלטו אותו]\u0006 ה\u0003מחיצות,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף זה המחיצות קלטוהו, ואין לו תקנה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"אם גאל יגאל איש ממעשרו\u0004 חמישיתו יוסף עליו\u0003\"\u0004 (ויקרא כז, לא), ודיוק הלשון: \u0003\"ממעשרו\"\u0004 — \u0003ולא כל מעשרו.\u0004 שלשון זו באה למעט דברים מסויימים; פרט \u0003למעשר שני שאין בו שוה פרוטה,\u0004 שאין לו גאולה (פדיון). \u0003איתמר\u0004 \u0005[נאמר],\u0006 שנחלקו אמוראים בפירוש הלכה זו. \u0003רב אמי אמר:\u0004 הכוונה היא ש\u0003אין בו,\u0004 שהמעשר עצמו אינו \u0003שוה פרוטה.\u0004 ואילו \u0003רב אסי אמר: אין בחומשו.\u0004 שאף אם המעשר עצמו שווה פרוטה, אם החומש שצריך להוסיף עליו אינו שווה פרוטה, אין בו דין פדיון. וכיוצא בזה נחלקו גם חכמים אחרים בבעיה זו. \u0003ר' יוחנן אמר: אין בו. ר' שמעון בן לקיש אמר: אין בחומשו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003מעשר שני שאין בו שוה פרוטה\u0004 — \u0003דיו שיאמר \"הוא וחומשו מחולל על מעות ראשונות\".\u0004","\u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003אין בחומשו\u0004 — \u0003היינו דקתני\u0004 \u0005[זהו\u0006 הטעם \u0005ששנה]\u0006 \u0003\"דיו\",\u0004 ששינה בלשון, ואמר שלמרות הכל דיו בכך, להשמיענו \u0003דאף על גב דבדידיה אית ביה\u0004 \u0005[שאף על פי שהוא בעצמו יש בו]\u0006 שווה פרוטה, \u0003כיון דבחומשיה ליכא\u0004 \u0005[שבחומשו אין]\u0006 — \u0003שפיר\u0004 \u0005[יפה,\u0006 טוב עשה\u0005].\u0006 ודי לו אם יחללנו בתוך מעות מעשר אחרות, או יבליענו בצורה דומה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003\"אין בו\"\u0004 עצמו, \u0003מאי\u0004 \u0005[מה]\u0006 לשון \u0003\"דיו\"?\u0004 הרי מתחילה אין בו ערך חשוב שיהא צד פדיון כלל! ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר, שאין הלשון מדוקדקת על פי שיטה זו.","לגופה של ההלכה בדבר תוספת החומש במעשר ובדינים אחרים, \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: האם \u0003חומשא מלגיו\u0004 \u0005[החומש מבפנים],\u0006 שמחשבים ומוסיפים חמישית ערכו של הדבר הנפדה, \u0003או חומשא מלבר\u0004 \u0005[חומש מבחוץ]\u0006 שהוא רבע ערכו של הדבר הנפדה, אבל הוא חומש של הסכום הכולל ערך הדבר הנפדה והתוספת יחד? \u0003אמר רבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פתרון לדבר ממה ששנינו בברייתא: \u0003הבעלים אומרים בעשרים,\u0004 שהם עצמם מוכנים לקנות או לפדות את ההקדש בעשרים דינר \u0003וכל אדם\u0004 המוכן לקנות, מוכן גם הוא לקנותו \u0003בעשרים\u0004 — \u0003הבעלים קודמין מפני שמוסיפים חומש,\u0004 ונמצא שההקדש מקבל מידם יותר משהציע כל אדם אחר. \u0003אמר אחד: הרי עלי\u0004 סחורה זו \u0003בעשרים ואחד.\u0004"],["\u0003הבעלים נותנין עשרים ושש\u0004 בעל כורחם. כי אם ימכרו לאותו אדם בעשרים ואחת, נמצא ההקדש מפסיד. שהרי הבעלים נותנים בסך הכל יותר כשמצרפים קרן וחומש כאחד. ואם יתן בעל הנכסים רק עשרים ויוסיף חומש, נמצא שקיבל דבר בפחות משוויו, שהרי יש המעריך אותו בעשרים ואחד, על כן נותנים הבעלים כפי שהעריך אותו אדם, ומוסיף על כך את החומש שהוא עצמו היה צריך להוסיף לפי הצעתו שלו (חמשה דינרים), ונמצא שהבעלים נותנים עשרים ושש. וכן אם אמר אחר \u0003עשרים ושנים\u0004 — \u0003הבעלים נותנין\u0004 בעל כורחם \u0003עשרים ושבע.\u0004 שנותנים כמו שנותן אותו אדם, ומוסיפים מה שאמרו לתת בחומש, וכן \u0003עשרים ושלש\u0004 — \u0003הבעלים נותנין עשרים ושמונה.\u0004 אמר \u0003בעשרים וארבע\u0004 — \u0003הבעלים נותנין עשרים ותשע.\u0004","אמר \u0003עשרים וחמש\u0004 — \u0003הבעלים נותנין שלשים\u0004 עד שיגדל הסכום שיציע אחר יותר מקרן וחומש של הבעלים. והכלל הוא \u0003לפי שאין מוסיפין\u0004 הבעלים \u0003חומש על עילוי\u0004 (תוספת המחיר) \u0003של זה,\u0004 אלא מוסיפים חומש רק על מה שהם עצמם הציעו. על כל פנים ברור מחשבונות אלה, כי חומש של עשרים הוא עשרים וחמש, ו\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי הכוונה היא \u0003חומשא מלבר\u0004 \u0005[חומש מבחוץ],\u0006 שהוא רבע מן הסכום הראשוני (הקרן), וחומש מהסכום הכולל. ומסכמים: אכן, \u0003שמע מינה.\u0004","ומעירים: בעיה זו היא \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו בדבר. שכן שנינו ברייתא: מה שנאמר \u0003\"ויסף חמשתו עליו\"\u0004 (ויקרא כז, כז) כוונתו: \u0003שיהא הוא וחומשו\u0004 יחד \u0003חמשה\u0004 (והוא חומש מלבר), אלו \u0003דברי ר' יאשיה. ר' יונתן אומר: חמישיתו\u0004 כוונתו \u0003חומשו של קרן\u0004 (חומש מלגו) ולא חמישית מן הסכום הכולל.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו בדיני חומש: האם \u0003חומש מעכב,\u0004 שאם פדה מעשר שני ולא הוסיף את החומש, האם מעכב בדבר את האכילה, עד שיתן, \u0003או אינו מעכב?\u0004 ותוכן הבעיה: האם נאמר כי דבר השווה \u0003ארבעה, בארבעה פריק\u0004 \u0005[פודה],\u0006 \u0003ואכנפשיה\u0004 \u0005[ומעצמו]\u0006 \u0003מוסיף חומש,\u0004 שהוא תוספת המוטלת על הפודה, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003חומש לא מעכב,\u0004 שהרי החומש הוא כתוספת בלבד. \u0003או דלמא\u0004 \u0005[שמא]\u0006 דבר השווה \u0003ארבעה\u0004 של מעשר, \u0003בחמשה פריק\u0004 \u0005[פודה\u0006 דווקא\u0005],\u0006 ואין הפדיון נתפס בפחות מכן, ולכן \u0003חומש מעכב.\u0004","\u0003אמר רבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו: מעשר שני של \u0003הדמאי,\u0004 שתיקנו חכמים שינהג מספק, כאילו אינו מתוקן — \u0003אין לו חומש,\u0004 שאף שפודהו, אינו חייב בתוספת חומש, \u0003ואין לו ביעור,\u0004 שאין צריך לבערו בסוף שלוש שנים כמעשר שני גמור.","ונלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003קרן יש לו,\u0004 שבכל זאת חייבים לפדות מעשר שני של דמאי, אף שאין חייבים בחומש. ומעתה נברר: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? מסתבר לומר כי חכמים תקנו תקנה זו משום שפדיון \u0003קרן\u0004 עצמה ש\u0003מעכב\u0004 אכילה \u0003בדאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003איתא בדרבנן\u0004 \u0005[\u0006\u0005ישנו\u0006 גם בדמאי \u0005מדברי חכמים].\u0006 \u0003חומש דלא\u0004 \u0005[שאינו]\u0006 \u0003מעכב\u0004 אף \u0003ב\u0004טבל \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003ליתא בדרבנן\u0004 \u0005[איננו\u0006 בדמאי, \u0005ש\u0006הוא \u0005מדברי חכמים].\u0006","ומציעים: \u0003לימא כתנאי\u0004 \u0005[\u0006האם \u0005לומר\u0006 שהיא \u0005כ\u0006מחלוקת \u0005תנאים],\u0006 שכבר דנו בנושא זה? ששנינו: \u0003נתן את הקרן\u0004 כפדיון מעשר, \u0003ו\u0004אולם עדיין \u0003לא נתן את החומש, ר' אליעזר אומר: יאכל. ר' יהושע אומר: לא יאכל. אמר רבי: נראין דברי ר' אליעזר בשבת,\u0004 שמפני כבוד השבת התירו לו לאכול מיד, \u0003ודברי ר' יהושע ב\u0004יומות ה\u0003חול.\u0004","ונדייק מכאן: \u0003מדאמר\u0004 \u0005[ממה שאמר]\u0006 רבי, \u0003נראין דברי ר' אליעזר בשבת מכלל דפליגי\u0004 \u0005[מכאן ש\u0006הם \u0005חלוקים]\u0006 \u0003אפילו בחול.\u0004 ומצד שני \u0003מדאמר\u0004 \u0005[מ\u0006כיון \u0005שאמר],\u0006 \u0003נראין דברי ר' יהושע בחול, מכלל\u0004 הדבר אתה למד \u0003דפליגי\u0004 \u0005[ש\u0006הם \u0005חלוקים]\u0006 \u0003אפילו בשבת.\u0004 ואם כן מחלוקת עקרונית היא זו.","\u0003מאי לאו בהא סברא קמיפלגי\u0004 \u0005[האם לא בסברה זו הם חולקים]:\u0006 ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003חומש לא מעכב,\u0004 ולדעתו עיקר הפדיון הוא בקרן, \u0003ו\u0004אילו \u0003ר' יהושע סבר\u0004 \u0005[סבור]\u0006 ש\u0003חומש מעכב\u0004 את הפדיון.","\u0003אמר רב פפא\u0004 בדחיית ראיה זו: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003חומש לא מעכב\u0004 את הפדיון מן התורה. \u0003והכא\u0004 \u0005[וכאן]\u0006 בשאלה אם \u0003חיישינן לפשיעותא קמיפלגי\u0004 \u0005[חוששים אנו לרשלנות\u0006 ולהזנחה \u0005חולקים הם].\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהושע \u0005סבור]\u0006 \u0003חיישינן לפשיעותא\u0004 \u0005[חוששים אנו לרשלנות\u0006 ולהזנחה\u0005],\u0006 שמא יתרשל ולא יתן את החומש, ולכן אסרו עליו לאכול עד שישלם. \u0003ומר סבר לא חיישינן לפשיעותא\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר, \u0005סבור\u0006 ש\u0005אין אנו חוששים להזנחה],\u0006 ומן הסתם ישלם אחר כך.","\u0003אמר ר' יוחנן:\u0004 אף שנחלקו במעשר שני, \u0003הכל מודים בהקדש,\u0004 שאם נתן את ערכו בלא להוסיף חומש כפדיונו — \u0003שחילל\u0004 וחל הפדיון. והטעם: \u0003הואיל וגזברין\u0004 של ההקדש \u0003תובעין אותו בשוק\u0004 שישלם את החומש, וכיון שיש לחומש תובעים, אין אנו צריכים לחשוש לרשלנות בענין זה, ויכול להשתמש בו מיד.","ותוהים: \u0003ו\u0004כי \u0003בהקדש לא פליגי\u0004 \u0005[נחלקו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בדין הקדש: \u0003נתן את הקרן\u0004 בפדיון, \u0003ולא נתן לו את החומש, ר' אליעזר אומר: חילל, וחכמים אומרים: לא חילל. אמר רבי: נראין דברי ר' אליעזר בהקדש, ודברי חכמים במעשר.\u0004","ונדייק: \u0003מדאמר\u0004 \u0005[מ\u0006כיון \u0005שאמר]\u0006 \u0003נראין דברי ר' אליעזר בהקדש\u0004 — \u0003מכלל\u0004 הדבר אתה למד \u0003דפליג\u0004 \u0005[ש\u0006הוא \u0005חלק]\u0006 \u0003אפילו במעשר.\u0004 וכן \u0003מדקאמר\u0004 \u0005[ממה שאמר]\u0006 \u0003נראין דברי חכמים במעשר\u0004 — \u0003מכלל דאינהו פליגי\u0004 \u0005[מכאן שהם חלוקים]\u0006 \u0003אפילו בהקדש.\u0004 ואם כן בטלו דברי ר' יוחנן!","\u0003אלא אי אתמר, הכי אתמר\u0004 \u0005[אם נאמר, כך נאמר]:\u0006 \u0003אמר ר' יוחנן: הכל מודים בשבת בהקדש שחילל. חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וקראת לשבת ענג\"\u0004 (ישעיה נח, יג) ומשום מצות עונג שבת, הקילו עליו. \u0003ועוד, הואיל וגזברין תובעין אותו בשוק.\u0004","ועוד בענין חומש. \u0003אמר רמי בר חמא: הרי אמרו\u0004 כי \u0003הקדש אינו מתחלל על הקרקע, דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 בגאולת שדה הקדש \u0003\"ונתן הכסף וקם לו\"\u0004 (ראה ויקרא כז, יט). משמע: כסף ממש ולא קרקע. אבל יש לשאול: \u0003חומשו\u0004 של הקדש \u0003מהו שיתחלל על הקרקע?\u0004","וכן יודעים אנו כי \u0003תרומה אינה משתלמת אלא מן החולין.\u0004 שאם אכל זר תרומה בשוגג, משלם תמורתה לכהן, לא תרומה אחרת, אלא דווקא חולין. \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]:\u0006 \u0003\"\u0004ואיש כי יאכל קודש בשגגה ויסף חמישיתו עליו \u0003ונתן לכהן את הקדש\"\u0004 (ויקרא כב, יד). לומר: \u0003דבר הראוי להיות קדש,\u0004 כלומר — דבר של חולין, לפי שתרומה אינה ראויה להיעשות קודש. ויש לשאול: \u0003חומשה מהו שישתלם שלא מן החולין\u0004 אלא מתרומה?","ועוד שאלה: \u0003מעשר\u0004 שני \u0003אין מתחלל על האסימון\u0004 (עיגול מתכת דמוי מטבע, שלא טבעו בו צורה), \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 \u0003\"וצרת הכסף בידך\"\u0004 (דברים יד, כה), ודרשו חכמינו: \u0003לרבות כל דבר שיש עליו צורה\u0004 של מטבע. ובכסף בלא צורה אין פודין מעשר. \u0003חומשו מהו שיתחלל על האסימון?\u0004","שאלות אלה לא פתרן רמי בר חמא, אך \u0003אתגלגל מלתא ומטא לקמיה\u0004 \u0005[התגלגל הדבר,\u0006 השאלה, \u0005והגיע לפני]\u0006 \u0003רבא.\u0004 \u0003אמר להו\u0004 \u0005[להם]\u0006 למוסרי השמועה פתרון לשאלה: \u0003אמר קרא\u0004 \u0005[אמר הכתוב]\u0006 \u0003\"עליו\"\u0004 (\"ויסף חמשתו עליו\"), ולשון זו בא ללמד \u0003לרבות חומשו כמותו,\u0004 שדין החומש כדין הקרן, ואין מחלקים בין זה לזה.","\u0003אמר רבינא: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 מעין זה, שלמדנו במשנה: \u0003הגונב תרומה ולא אכלה\u0004 — \u0003משלם תשלומי כפל דמי תרומה,\u0004 ככל גנב שמשלם כפל גניבתו, ומשלם רק דמי תרומה, שהתרומה (לפי שנאכלת רק לכהנים בלבד) זולה מן החולין, ואינו צריך לשלם חולין. אך אם \u0003אכלה\u0004 הגנב — \u0003משלם שני קרנים\u0004 (פעמים קרן) כדין גנב, ומשלם גם \u0003חומש.\u0004 וכך מחלקים את התשלום הזה: \u0003קרן וחומש\u0004 אחד — משלם \u0003מן החולין,\u0004 שמשלם דבר זה ככל זר שאכל תרומה, \u0003והקרן\u0004 הנוספת שחייב הגנב לשלם, משלם \u0003דמי תרומה.\u0004"],["\u0003שמע מינה\u0004 \u0005[למד מכאן],\u0006 כי \u0003חומשו כמותו.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003אמר רבא: גבי\u0004 \u0005[אצל]\u0006 \u0003גזל כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"\u0004והשיב את הגזילה אשר גזל\u0003...וחמשתיו יסף עליו\"\u0004 (ויקרא ה, כג–כד). \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003נתן לו\u0004 לנגזל \u0003את הקרן, ונשבע לו\u0004 במרמה \u0003על החומש,\u0004 שטען שכבר נתן לו, והתברר שלא נתן — \u0003הרי זה מוסיף חומש על\u0004 ה\u0003חומש\u0004 כדין מי שנפטר מחובו על ידי שבועת שקר. וכן אם כפר בחומש זה ונשבע, מוסיף עליו \u0003עד שיתמעט הקרן פחות משוה פרוטה,\u0004 ששוב אין כאן דבר שיש בו מקום לתביעה בבית דין.","וכן \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תרומה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"\u0004ו\u0003איש כי יאכל קדש בשגגה ויסף חמשיתו עליו\"\u0004 (שם כב, יד). \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003האוכל תרומה בשוגג משלם קרן וחומש; אחד האוכל ואחד השותה ואחד הסך\u0004 שמן של תרומה על בשרו, \u0003אחד תרומה טהורה, ואחד תרומה טמאה\u0004 — \u0003משלם חומשה וחומשא דחומשא\u0004 \u0005[וחומש של חומש].\u0006 שאם חזר ואכל אותו חומש, משלם אותו ומוסיף עליו חומש, נמצא שאף בתרומה, החומש נעשה כקרן לענין תוספת חומש עליו. \u0003ואילו גבי\u0004 \u0005[אצל]\u0006 \u0003מעשר\u0004 שני \u0003לא מכתב כתיב\u0004 \u0005[נאמר]\u0006 הדבר בתורה, \u0003ולא מיתנא תנא\u0004 \u0005[שנוי]\u0006 במשנה \u0003ולא איבעויי איבעיא לן\u0004 \u0005[נשאל לנו\u0006 על ידי האמוראים\u0005].\u0006","ועוד בעיה: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003הקדש כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ואם המקדיש יגאל את ביתו, ויסף חמישית כסף ערכך\u0004 עליו\u0003\"\u0004 (שם כז, טו). \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003הפודה את הקדשו\u0004 שהוא עצמו הקדיש — \u0003מוסיף חומש.\u0004 הרי \u0003חומשא תנן\u0004 \u0005[חומש\u0006 עצמו \u0005שנינו],\u0006 \u0003חומשא דחומשא\u0004 \u0005[חומש על חומש]\u0006 \u0003לא תנן\u0004 \u0005[שנינו].\u0006 \u0003מאי\u0004 \u0005[מה\u0006 דינו \u0005]?\u0006 וצדדי השאלה: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תרומה כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויסף\", גבי\u0004 \u0005[אצל]\u0006 \u0003קדש נמי\u0004 \u0005[גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"ויסף\",\u0004 ואם כן צריך להוסיף גם בהקדש חומש על חומש,","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תרומה כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויסף\",\u0004 ואת ההלכה בענין חומש לחומש למדים כך: \u0003אי שקלת ליה\u0004 \u0005[אם לוקח אתה את]\u0006 ה\u0003וי\"ו\u0004 של המלה \u0003\"ויסף\",\u0004 \u0003ושדית ליה\u0004 \u0005[ואתה מטיל,\u0006 מוסיף \u0005אותו]\u0006 \u0003על\u0004 המלה \u0003\"חמשיתו\",\u0004 \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 נקרא כאילו היה כתוב \u0003\"חמישיתיו\"\u0004 (בעצם \"חמישיתוו\" והו\"ו הכפולה נקראת איפוא כסימן ריבוי) כמו בגזל, ואולם \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003הקדש כתיב\u0004 \u0005[נאמר]\u0006 רק \u0003\"ויסף חמישית\".\u0004 ואם כן \u0003אף על גב דכי שקלת ליה\u0004 \u0005[אף על פי שאם תיקח]\u0006 את ה\u0003וי\"ו\u0004 של ה\u0003\"ויסף\", ושדית ליה\u0004 \u0005[ותטיל אותו]\u0006 \u0003על\u0004 המלה \u0003חמישית,\u0004 \u0003סוף סוף הוה ליה\u0004 \u0005[הרי הוא]\u0006 נקרא רק \u0003\"חמשתו\"\u0004 בלשון יחיד, ולא \"חמישיתיו\", ואם כן מה הדין?","ומציעים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו,\u0006 תיפתר הבעיה\u0005]\u0006 מטעם אחר: \u0003דהוה ליה\u0004 \u0005[שהריהו\u0006 נעשה\u0005]\u0006 כ\u0003הקדש שני.\u0004 שכן בכל מקום, אם היה לו דבר של הקדש, וחילל אותו על דבר אחר, אף שהשני נתפס כקדושה, הריהו הקדש שני, ואין בו כל דיני הקדש. \u0003ואמר ר' יהושע בן לוי:\u0004 על \u0003הקדש ראשון מוסיף חומש, על הקדש שני אין מוסיף חומש! אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפי לרבינא: הכי\u0004 \u0005[כך]\u0006 \u0003אמר רבא:\u0004 \u0003חומש כתחילת הקדש דמי\u0004 \u0005[נחשב],\u0006 ולא כהקדש שני.","ושואלים: אם כן \u0003מאי הוה עלה\u0004 \u0005[מה היה עליה],\u0006 על שאלה זו? \u0003אמר רב טביומי משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ויסף חמישית כסף ערכך\"\u0004 (שם), \u0003מקיש\u0004 (משווה) הכתוב את \u0003חומשו לכסף ערכו. מה\u0004 על \u0003כסף ערכו\u0004 שהוא ממיני ההקדש, \u0003מוסיף חומש\u0004 — \u0003אף\u0004 על \u0003כסף חומשו נמי\u0004 \u0005[גם כן]\u0006 \u0003מוסיף חומש.\u0004 ונפתרה איפוא שאלתו של רבא.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר שהזכרנו, \u0003אמר ר' יהושע בן לוי: על הקדש ראשון\u0004 — \u0003מוסיף חומש, ועל הקדש שני אין מוסיף חומש. אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהושע בן לוי\u0004 — לפי ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ואם המקדיש יגאל את ביתו,\u0004 ויסף חמישית כסף ערכך\u0003\"\u0004 (שם), יש לדייק בלשון: \u0003המקדיש, ולא המתפיס.\u0004 שרק בהקדש הראשון קיים דין זה, אבל לא כשמתפיס בהקדש זה דבר אחר.","מסופר: \u0003תני תנא קמיה\u0004 \u0005[שנה\u0006 חוזר \u0005המשניות לפני]\u0006 \u0003ר' אלעזר,\u0004 נאמר: \u0003\"ואם בבהמה הטמאה, ופדה בערכך\"\u0004 (שם כז), \u0003מה בהמה טמאה מיוחדת, שתחילתה הקדש, וכולה לשמים,\u0004 שהרי לאחר שהוקדשה, אין בה כל הנאה עוד לבעלים או לאחרים, \u0003ומועלין בה, אף כל שתחילתה הקדש, וכולה לשמים\u0004 — \u0003מועלין בה.\u0004","\u0003אמר ליה\u0004 \u0005[אמר לו]\u0006 \u0003ר' אלעזר לתנא\u0004 \u0005[לחוזר המשניות]:\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שנאמר שם בברייתא: \u0003כולה לשמים\u0004 — הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003קדשים קלים\u0004 (כגון שלמים), \u0003כיון דאית להו\u0004 \u0005[שיש להם]\u0006 \u0003לבעלים\u0004 חלק \u0003בגוייהו\u0004 \u0005[בהם]\u0006 שהרי הם אוכלים מהם, לכן \u0003לית בהו\u0004 \u0005[אין בהם]\u0006 \u0003מעילה.\u0004 \u0003אלא\u0004 מה שאמר \u0003\"תחילת הקדש\" למעוטי מאי\u0004 \u0005[למעט את מה]?\u0006 וכי \u0003תחילת הקדש הוא דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003מעילה,\u0004 ואילו \u0003סוף הקדש לית ביה\u0004 \u0005[אין בו]\u0006 \u0003מעילה?!\u0004 והרי הקדש גמור הוא! \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לענין חומש קאמרת\u0004 \u0005[אומר אתה],\u0006 וכדברי \u0003ר' יהושע בן לוי,\u0004 שהכוונה איננה לענין מעילה ממש, אלא לגבי דין החומש, אם חייבים להוסיף בפדיונו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין, הכי קאמינא\u0004 \u0005[כן, כך אמרתי],\u0006 כלומר, זו היא באמת כוונת הדברים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרבינא,\u0004 לגבי אותה ברייתא: וכי \u0003בהמה טמאה בתחילת הקדש איתא\u0004 \u0005[ישנה],\u0006"],["\u0003באמצע הקדש,\u0004 כלומר, בהקדש שני, שמשתמש בה כדי לחלל עליה הקדש אחר, \u0003ליתא\u0004 \u0005[איננה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הטעם הוא \u0003לפי שאינה בסוף הקדש.\u0004 שהרי בהמה טמאה בסופו של דבר איננה נשארת בקדושה, שכן כשלעצמה אינה ראויה לא לקרבן, ולא לבנין המקדש, אלא פודים אותה, ומשתמשים בדמיה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: באמצע הקדש מיהא איתא\u0004 \u0005[על כל פנים ישנה],\u0006 אם כן, \u0003ולוסיף נמי\u0004 \u0005[ושיוסיף\u0006 עליה \u0005גם כן]\u0006 \u0003חומש!\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי הוא כסוף הקדש, מה סוף הקדש אינו מוסיף\u0004 עליו \u0003חומש\u0004 (שהרי אין סוף הקדש בבהמה טמאה), \u0003אף אמצע הקדש אינו מוסיף\u0004 עליו \u0003חומש.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא: מאי חזית דמדמית ליה\u0004 \u0005[מה ראיתי שאתה מדמה זאת]\u0006 \u0003לסוף הקדש?\u0004 \u0003נדמייה\u0004 \u0005[נדמה זאת]\u0006 \u0003לתחילת הקדש! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 ש\u0003לסוף הקדש הוה ליה לדמויי\u0004 \u0005[היה לו לדמות],\u0006 \u0003שכן\u0004 הוא לומד דבר \u0003נתפס\u0004 בקדושה מדבר \u0003נתפס\u0004 בקדושה, ולא קדושה ראשונה. ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003לתחילת הקדש הוה ליה לדמויי\u0004 \u0005[היה לו לדמות]\u0006 \u0003שכן\u0004 ילמד \u0003דבר שיש אחריו קדושה\u0004 (באמצע הקדש) \u0003מדבר שיש אחריו קדושה!\u0004","ומשיבים: יש להסביר זאת \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רבא\u0004 לענין אחר, שמה שנאמר \u0003\"העלה\"\u0004 (ויקרא ו, ב), ה' הידיעה באה ללמד כי הכוונה היא: \u0003עולה ראשונה. הכי נמי\u0004 \u0005[כך גם כן]\u0006 שנאמר כאן \u0003\"הטמאה\"\u0004 (שם כז, כז) כוונתו \u0003טמאה ראשונה,\u0004 שהיתה תחילת הקדש, ולא באמצע הקדש.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יהושע בן לוי,\u0004 אמר: \u0003\"פרה זו תחת פרה\u0004 זו \u0003של הקדש\",\u0004 או שאמר \u0003\"טלית זו תחת טלית\u0004 זו \u0003של הקדש\"\u0004 — הרי \u0003הקדשו פדוי, ויד הקדש על העליונה,\u0004 שאם הדבר שמחלל בהקדש שווה כנגד ההקדש או יותר — הרי הוא להקדש. ואם שווה פחות — יצטרך להוסיף ולהשלים דמי ההקדש.","אם אמר: \u0003\"פרה זו בחמש סלעים תחת פרה של הקדש\",\u0004 או שאמר \u0003\"טלית זו בחמש סלעים תחת טלית של הקדש\"\u0004 — \u0003הקדשו פדוי,\u0004 גם אם ערך ההקדש גדול יותר, אף כי יצטרך אז להשלים. \u0003על הקדש ראשון מוסיף חומש, על הקדש שני אין מוסיף חומש.\u0004 הרי ששנינו במפורש כדברי ר' יהושע בן לוי.","שיעורה של \u0003האונאה\u0004 הוא \u0003ארבעה כסף,\u0004 כלומר, ארבע מעות לכל סלע (שיש בו ארבעה דינרים, עשרים וארבע מעות). \u0003והטענה\u0004 בבית דין, כלומר, הסכום הקטן ביותר שיכול אדם לטעון עליו, כדי לחייב את הנתבע בשבועה היא: \u0003שתי כסף. ו\u0004אולם \u0003ההודאה,\u0004 כשהודה הנתבע במקצת הטענה, אפילו ב\u0003שוה\u0004 \u0003פרוטה.\u0004","וכיון שהזכרנו פרוטה זו, אומרים: \u0003חמש פרוטות הן\u0004 בהלכה: \u0003ההודאה שוה פרוטה, והאשה מתקדשת בשוה פרוטה, והנהנה בשוה פרוטה מן ההקדש\u0004 — \u0003מעל\u0004 וחייב להביא קרבן, \u0003והמוצא שוה פרוטה חייב להכריז, והגוזל את חבירו שוה פרוטה ונשבע לו\u0004 שלא גזל ממנו, כאשר חוזר בתשובה ומחזיר את הגזילה, \u0003יוליכנו אחריו\u0004 להחזיר את הגזילה \u0003אפילו למדי\u0004 הרחוקה, שבאופן זה אינו יכול להחזיר על ידי שליח, אלא לנגזל עצמו.","שואלים: הלא כבר \u0003תנינא חדא זימנא\u0004 \u0005[שנינו\u0006 דבר זה \u0005פעם אחת]:\u0006 \u0003האונאה ארבעה כסף מעשרים וארבעה\u0004 דינר \u0003כסף לסלע, שתות\u0004 \u0005[ששית]\u0006 \u0003למקח!\u0004 ומשיבים: \u0003הטענה שתי כסף וההודאה שוה פרוטה אצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005],\u0006 שדבר זה לא שנינו, ובדרך אגב הוזכרה גם ההונאה.","ושואלים: \u0003הא נמי תנינא\u0004 \u0005[הרי גם\u0006 את \u0005זו שנינו]\u0006 במקום אחר: \u0003שבועת הדיינים\u0004 באופן זה היא נעשית: \u0003הטענה שתי כסף וההודאה שוה פרוטה!\u0004 ומשיבים: אכן, גם את זה שנינו, ואולם \u0003סיפא אצטריכא ליה\u0004 \u0005[הסוף\u0006 של המשנה \u0005הוצרך לו]\u0006 שיש בו דבר חדש \u0003דקתני\u0004 \u0005[ששנה]:\u0006 \u0003חמש פרוטות הן.\u0004","שנינו במשנה: \u0003חמש פרוטות הן,\u0004 ומנינו פרוטות שמוזכרות בענייני הלכה שונים. ושואלים: \u0003וליתני נמי\u0004 \u0005[ושישנה גם כן]\u0006 \u0003האונאה פרוטה,\u0004 כלומר, שאין הונאה עצמה אלא בפרוטה. \u0003אמר רב כהנא: זאת אומרת אין אונאה לפרוטות,\u0004 שאם לא היה סכום ההונאה מטבע כסף (שהקטן שבהם הוא איסר בן שמונה פרוטות) אין בכך משום הונאה.","\u0003ולוי אמר: יש אונאה\u0004 אפילו \u0003לפרוטות. וכן תני\u0004 \u0005[שנה]\u0006 \u0003לוי במתניתיה\u0004 \u0005[במשניות שלו]\u0006 שלוי סידר בעצמו קובץ משניות במקביל למשנה (כעין התוספתא) ושם שנה: \u0003חמש פרוטות הן: האונאה פרוטה, וההודאה פרוטה, וקדושי אשה בפרוטה, וגזל בפרוטה, וישיבת הדיינין בפרוטה,\u0004 שמי שיש לו טענה על חבירו בדין ממונות בפרוטה יכול להביאו לפני הדיינים והם צריכים לדון בנושא זה.","ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו,\u0006 במשנתנו\u0005]\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא קתני\u0004 \u0005[שנה]\u0006 \u0003ישיבת הדיינים?\u0004 ומשיבים: כבר \u0003תנא ליה\u0004 \u0005[שנה לו]\u0006 \u0003גזל\u0004 בפרוטה, וכל טענות שטוען על חבירו ממיני הגזל הם.","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003לא תני\u0004 \u0005[שנה]\u0006 \u0003גזל וקתני\u0004 \u0005[ושנה]\u0006 גם \u0003אבידה,\u0004 הרי שחוזר ומפרט את הדין הכללי, שיש דיני ממונות של שווה פרוטה! ומשיבים: \u0003הנך אצטריכא ליה\u0004 \u0005[\u0006דברים \u0005אלה היו צריכים לו]\u0006 לשנות כל אחד לחוד לפי שיש בהם חידוש, מה ששנה \u0003גזל\u0004 מלמדנו לא רק שהוא בשווה פרוטה אלא ש\u0003הגוזל מחבירו שוה פרוטה ונשבע לו יוליכנו אחריו ואפילו\u0004 למקום רחוק, \u0003למדי.\u0004 וכן החידוש לענין \u0003אבידה\u0004 — ש\u0003המוצא אבידה שוה פרוטה חייב להכריז, ואף על גב דזל\u0004 \u0005[ואף על פי שהוזל]\u0006 אחר כך ערך האבידה ושוב אינה שווה פרוטה. ומשום חידושים אלה פירט את שני אלה.","ושואלים: \u0003ולוי, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא תני\u0004 \u0005[שנה]\u0006 \u0003אבידה בפרוטה?\u0004 ומשיבים: הלא \u0003תנא ליה\u0004 \u0005[שנה]\u0006 כבר \u0003גזל,\u0004 ואבידה שאין משיבים דינה כגזל.","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003לא קתני\u0004 \u0005[שנה]\u0006 \u0003גזל וקתני\u0004 \u0005[ושנה]\u0006 גם כן \u0003ישיבת הדיינין,\u0004 נמצא שאינו נמנע מפירוט יתר, אף שאינו צריך כל כך! ומשיבים: \u0003ישיבת הדיינין אצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 במיוחד לשנותה, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 מדברי \u0003רב קטינא,\u0004 ש\u0003אמר רב קטינא: בית דין נזקקין\u0004 לטענות \u0003אפילו לפחות משוה פרוטה,\u0004 שכל הטוען על חבירו שעשה לו עוול יכול להתדיין על כך בפני הדיינים.","ושואלים: \u0003ולוי מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא קתני\u0004 \u0005[שנה]\u0006 \u0003הקדש\u0004 שאף בו יש דין מעילה החל בשווה פרוטה? ומשיבים: \u0003ב\u0004דיני \u0003חולין קמיירי\u0004 \u0005[הוא עוסק]\u0006 ואילו \u0003ב\u0004דיני \u0003קדשים לא קמיירי\u0004 \u0005[אינו עוסק]\u0006 ולכן לא הביא כל דבר השייך לקדשים.","ושואלים מצד אחר: \u0003אלא\u0004 ה\u0003תנא דידן\u0004 \u0005[שלנו],\u0006 במשנתנו \u0003דקא מיירי\u0004 \u0005[שעוסק]\u0006 \u0003בקדשים\u0004 \u0003נתני\u0004 \u0005[שישנה]\u0006 גם \u0003מעשר בפרוטה!\u0004 ומשיבים: סבר תנא זה \u0003כמאן דאמר\u0004 \u0005[\u0006כדעת \u0005מי שאומר]\u0006 \u0003אין בחומשו פרוטה.\u0004 כלומר, שאין חיוב במעשר עד שיהיה שווה לפחות ארבע פרוטות. ושואלים: אם כן \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003חומש מעשר בפרוטה!\u0004 ומשיבים: \u0003בקרנא קא מיירי\u0004 \u0005[בקרן\u0006 עצמה \u0005הוא עוסק],\u0006 \u0003ב\u0004דיני \u0003חומש לא קא מיירי\u0004 \u0005[איננו עוסק].\u0006","\u0003גופא,\u0004 לגופם של דברים שהזכרנו. \u0003אמר רב קטינא: בית דין נזקקין אפילו ל\u0004טענה של \u0003פחות משוה פרוטה. מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא:\u0004 הלא שנינו, על הכתוב \u0003\"ואת אשר חטא מן הקדש ישלם\"\u0004 (ויקרא ה, טז),"],["\u0003לרבות פחות משוה פרוטה להישבון\u0004 (להשבה) שיש להחזיר לקודש, אפילו אם מעל ולקח כל שהוא. ונדון מכאן: \u0003לקדש\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל להדיוט\u0004 (סתם אדם) — \u0003לא,\u0004 משמע שאין חובת השבה חלה על פחות משווה פרוטה!","\u0003אלא, אי אתמר הכי אתמר\u0004 \u0005[אם נאמר, כך נאמר\u0006 הדבר\u0005],\u0006 \u0003אמר רב קטינא: אם הוזקקו בית דין ל\u0004דין של \u0003שוה פרוטה\u0004 — גומרין ופוסקים בסוף \u0003אפילו\u0004 אם בינתים נתמעט הערך והוא \u0003פחות משוה פרוטה.\u0004 כי \u0003תחילת הדין בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהא זה \u0003פרוטה,\u0004 ואילו \u0003גמר הדין לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהא שווה \u0003פרוטה.\u0004","כיון שבמשנה הקודמת הובאה מחרוזת דינים בנושאים שונים שיש להם צד משותף אחד, מביאים גם במשנה זו הלכות אחרות שיש להן דינים דומים. \u0003חמשה חומשין הן,\u0004 שבחמשה דברים יש להוסיף חומש על ערך החפץ עצמו \u0003אלו הן\u0004: זר \u0003האוכל תרומה\u0004 גדולה, או \u0003תרומת מעשר\u0004 שנותנים הלויים (מעשר מן המעשר) לכהן, או \u0003תרומת מעשר של דמאי,\u0004 או \u0003את\u0004 \u0003החלה\u0004 או את \u0003הבכורים\u0004 — \u0003מוסיף חומש.\u0004 \u0003והפודה נטע רבעי\u0004, פירות אילנות בשנה הרביעית לנטיעתם, או את ה\u0003מעשר שני שלו\u0004 עצמו — \u0003מוסיף חומש. הפודה את הקדשו\u0004 שהוא עצמו הקדיש — \u0003מוסיף חומש, הנהנה שוה פרוטה מן ההקדש\u0004 — \u0003מוסיף חומש, והגוזל את חבירו שוה פרוטה ונשבע לו\u0004 לשקר — \u0003מוסיף חומש.\u0004","\u0003אמר רבא: קשיא ליה\u0004 \u0005[היה קשה לו]\u0006 \u0003לר' אלעזר,\u0004 על ששנו פה \u0003תרומת מעשר של דמאי,\u0004 כיון שכל הפרשת מעשר מן הדמאי אינה אלא מתקנת חכמים \u0003וכי עשו חכמים חיזוק לדבריהם כשל תורה\u0004 שיוסיף גם חומש?","\u0003אמר רב נחמן אמר שמואל: הא מני\u0004 \u0005[זו\u0006 שיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר\u0004 ש\u0003עשו חכמים חיזוק לדבריהם כשל תורה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 שליח \u0003המביא גט ממדינת הים, נתנו לה\u0004 לאשה \u0003ולא אמר לה\u0004 כתקנת חכמים \u0003\"בפני נכתב ובפני נחתם\"\u0004 הגט — מי שנשא גרושה זו \u0003יוציא\u0004 (יגרש) את האשה בגט, \u0003והולד\u0004 שנולד מנישואין אלו \u0003ממזר,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 אף על פי שלא עשה כדין מכל מקום \u0003אין הולד ממזר.\u0004 אלא \u0003כיצד יעשה? יטלנו\u0004 את הגט \u0003ממנה\u0004 (מהאשה) \u0003ויחזור ויתננו לה בפני שנים, ויאמר לה: \"בפני נכתב ובפני נחתם\".\u0004","ותוהים: \u0003ו\u0004לדעת \u0003ר' מאיר, משום\u0004 ש\u0003לא\u0004 \u0003אמר לה \"בפני נכתב ובפני נחתם\",\u0004 למרות שהיה הגט כשר ונעשה כתיקונו, \u0003יוציא והולד ממזר?!\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003ר' מאיר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר רב המנונא משמיה\u0004 \u0005[משמו\u0006 של \u0003עולא, אומר היה ר' מאיר: כל המשנה ממטבע שטבעו חכמים בגיטין\u0004 בלשון או בנוסח, אם נשא אשה בגט כזה \u0003יוציא והולד ממזר.\u0004 ולענייננו למדנו שר' מאיר עשה חיזוק לתקנות חכמים כאילו היו דברי תורה.","על כלל זה \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ששת,\u0004 שנינו: \u0003מחללין אותו,\u0004 את המעשר השני של דמאי, \u0003כסף על כסף, נחושת על נחושת, כסף על נחושת ונחושת על הפירות, ויחזור ויפדה את הפירות\u0004 הללו בכסף, אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 כיון שפדה בפירות — \u0003יעלו\u0004 ה\u0003פירות ויאכלו בירושלים\u0004 ואי אפשר לפדותם שנית.","וממשיך רב ששת להסביר \u0003ומי מחללינן\u0004 \u0005[האם מחללים אנו]\u0006 \u0003כסף על נחושת? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003סלע\u0004 (מטבע כסף) \u0003של מעשר שני ושל חולין שנתערבו\u0004 זה בזה, \u0003מביא\u0004 בשווי של \u0003סלע מעות\u0004 נחושת, \u0003ואומר: כל מקום שישנה סלע של מעשר שני\u0004 בתוך תערובת כספים זו \u0003מחוללת על מעות הללו, ובורר את היפה שבהן\u0004 (בין המעות) \u0003ומחללו עליה,\u0004 ואז נתפסות המעות השניות בקדושת מעשר, וכל התערובת הראשונה נעשית חולין."],["\u0003מפני שאמרו: מחללין אותו,\u0004 את המעשר, \u0003כסף על נחשת מדוחק, לא שיקיים כן\u0004 שיהיו מעות מעשר מנחושת \u0003אלא שחוזר ומחללן על הכסף. קתני מיהת\u0004 \u0005[שנה על כל פנים]:\u0006 \u0003מחללין מדוחק,\u0004 משמע: \u0003מדוחק\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא מדוחק\u0004 — \u0003לא.\u0004 זה הדין בפדיון מעשר שני מן התורה, ואילו לגבי דמאי שהוא מדברי חכמים, מתיר ר' מאיר לעשות כן לכתחילה!","\u0003אמר רב יוסף: אף על פי שמיקל ר' מאיר בפדיונו,\u0004 מכל מקום \u0003מחמיר הוא באכילתו, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא התירו למכור דמאי\u0004 בלא לעשרו תחילה, \u0003אלא לסיטון בלבד,\u0004 לפי שקונה מאנשים רבים ומוכר בכמויות גדולות, ויצא נפסד אם יפריש. \u0003ובעל הבית\u0004 שקנה מעם הארץ, \u0003בין כך ובין כך,\u0004 בין שמוכר כמויות גדולות או קטנות, בכל מקרה הוא \u0003צריך לעשר,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: אחד הסיטון ואחד בעל הבית\u0004 — \u0003מוכר, ושולח לחבירו ונותן לו במתנה ואינו חושש,\u0004 והאיש שירצה לאכול — הוא יעשר.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבינא\u0004 מצד אחר; שנינו: \u0003הלוקח\u0004 (קונה) \u0003מן הנחתום\u0004 (אופה), \u0003מעשר מן\u0004 הפת \u0003החמה על הצוננת, ומן הצוננת על החמה, ואפילו מדפוסים הרבה,\u0004 אלו \u0003דברי ר' מאיר.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שמעשר \u0003מן הצוננת על החמה\u0004 — אפשר לומר שעושה זאת כשיטת \u0003ר' אילעאי,\u0004 ש\u0003אמר ר' אילעאי: מנין לתורם מן הרעה על היפה שתרומתו תרומה\u0004 — \u0003שנאמר: \"ולא תשאו עליו חטא בהרימכם את חלבו ממנו\"\u0004 (במדבר יח, לב), כלומר, מזהיר הכתוב את הלויים שלא יפרישו מן הגרוע, אבל מכאן אפשר לדייק ש\u0003אם אינו\u0004 נעשה \u0003קדש\u0004 — \u0003נשיאת חטא למה?\u0004 שהרי לא עשה דבר. \u0003מכאן לתורם מן הרעה על היפה, שתרומתו תרומה,\u0004 אף שלא עשה כראוי.","\u0003אלא\u0004 מה שיפריש \u0003אפילו מדפוסים הרבה, ליחוש דלמא אתי לאפרושי\u0004 \u0005[שיחשוש שמא יבוא\u0006 אותו אדם \u0005להפריש]\u0006 \u0003מן החיוב על הפטור, ומן הפטור על החיוב!\u0004 שהרי יתכן שדפוס אחר הוא של אדם שעישר ודפוס אחר של דמאי! ואם כן רואים שרבי מאיר מקל בדמאי שמדברי חכמים.","\u0003אמר אביי: ר' אלעזר שפיר קא קשיא ליה\u0004 \u0005[יפה היה קשה לו],\u0006 \u0003ו\u0004אילו \u0003שמואל לא שפיר קא משני ליה\u0004 \u0005[יפה עונה לו],\u0006 שאין תשובתו של שמואל מספקת. \u0003דקשיא ליה\u0004 \u0005[שקשה\u0006 היה \u0005לו]\u0006 \u0003לר' אלעזר:\u0004 כיצד מחמיר ר' מאיר וגוזר כל כך בדין מעשר, שעונשו אף מדברי תורה רק \u0003מיתה\u0004 ש\u0003בידי שמים. ומשני ליה\u0004 \u0005[ומתרץ לו]\u0006 \u0003שמואל\u0004 ומוכיח, שהחמיר ר' מאיר בנושא של גט, שקשור באיסור אשת איש, שיש בו \u0003מיתת בית דין,\u0004 והרי \u0003דלמא שאני\u0004 \u0005[שמא שונה]\u0006 ענין של \u0003מיתת בית דין דחמירא\u0004 \u0005[ש\u0006היא \u0005חמורה\u0006 יותר\u0005]\u0006 ושמא רק בזה מחמיר ר' מאיר בדברי סופרים כדברי תורה, ואף","\u0003רב ששת לא שפיר קא מותיב ליה\u0004 \u0005[יפה הוא מקשה לו],\u0006 \u0003דקאמרי אינהו\u0004 \u0005[ש\u0006הרי \u0005אמרו הם]\u0006 ר' אלעזר ושמואל בדבר שיש בו עונש \u0003מיתה\u0004 כלשהו. \u0003ומותיב\u0004 \u0005[ומקשה]\u0006 \u0003רב ששת\u0004 מדבר שיש בו רק איסור \u0003לאו\u0004 (\"לא תעשה\"), \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במעשר שני \u0003\"לא תוכל לאכל בשעריך\u0004 מעשר דגנך ותירושך\u0003\"\u0004 (דברים יב, יז), הרי שיש בכך רק איסור \"לא תעשה\". \u0003ולמאי דמותיב\u0004 \u0005[ולפי מה שמקשה]\u0006 \u0003רב ששת\u0004 — \u0003רב יוסף שפיר קא משני ליה\u0004 \u0005[יפה מתרץ לו\u0006 מעין דבריו\u0005].\u0006","\u0003אלא\u0004 יש לשאול, \u0003רבינא, עד דמותיב\u0004 \u0005[ש\u0006הוא \u0005מקשה לו]\u0006 \u0003מ\u0004דין זה של \u0003נחתום\u0004 להראות שלכאורה מיקל ר' מאיר \u0003לסייע ליה\u0004 \u0005[שיסייע לו]\u0006 \u0003מ\u0004דין \u0003פלטר!\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הלוקח מן הפלטר,\u0004 (שהוא נחתום המוכר כמויות גדולות), \u0003מעשר מן כל דפוס ודפוס,\u0004 אלו \u0003דברי ר' מאיר!\u0004","\u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר],\u0006 להסביר את הבדל הדין בין פלטר לנחתום, כי \u0003פלטר מתרי תלתא גברא זבין\u0004 \u0005[משנים שלשה אנשים\u0006 הוא \u0005קונה],\u0006 \u0003נחתום נמי מחד גברא\u0004 \u0005[גם כן מאדם אחד]\u0006 \u0003הוא זבין\u0004 \u0005[קונה]\u0006 בדרך כלל, ולכן אין לחשוש שמא מפריש מן הפטור על החיוב.","\u0003רבא אמר\u0004 שלא כדברי אביי, ולדעתו \u0003שמואל שפיר קא משני ליה\u0004 \u0005[יפה הוא מתרץ לו],\u0006 שהרי בשני הנושאים יש \u0003שם מיתה בעולם,\u0004 מושג מיתה בכלל, שישנו גם במיתה בידי שמים, וגם במיתה בידי אדם. ולכן יפה הוכיח מדברי ר' מאיר עצמם מענין לענין.","\u0003אלו דברים שאין להם אונאה,\u0004 שגם אם היה הבדל שתות ויותר בין הערך האמיתי והמחיר ששולם, אין בכך משום אונאה. והם: \u0003העבדים, והשטרות, והקרקעות, וההקדשות.\u0004 ובאלה יש דינים מיוחדים נוספים: \u0003אין להן תשלומי כפל,\u0004 שהגונב אותם אינו חייב לשלם כפל, \u0003ולא תשלומי ארבעה וחמשה\u0004 אם טבחם או מכרם הגנב. \u0003שומר חנם אינו נשבע\u0004 עליהם, \u0003ונושא שכר\u0004 (שומר המקבל שכר עבור שמירתו) \u0003אינו משלם\u0004 אם נגנבו או אבדו ממנו. \u0003ר' שמעון אומר:\u0004"],["\u0003קדשים שהוא חייב באחריותן,\u0004 שהקדיש באופן כזה שחלה עליו התחייבות אישית, ואם אבדו אלה, צריך להביא אחרים תמורתם, יש לו בהם בעלות מסויימת, ולכן \u0003יש להן אונאה, ושאינו חייב באחריותן\u0004 — \u0003אין להן אונאה. ר' יהודה אומר: אף המוכר ספר תורה, בהמה ומרגלית\u0004 — \u0003אין להם אונאה,\u0004 שאין להם בעצם מחירים קבועים. \u0003אמרו לו\u0004 חכמים: \u0003לא אמרו\u0004 חכמים הראשונים \u0003אלא את אלו\u0004 שמנינו בלבד.","שואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שבאותם דברים שמנה במשנה, אין בהם אונאה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 הכתוב \u0003\"וכי תמכרו ממכר לעמיתך או קנה מיד עמיתך\u0004 אל תונו איש את אחיו\u0003\"\u0004 (ויקרא כה, יד) מדבר מענין \u0003דבר הנקנה\u0004 ועובר \u0003מיד ליד, יצאו קרקעות שאינן מטלטלים\u0004 מיד ליד, \u0003יצאו עבדים שהוקשו\u0004 \u0005[שהושוו]\u0006 בכמה מקומות \u0003לקרקעות\u0004 ונדונים כקרקע לעניינים שונים. ו\u0003יצאו שטרות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכי תמכרו ממכר\",\u0004 כלומר דבר ש\u0003גופו\u0004 (הוא עצמו) \u0003מכור וגופו קנוי, יצאו שטרות שאין גופן מכור ואין גופן קנוי,\u0004 שהרי השטר עצמו איננו בעל ערך, \u0003ואינן עומדין אלא לראיה שבהם.\u0004","\u0003מכאן אמרו: המוכר שטרותיו\u0004 הישנים שכבר נפרעו \u0003לבשם,\u0004 שישתמש בהם כנייר לצרור בו, \u0003יש להם אונאה,\u0004 שהרי אז מוכר לא את שטר הראיה, אלא את הנייר שבו. על כך שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהרי מוכר נייר בלבד, ונייר יש בו אונאה כשאר מטלטלים! ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מד\u0004ברי \u0003רב כהנא,\u0004 שאמר ש\u0003אין אונאה לפרוטות,\u0004 ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003יש אונאה לפרוטות\u0004. שהרי ודאי שמוכר את הנייר הזה בפרוטות בלבד. ולענין \u0003הקדשות\u0004 שאין בהם אונאה \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"אחיו\"\u0004 (שם), לומר: דווקא \u0003אחיו\u0004 — \u0003ולא הקדש.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על ראיה זו \u0003רבה בר ממל: כל היכא דכתיב\u0004 \u0005[מקום שנאמר]\u0006 \u0003\"ידו\"\u0004 האם \u0003ידו ממש הוא,\u0004 ולא בדרך השאלה? \u0003אלא מעתה דכתיב\u0004 \u0005[ש\u0006מצאנו \u0005כתוב]\u0006 \u0003\"ויקח את כל ארצו מידו\"\u0004 (במדבר כא, כו), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תפרש ש\u0003כל ארעא בידיה הוה נקיט לה\u0004 \u0005[הארץ בידו היה מחזיק אותה]?\u0006 \u0003אלא\u0004 ודאי מפרש \"מידו\" — \u0003מרשותו, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 תפרש \u0003מרשותו.\u0004 ואם כן, ההוכחה שהוכחנו אין בה ממש!","ומקשים לצד שני: \u0003וכל היכא דכתיב\u0004 \u0005[ובכל מקום שנאמר]\u0006 \u0003\"ידו\"\u0004 האם \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ידו ממש הוא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת: ממה שנאמר \u0003\"אם המצא תמצא בידו\u0004 הגניבה\u0003\"\u0004 (שמות כב, ג) \u0003אין לי\u0004 שהגנב משלם כפל \u0003אלא\u0004 כשנמצאה הגניבה ב\u0003ידו ממש,\u0004 ואולם אם נמצאה ב\u0003גגו,\u0004 או \u0003חצירו,\u0004 או \u0003קרפיפו\u0004 (חצר אחורית) \u0003מנין\u0004 שאף הוא משלם כפל? — \u0003תלמוד לומר: \"אם המצא תמצא\",\u0004 שכפילות הלשון מלמדת \u0003תמצא מכל מקום.\u0004","ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003\"אם המצא תמצא\", הא לאו הכי הוה אמינא\u0004 \u0005[הרי לולא זאת הייתי אומר]:\u0006 \u0003כל היכא דכתב\u0004 \u0005[מקום שנאמר]\u0006 \u0003\"ידו\"\u0004 הכוונה ל\u0003ידו ממש! ותו, תניא\u0004 \u0005[ועוד, שנויה\u0006 ברייתא\u0005]\u0006 כעין זו: ממה שנאמר לגבי גט \u0003\"ונתן בידה\"\u0004 (דברים כד, א) \u0003אין לי אלא ידה, גגה חצירה וקרפיפה מנין? תלמוד לומר \"ונתן\"\u0004 — \u0003מכל מקום.\u0004 ואף כאן נדייק: \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שכתבה התורה]\u0006 \u0003\"ונתן\", הא לאו הכי הוה אמינא\u0004 \u0005[הרי לולא זאת הייתי אומר]:\u0006 \u0003כל היכא דכתב\u0004 \u0005[מקום שנאמר]\u0006 \u0003\"ידו\",\u0004 הכוונה ל\u0003ידו ממש.\u0004","ומשום כך יש לדחות את קושיית רבה בר ממל, ולומר: אכן \u0003כל \"ידו\"\u0004 שבכתוב, יש לפרשו כי \u0003ידו ממש הוא, ושאני התם\u0004 \u0005[ושונה שם]\u0006 בכתוב \"ויקח כל ארצו מידו\" \u0003דליכא למימר הכי\u0004 \u0005[שאין\u0006 אפשרות \u0005לומר כך]\u0006 \u0003אלא\u0004 עלינו להבין שמשמעה: \u0003ברשותו.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: שכירות יש לו אונאה, או אין\u0004 בה \u0003אונאה?\u0004 שאם נשכר אדם לעבודה בפחות או יותר מן המחיר המקובל, האם יש בכך משום אונאה? וצדדי השאלה: האם נאמר כי \u0003\"ממכר\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 — \u0003אבל לא שכירות, או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי כתיב\u0004 \u0005[האם נאמר]\u0006 בתורה \u0003\"ממכר לעולם\"? \"ממכר\" סתמא כתיב\u0004 \u0005[סתם כתוב].\u0006 \u0003והאי נמי\u0004 \u0005[וזו,\u0006 השכירות, \u0005גם כן]\u0006 \u0003ביומיה\u0004 \u0005[ביומה]\u0006 הרי כ\u0003מכירה היא,\u0004 שהרי השכירות היא מכירת דבר (חפץ או אדם) לזמן מוגבל, ויש בה אונאה כבכל מכירה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: חטין וזרען בקרקע, מהו\u0004 דינן? \u0003יש להן אונאה, או אין להן אונאה?\u0004 וצדדי השאלה: \u0003האם\u0004 \u0003כמאן דשדיין בכדא דמיין\u0004 \u0005[כמוטלות בכד\u0006 הן \u0005נחשבות]\u0006 \u0003ויש להן אונאה.\u0004 שהרי הן עצמן מטלטלים, \u0003או דלמא בטלינהו על גב ארעא\u0004 \u0005[שמא בטלן לגבי הקרקע]\u0006 ודינן כקרקע?","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אמר איהו\u0004 \u0005[הוא],\u0006 האריס, או הפועל: \u0003שדאי\u0004 \u0005[הטלתי,\u0006 זרעתי\u0005],\u0006 \u0003בה שיתא\u0004 \u0005[ששה\u0006 קבים\u0005],\u0006 \u0003ואתו סהדי ואמרי\u0004 \u0005[ובאו עדים ואמרו]\u0006 ש\u0003לא שדא\u0004 \u0005[הטיל,\u0006 זרע\u0005]\u0006 \u0003בה אלא חמשה\u0004 קבים, \u0003ו\u0004אולם במקרה כזה \u0003האמר\u0004 \u0005[הרי\u0006 \u0003אמר]\u0004 \u0003רבא\u0004 עצמו: \u0003כל דבר\u0004 שיש בו אונאה \u0003שבמדה, ושבמשקל ושבמנין, אפילו פחות מכדי אונאה\u0004 — \u0003חוזר.\u0004 שדין אונאה ששיעורו בשתות, וכן שאר הפרטים שבו, הם רק כשיש טעות בערכם של דברים, אבל כאשר יש הבדל במידות, שהן מוגדרות וברורות, אין הגבלות דיני אונאה חלות שם, ולכן בקרקעות אם היתה טעות במדה — חוזר.","\u0003אלא\u0004 המקרה היה ש\u0003אמר איהו\u0004 \u0005[הוא],\u0006 האריס: \u0003שדאי\u0004 \u0005[הטלתי,\u0006 זרעתי\u0005]\u0006 \u0003בה כדאבעי\u0004 \u0005[כמה שהיה נחוץ]\u0006 \u0003לה,\u0004 ולא נקב במדה מסויימת, \u0003ואיגלאי מילתא\u0004 \u0005[והתברר הדבר]\u0006 ש\u0003לא שדא\u0004 \u0005[הטיל,\u0006 זרע\u0005]\u0006 \u0003בה כדאבעי\u0004 \u0005[כראוי]\u0006 \u0003לה,\u0004 האם \u0003יש להם אונאה או אין להם אונאה?\u0004 ואז אפשר לשאול האם \u0003כמאן דשדי בכדא דמיין\u0004 \u0005[כמוטלות בכד\u0006 הן \u0005נחשבות]\u0006 \u0003ויש להם אונאה, או דלמא בטלינהו\u0004 \u0005[שמא בטלן]\u0006 \u0003אגב ארעא\u0004 \u0005[הקרקע]?\u0006","ובאותו מקרה: אם היתה הודאה במקצת, האם \u0003נשבעין עליהן, או אין נשבעין עליהן?\u0004 ואף כאן השאלה: האם \u0003כמאן דשדיין בכדא דמיין\u0004 \u0005[כמוטלות בכד\u0006 הן \u0005נחשבות]\u0006 ודינן כמטלטלין \u0003ונשבעין עליהן, או דלמא בטלינהו\u0004 \u0005[שמא בטלן]\u0006 \u0003אגב ארעא\u0004 \u0005[הקרקע]\u0006 \u0003ואין נשבעין עליהן,\u0004 כפי שאין נשבעים בכלל על תביעות שבקרקעות!","ושאלה אחרת בנושא זה: האם הקרבת \u0003עומר, מתירן\u0004 באכילה, שכן כל תבואה שצמחה לפני העומר (ט\"ז בניסן) הקרבת העומר מתירה אותה באכילה. וזו שלא צמחה עוד, אסורה עד להבאת העומר בשנה הבאה, \u0003או אין עומר מתירן?\u0004 על כך שואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאשרוש\u0004 \u0005[אם\u0006 מדובר פה בחטים \u0005שכבר השרישו]\u0006 — הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 הלכה בענין זה! \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא אשרוש\u0004 \u0005[השרישו]\u0006 הלא גם כן \u0003תנינא\u0004 \u0005[שנינו].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 כל התבואות, \u0003אם השרישו קודם\u0004 לזמן ה\u0003עומר\u0004 — \u0003עומר מתירן\u0004 באכילה כאשר יבוא לקצרן, \u0003ואם לאו\u0004 \u0005[לא],\u0006 שהשרישו אחרי הנפת העומר — \u0003אסורין\u0004 (משום \"חדש\"), \u0003עד שיבא עומר הבא!\u0004 ואם כן מה מקום לשאלה זו של רבא?","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא באופן כזה: \u0003דחצדינהו וזרעינהו\u0004 \u0005[שקצר אותם, וזרע אותם]\u0006 \u0003קודם לעומר, ואתא ליה\u0004 \u0005[ובא לו]\u0006 ה\u0003עומר, וחליף עילוייהו\u0004 \u0005[וחלף,\u0006 עבר \u0005עליהם],\u0006 \u0003ולא אשרוש\u0004 \u0005[השרישו]\u0006 \u0003קודם לעומר,\u0004"],["והשאלה היא: \u0003מהו\u0004 הדין מותר \u0003למינקט ומיכל מינייהו\u0004 \u0005[לקחת\u0006 מחיטין אלו עצמן \u0005ולאכול מהן],\u0006 האם נאמר כי \u0003כמאן דשדיין בכדא דמי ושרינהו\u0004 \u0005[כמי שהן מוטלות בכד נחשבות, והתירן]\u0006 ה\u0003עומר,\u0004 שהרי הונף העומר לאחר שנקצרו, \u0003או דלמא בטלינהו\u0004 \u0005[שמא בטלן]\u0006 \u0003אגב ארעא\u0004 \u0005[קרקע],\u0006 והן כזרועות שלא השרישו ונאסרו. לשאלות אלה לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003אמר רבא אמר רב חסא, בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אמי:\u0004 אותם דברים שאמרנו שאין להם אונאה, האם \u0003אונאה\u0004 בשיעור שתות דווקא \u0003אין להם,\u0004 אבל \u0003ביטול מקח\u0004 בטעות גדולה יותר \u0003יש להן,\u0004 או \u0003אין להן? אמר רב נחמן: הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 \u0003רב חסא,\u0004 כי \u0003פשיט\u0004 \u0005[פתר]\u0006 \u0003ר' אמי\u0004 עצמו ואמר: \u0003אונאה אין להם, ביטול מקח יש להם. ר' יונה אמר\u0004 דבר זה על \u0003הקדשות, ר' ירמיה אמר\u0004 על \u0003קרקעות, ותרוייהו משמיה\u0004 \u0005[ושניהם משמו]\u0006 של \u0003ר' יוחנן אמרו: אונאה אין להם, ביטול מקח יש להן.\u0004","ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 דין זה על \u0003הקדשות,\u0004 \u0003כל שכן\u0004 שהוא הדין על \u0003קרקעות,\u0004 אבל \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 על \u0003קרקעות, אבל\u0004 על \u0003הקדשות לא\u0004 אמר. וכדברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: הקדש\u0004 ה\u0003שוה מנה, שחיללו על שוה פרוטה\u0004 — \u0003מחולל.\u0004 משום שבעצם אין כלל בהקדש דין אונאה, ולכן מתחלל אפילו בכל שהוא.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003אם היה קודש בעל מום,\u0004 שהחליף בו בהמה אחרת, הרי הוא עצמו \u0003יצא לחולין,\u0004 שנפדה על ידי כך, \u0003וצריך לעשות לו דמים.\u0004 כלומר, לחשב את מחירו, ולהוסיף כדי דמיו להקדש. ועל כך \u0003אמר ר' יוחנן: יצא לחולין\u0004 — \u0003דבר תורה, וצריך לעשות לו דמים\u0004 — \u0003מדבריהם\u0004 שחכמים תיקנו שצריך להוסיף לו דמים עד כדי ערכו. \u0003וריש לקיש אמר: אף צריך לעשות לו דמים מן התורה.\u0004","ומעתה נברר, \u0003במאי עסקינן\u0004 \u0005[במה\u0006 בדיוק \u0005עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שההבדל בין הערך הממשי, ובין הבהמה שנתנה כתמורה ופדיון, היה \u0003בכדי אונאה\u0004 ולא יותר — \u0003בהא לימא\u0004 \u0005[בכך יאמר]\u0006 \u0003ריש לקיש\u0004 כי \u0003צריך לעשות לו דמים דבר תורה? והתנן\u0004 \u0005[והרי\u0006 במשנתנו \u0005שנינו]:\u0006 \u0003אלו דברים שאין להם אונאה: הקרקעות והעבדים והשטרות וההקדשות!\u0004","\u0003אלא\u0004 ודאי הכוונה שהיה הפרש ביניהם כדי \u0003ביטול מקח,\u0004 האם \u0003בהא לימא\u0004 \u0005[בכך יאמר]\u0006 \u0003ר' יוחנן\u0004 ש\u0003צריך לעשות לו דמים\u0004 רק \u0003מדבריהם?\u0004 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יונה\u0004 דבר זה על \u0003הקדשות ור' ירמיה אמר\u0004 על \u0003קרקעות,\u0004 \u0003ותרוייהו משמיה\u0004 \u0005[ושניהם משמו]\u0006 של \u0003ר' יוחנן אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אונאה אין להם,\u0004 אבל \u0003ביטול מקח יש להם!\u0004 ומשיבים: \u0003לעולם\u0004 תפרש שכאן היה הבדל בכדי \u0003ביטול מקח, ואיפוך\u0004 \u0005[והפוך]\u0006 את השיטות, שמה שייחסו ל\u0003ר' יוחנן,\u0004 אמרו \u0003ריש לקיש, ו\u0004מה שייחסו ל\u0003ריש לקיש\u0004 באמת דברי \u0003ר' יוחנן\u0004 הם.","\u0003במאי קמיפלגי\u0004 \u0005[במה הם חולקים],\u0006 מה יסוד מחלוקתם? \u0003ב\u0004הלכ שקבע \u0003שמואל,\u0004 ש\u0003אמר שמואל: הקדש שוה מנה, שחיללו על שוה פרוטה\u0004 — \u0003מחולל. מר אית ליה\u0004 \u0005[חכם זה,\u0006 ריש לקיש, \u0005יש לו,\u0006 מקבל\u0005]\u0006 את דברי \u0003שמואל,\u0004 ולכן אמר שההקדש כבר נפדה מדין תורה, \u0003ומר לית ליה\u0004 \u0005[חכם זה,\u0006 רבי יוחנן, \u0005אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003שמואל.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר: \u0003דכולי עלמא אית להו\u0004 \u0005[הכל יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003שמואל,\u0004 \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה סבור],\u0006 שמה שאמר שמואל הקדש \u0003שחיללו\u0004 כוונתו: בדיעבד \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003לכתחילה\u0004 — \u0003לא\u0004 יעשה כן. \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]\u0006 שלאו דווקא חיללו בדיעבד, אלא \u0003אפילו לכתחלה.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 והסבר את הקושי באופן אחר: \u0003לעולם\u0004 מדובר כאן שהיה ההבדל בהקדש \u0003בכדי אונאה\u0004 ולא יותר \u0003ולא תיפוך\u0004 \u0005[תהפוך]\u0006 את שיטות ר' יוחנן וריש לקיש, אלא בשיטת \u0003רב חסדא קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 ש\u0003אמר\u0004 רב חסדא: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 שהקדשות \u0003אין להם אונאה\u0004 — כוונתו: \u0003אינן בתורת אונאה,\u0004 שאין חלים עליהם דיני האונאה הרגילים, אלא דינים חמורים יותר."],["\u0003אפילו פחות מכדי אונאה חוזר.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: יש \u0003רבית ואונאה להדיוט, ואין רבית ואונאה להקדש!\u0004 ודוחים: \u0003מי אלימא ממתניתין\u0004 \u0005[האם\u0006 ברייתא זו \u0005חזקה יותר ממשנתנו]\u0006 \u0003דאוקימנא\u0004 \u0005[שהעמדנוה\u0006 והסברנוה\u0005]\u0006 שמדובר \u0003בתורת אונאה,\u0004 כלומר, בפרטי דין אונאה ולא בעקרון. \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 נסביר את הברייתא: יש \u0003רבית ודין אונאה להדיוט, ואין רבית ודין אונאה להקדש.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש \u0003היינו דקתני סיפא\u0004 \u0005[זה ששנוי בסופה]\u0006 של אותה ברייתא: \u0003זה חומר בהדיוט מבהקדש?!\u0004 והרי לפי הסבר זה הדבר להיפך, חומר בהקדש מבהדיוט! ומשיבים: ביטוי זה נוגע רק על \u0003ארבית,\u0004 שמותר לגבות רבית מן ההקדש. ושואלים עוד: \u0003ליתני נמי\u0004 \u0005[שישנה גם כן]:\u0006 \u0003זה חומר בהקדש מבהדיוט\u0004 —על \u0003אונאה\u0004 אם מונה את ההבדלים בין הקדש והדיוט!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 כשהוא אומר \u0003זה חומר בהדיוט מבהקדש\u0004 יש בכך חידוש. ועוד, שזה \u0003ותו לא\u0004 \u0005[ולא עוד].\u0006 \u0003אלא הקדש,\u0004 וכי יכול אתה לומר \u0003\"זה חומר\" ותו לא\u0004 \u0005[ולא יותר]?\u0006 והרי הקדש חמור מחולין בהרבה דברים!","כיון שהוזכר הדבר בברייתא, שואלים: \u0003רבית\u0004 של \u0003הקדש היכי דמי\u0004 \u0005[איך היא בדיוק]?\u0006 \u0003אילימא\u0004 \u0003דאוזפיה\u0004 \u0005[אם תאמר שהלווהו]\u0006 הגזבר לאדם פרטי כסף הקדש \u0003מאה במאה ועשרים\u0004 — \u0003והלא\u0004 אסור להשתמש בהקדש לצרכי חולין, ונמצא כי \u0003מעל הגזבר, וכיון שמעל הגזבר\u0004 עם נתינת הכסף, הרי מיד \u0003יצאו מעותיו לחולין\u0004 על ידי המעילה, \u0003והוו להו\u0004 \u0005[והרי נעשו]\u0006 של \u0003הדיוט,\u0004 ויש בהם דין רבית כשאר הדיוטות!","\u0003אמר רב הושעיא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שקיבל עליו\u0004 אדם \u0003לספק\u0004 למקדש \u0003סלתות מארבע\u0004 סאין בסלע, ועלה המחיר, \u0003ועמדו\u0004 מחירי הסלתות \u0003משלש\u0004 בסלע. ו\u0003כדתניא\u0004 \u0005[וכפי ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003המקבל עליו לספק סלתות מארבע, ועמדו משלש,\u0004 בכל זאת \u0003מספק מארבע,\u0004 שהרי כך קיבל עליו. ואולם אם אירע להיפך, שקיבל עליו \u0003משלש,\u0004 וירד המחיר, \u0003ועמדו מארבע\u0004 — \u0003מספק מארבע.\u0004 ונמצא איפוא שיש בכך כעין רבית, \u0003שיד הקדש על העליונה,\u0004 ואף שבכגון זה אסור להדיוט — מותר להקדש.","\u0003רב פפא אמר:\u0004 יכול שיהא דין רבית בהקדש גם באופן פשוט: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003באבני בנין המסורות לגזבר עסקינן\u0004 \u0005[עוסקים אנו]\u0006 וכדברי \u0003שמואל.\u0004 ש\u0003אמר שמואל: בונין\u0004 את בנייני המקדש \u0003בחול,\u0004 כדי לא לבוא לידי מעילה בקודש בתהליכי הבנין, \u0003ואחר כך מקדישים.\u0004 ולכן יש לפי שעה לגזבר בידו רכוש שסופו להיעשות רכוש של קודש, אך בינתיים הוא חול, וכספים אלה השייכים להקדש, רשות לגזבר לעשות בהם כראות עיניו ואפילו להלוותם לאחרים.","שנינו במשנה שארבעה דברים שנמנו בה \u0003אין בהן תשלומי כפל.\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הכתוב \"על כל דבר פשע, על שור, על חמור, על שה, על שלמה, על כל אבדה... אשר ירשיעון אלהים, ישלם שנים לרעהו\" (שמות כב, ח). ודרשו: \u0003\"על כל דבר פשע\"\u0004 הרי זה \u0003כלל: \"על שור, על חמור, על שה, על שלמה\"\u0004 — \u0003פרט, \"על כל אבדה אשר יאמר\u0004 כי הוא זה \u0003\"\u0004— \u0003חזר וכלל.\u0004","ואם כך, יש בפסוק \u0003כלל ופרט וכלל.\u0004 ולפי כללי מדרש ההלכה, \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה דן\u0004 עניינו של פסוק זה, \u0003אלא כעין הפרט; מה הפרט מפורש\u0004 — \u0003דבר המטלטל וגופו\u0004 (הוא עצמו) \u0003ממון\u0004 — \u0003אף כל דבר המטלטל וגופו ממון\u0004 בכלל זה.","ולכן \u0003יצאו קרקעות\u0004 — \u0003שאינן מטלטלין, יצאו עבדים שהוקשו\u0004 (הושוו) \u0003לקרקעות\u0004 לענייני הלכה רבים. \u0003יצאו שטרות, שאף על פי שמטלטלין\u0004 — \u0003אין גופן ממון,\u0004 ואין הם אלא ראיה להתחייבות ממקרא, ואילו לענין \u0003הקדשות, אמר קרא\u0004 \u0005[הכתוב]\u0006 שם \u0003\"רעהו\"\u0004 (שם), ונלמד מכך: \u0003רעהו ולא\u0004 \u0003הקדש.\u0004","שנינו שאין בדברים אלה \u0003תשלומי ארבעה וחמשה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו\u0006 של דבר\u0005]?\u0006 ומסבירים: \u0003תשלומי ארבעה וחמשה אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003ולא תשלומי שלשה וארבעה.\u0004 וכיון שכבר הוכחנו מן הכתוב שאין בהם כפל, לא חל עליהם דין ארבעה וחמשה.","שנינו במשנה כי \u0003שומר חנם אינו נשבע\u0004 על דברים אלה. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר \"כי יתן איש אל רעהו כסף או כלים לשמור, וגונב מבית האיש, אם ימצא הגנב ישלם שנים. אם לא ימצא הגנב, ונקרב בעל הבית אל האלהים...\" (שמות כב, ו–ז). ודרשו: \u0003\"כי יתן איש אל רעהו\"\u0004 הרי זה \u0003כלל, \"כסף או כלים\"\u0004 — \u0003פרט, \"וגנב מבית האיש\"\u0004 — \u0003חזר וכלל.\u0004","ואם כן הרי זה \u0003כלל ופרט וכלל,\u0004 ופסוק זה \u0003אי אתה דן אלא כעין הפרט: מה הפרט מפורש\u0004 — \u0003דבר המטלטל וגופו ממון\u0004 — \u0003אף כל דבר המטלטל וגופו ממון\u0004 דינו כך,","\u0003יצאו קרקעות\u0004 — \u0003שאינן מטלטלין, יצאו עבדים שהוקשו לקרקעות, יצאו שטרות שאף על פי שמטלטלין אין גופן ממון.\u0004 ולגבי \u0003הקדשות\u0004 הלא \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"רעהו\"\u0004 (שם), לומר: \u0003רעהו ולא של הקדש.\u0004","עוד שנינו במשנה כי \u0003נושא שכר אינו משלם,\u0004 אם נגנבו דברים אלה או אבדו מרשותו. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 ומסבירים: \u0003תנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הכתוב: \"כי יתן איש אל רעהו חמור או שור, או שה, וכל בהמה לשמור, ומת או נשבר או נשבה אין רואה... ואם גנוב ייגנב מעמו ישלם לבעליו\" (שמות כב, ט–יא). ודרשו: \u0003\"כי יתן איש אל רעהו\"\u0004 הרי זה \u0003כלל, \"חמור או שור או שה\"\u0004 — \u0003פרט, \"וכל בהמה לשמר\"\u0004 — \u0003חזר וכלל.\u0004","הרי זה \u0003כלל ופרט וכלל,\u0004 ו\u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה דן אלא כעין הפרט: מה הפרט מפורש\u0004 — \u0003דבר המטלטל וגופו ממון\u0004 — \u0003אף כל דבר המטלטל וגופו ממון.\u0004","הרי \u0003יצאו קרקעות\u0004 — \u0003שאינן מטלטלין, יצאו עבדים שהוקשו לקרקעות, יצאו שטרות שאף על פי שמטלטלין אין גופן ממון.\u0004 ולגבי \u0003הקדשות\u0004 הלא \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"רעהו\"\u0004 (שם), לומר: \u0003רעהו ולא של הקדש.\u0004","למדנו איפוא את המקור בתורה להלכות אלה שנזכרו במשנה, ועתה באים לבררן לגופן. נאמר במשנה זו ש\u0003שומר חנם אינו נשבע\u0004 על גניבה ואבידה. \u0003ורמינהו\u0004 \u0005[ואנו משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003בני העיר ששלחו את שקליהן\u0004 שנותנים בחודש אדר לצורך המקדש, לירושלים, \u0003ונגנבו\u0004 השקלים \u0003או שאבדו,\u0004","\u0003אם משנתרמה התרומה\u0004 של הכסף במקדש, לפי שהיו מכניסים את כל השקלים שהגיעו לחדר מיוחד, ששם היו תורמים (מרימים ומקדישים) מהם חלק עבור צרכי הקרבנות של החודשים הבאים, ותרומה זו היתה כדי לשתף את כל ישראל בקרבנות הציבור,"],["ומשעת תרומה נחשב כל כסף השקלים, בין זה שהגיע כבר לתעודתו, ובין זה שלא הגיע, כשייך למקדש, הרי השליחים \u0003נשבעין לגזברין\u0004 שלא שלחו ידם בהם. \u0003ואם לאו\u0004 \u0005[לא]\u0006 שעדיין לא נתרמה תרומה, \u0003נשבעין\u0004 השליחים \u0003לבני העיר, ובני העיר שוקלין\u0004 שקלים \u0003אחרים תחתיהן. נמצאו\u0004 השקלים שאבדו, \u0003או שהחזירום הגנבים\u0004 — \u0003אלו ואלו\u0004, גם השקלים הקודמים וגם אלה שחזרו ונתנו, \u0003שקלים הם\u0004 ויש בהם קדושת כספי קודש, \u0003ואין עולין להם לשנה הבאה.\u0004 שאין נתינה כפולה זו של השקלים בשנה זו, פוטרת את בני העיר מלתת שקליהם לשנה הבאה. ולעניננו הרי מוכח מכאן כי נשבעים על ההקדשות!","\u0003אמר שמואל: הכא בנושא שכר עסקינן\u0004 \u0005[כאן ב\u0006שליח \u0005מקבל שכר עוסקים אנו].\u0006 ושבועה זו אינה באה כדי לפטרם מאחריות עבור הגניבה, אלא \u0003נשבעין ליטול שכרן,\u0004 שהרי הם רוצים לקבל את השכר שנקצב להם, ולכן נשבעים שהם מצידם עשו את עבודתם בשלימות. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מדוע \u0003נשבעין לגזברין? לבני העיר מבעי ליה\u0004 \u0005[צריך להם]\u0006 שישבעו, שהרי מבני העיר הם התובעים! \u0003אמר רבה:\u0004 הכוונה היא \u0003נשבעין לבני העיר במעמד גזברין, כי היכי\u0004 \u0005כדי\u0006 ש\u0003לא נחשדינהו\u0004 \u0005[יחשדו בהם]\u0006 הגזברין בבני אותה עיר שלא תרמו שקליהם כלל. \u0003ואי נמי\u0004 \u0005[או גם כן]\u0006 \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא לקרו להו\u0004 \u0005[יקראו להם]\u0006 \u0003\"פושעים\"\u0004 \u0005[\"רשלנים\"],\u0006 על כן נשבעים השליחים שהם עשו מצידם את כל הראוי להיעשות.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003נגנבו או שאבדו קתני\u0004 \u0005[שנה],\u0006 \u0003ושומר שכר בגניבה ואבידה חיובי מיחייב\u0004 \u0005[חייב\u0006 הוא\u0005]!\u0006 \u0003והכא נמי\u0004 \u0005[וכאן גם כן],\u0006 שהם שומרים על הקדש, \u0003נהי דשלומי לא משלמי\u0004 \u0005[ואם אמנם שלשלם אינם משלמים]\u0006 על הגניבה, \u0003אגרייהו מיהא לפסיד\u0004 \u0005[שכרם לפחות יפסדו],\u0006 שהרי אחריותם על השמירה כוללת גניבה ואבידה!","\u0003אמר רבה:\u0004 מה שנאמר כאן \u0003נגנבו\u0004 — כוונתו \u0003בלסטים מזויין,\u0004 שאינו גנב רגיל אלא שודד, והרי זה אונס, ששומר שכר אינו חייב עליו. וכן \u0003אבדו\u0004 כוונתו \u0003שטבעה ספינתו בים,\u0004 שאבידה כזו היא אונס, ושומר שכר אינו חייב בה.","\u0003ר' יוחנן אמר\u0004 הסבר אחר: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: קדשים שחייב באחריותן יש להן אונאה, ו\u0004לכן גם \u0003נשבעין עליהם.\u0004","ושואלים: \u0003התינח\u0004 \u0005[נניח]\u0006 על פי תירוץ זה, \u0003עד שלא נתרמה התרומה,\u0004 שאז אחריות השקלים היא על בני העיר, ולכן לר' שמעון נשבעים עליהם, ואולם \u0003משנתרמה התרומה קדשים שאינו חייב באחריותן נינהו\u0004 שוב אין אחריותם על בני העיר כלל, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תורמין\u0004 מן השקלים בלשכה במקדש, ומכוונים בזה להוציא ידי חובה \u0003על האבוד\u0004 בדרך, \u0003ועל הגבוי\u0004 כבר שלא הגיע, \u0003ועל העתיד לגבות.\u0004 ואם כן משעה זו אין עוד אחריות בני העיר על הכספים!","\u0003אלא אמר ר' אלעזר:\u0004 יש לדחות מה שאמרנו, ו\u0003שבועה זו\u0004 שנשבעין השליחים \u0003תקנת חכמים היא, שלא יהו בני אדם מזלזלים בהקדשות,\u0004 שאם ידעו שאין נשבעים עליהם, יחשבו שאין ההקדש חשוב, ואפשר לזלזל בשמירתו.","שנינו במשנה כי \u0003נושא שכר אינו משלם\u0004 אם היה שומר את ההקדשות. \u0003רמי ליה\u0004 \u0005[הטיל לו,\u0006 הראה סתירה\u0005]\u0006 \u0003רב יוסף בר חמא לרבה; תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003נושא שכר אינו משלם, ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: גזבר של הקדש \u0003השוכר את הפועל לשמור את הפרה\u0004 אדומה שלא תפסל, או \u0003לשמור את התינוק\u0004 שהיה נשמר בטהרה מיום הולדתו כדי למלא את המים לאפר הפרה, או \u0003לשמור את הזרעים\u0004 של תבואה שמייעדים אותה להקרבת העומר, \u0003אין נותנין לו שכר שבת,\u0004 אם היה שכיר יום, \u0003לפיכך אין אחריות שבת עליו\u0004 אם אירע קלקול באחד מאלה ביום השבת, כיון שאינו מקבל שכר על שמירתו בשבת.","\u0003היה שכיר שבת\u0004 (שבוע), שנשכר לשבוע שלם, או \u0003שכיר חדש, שכיר שנה, שכיר שבוע\u0004 (שבע שנים) — \u0003נותנין לו\u0004 וכוללים בשכרו גם \u0003שכר שבת, לפיכך אחריות שבת עליו.\u0004 ולענייננו למדים אנו ששומר שכר של ההקדש חייב באחריותו. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003לשלם\u0004 מה שהפסיד?","ודוחים: \u0003לא,\u0004 הכוונה היא רק לענין \u0003להפסיד שכרו\u0004 על שהתרשל בשמירה. והקשה לו: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003רישא דקתני\u0004 \u0005[ראש\u0006 הברייתא \u0005ששנה\u0006 בה\u0005]\u0006 \u0003אין אחריות שבת עליו\u0004 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תפרש שהכוונה היא לענין \u0003להפסיד שכרו?!\u0004 \u0003ומי אית ליה\u0004 \u0005[והאם יש לו]\u0006 \u0003שכר שבת?\u0004 \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 ש\u0003אין נותנין לו שכר שבת,\u0004 ובהכרח שמדובר באחריות לשמירת הדברים עצמם! \u0003אשתיק\u0004 \u0005[שתק]\u0006 רבה ולא מצא תשובה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה לרב יוסף בר חמא: \u0003מידי שמיע לך בהא\u0004 \u0005[וכי שמעת דבר ב\u0006ענין \u0005זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת:\u0004 שם מדובר \u0003בשקנו מידו,\u0004 שעשו בענין זה הסכם מיוחד ועשו קנין, שיתחייב השומר באחריות. \u0003וכן אמר ר' יוחנן:\u0004 מדובר שם \u0003בשקנו מידו.\u0004","שנינו במשנה ש\u0003ר' שמעון אומר: קדשים שחייב באחריותן\u0004 — \u0003יש להן אונאה, ושאינו חייב באחריותן\u0004 — \u0003אין להם אונאה. תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003ר' יצחק בר אבא\u0004 ברייתא זו: דברי ר' שמעון נדרשים מן הכתוב \"נפש כי תחטא ומעלה מעל בה' וכחש בעמיתו בפקדון או בתשומת יד ...","\" (ויקרא ה, כא) וכך הוא דורש: \u0003קדשים שחייב באחריותן\u0004 — \u0003חייב\u0004 להשבע עליהם, לפי \u0003שאני קורא בהן: \"בה' וכחש\"\u0004 ועל ידי צירוף המילים באופן זה, משמע שאף ש\"כחש בה'\", נשבע. \u0003ושאינו חייב באחריותן\u0004 — \u0003פטור, שאני קורא בהן: \"בעמיתו וכחש\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יצחק: \u0003כלפי לייא\u0004 \u0005[לאן,\u0006 אתה פונה\u0005]?!\u0006 כלומר, דברים אלה מוזרים שהראיה היא כמעט היפך הענין."],["\u0003איפכא מסתברא\u0004 \u0005[ההיפך\u0006 הוא \u0005מסתבר]\u0006 לומר, שמה שחייב באחריותו הרי הוא כשלו, ולכן נכלל בכלל \"רעהו\", ומה שאינו חייב באחריותו הלא שייך לה'! \u0003אמר ליה\u0004 \u0005[לו]\u0006 חוזר המשניות: \u0003איסמיה\u0004 \u0005[האם אמחוק אותה]\u0006 את הברייתא הזו מגירסתי משום שהיא משובשת?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא.\u0004 אלא \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את הדרשה, בשינוי בהדגשה: \u0003קדשים שחייב באחריותן, חייב\u0004 בשבועה עליהם, \u0003דאיתרבו\u0004 \u0005[שהתרבו]\u0006 ונלמדו מן התוספת \u0003\"בה' וכחש\",\u0004 שאפילו דבר שיש בו כאילו חלק שמים, כיון ששלו הוא — חייב עליו. \u0003ושאינו חייב באחריותן פטור\u0004 בשבועה עליהם, \u0003דאמעיט\u0004 \u0005[שהתמעטו]\u0006 ממה שנאמר \u0003\"בעמיתו וכחש\".\u0004 לומר: רק דבר השייך להדיוט, ל\"עמיתו\" הוא שנשבעים עליו, ולא אחר.","שנינו במשנה כי \u0003ר' יהודה אומר: אף המוכר ספר תורה, מרגלית ובהמה, אין להם אונאה. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 שיש בה הסבר לדברים. \u0003ר' יהודה אומר: אף המוכר ספר תורה אין לה אונאה\u0004 — \u0003לפי שאין קץ לדמיה.\u0004 שהרי תורת ה' היא, וכל חפצים לא ישוו בה. \u0003בהמה ומרגלית אין להם אונאה\u0004 — \u0003מפני שאדם רוצה לזווגן.\u0004 שלעיתים רוצה אדם לצרף בהמה לצמד תואם, או מרגלית להשלים צמד או מחרוזת, ולכן אינו מקפיד על מחירם, לפי שעל ידי קנייתם מרויח הרבה.","\u0003אמרו לו: והלא הכל אדם רוצה לזווגן,\u0004 שהרי גם דברים אחרים, יתכן שירצה אדם לצרפם זה לזה, כדי שתהיה לו מערכת שלמה, ואם כן לא תהיה אונאה בשום דבר. ושואלים: \u0003ור' יהודה\u0004 מה עונה הוא על כך? ומשיבים: לדעתו, \u0003הני חשיבי ליה, והני לא חשיבי ליה\u0004 \u0005[אלה חשובים בעיניו, ואלה אינם חשובים בעיניו].\u0006 ולבירור שיטת ר' יהודה שואלים: ודברים שאין בהם אונאה, \u0003עד כמה\u0004 השיעור? שוודאי אין הכוונה בכל מחיר שבעולם. \u0003אמר אמימר: עד כדי דמיהם.\u0004 כלומר, אפשר לומר שאדם מוכן לשלם עד כפליים מן המחיר הקצוב.","באותה שיטה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה בן בתירא אומר: אף המוכר סוס וסייף וחטיטום\u0004 (מגן) \u0003במלחמה\u0004 — \u0003אין להם אונאה, מפני שיש בהם חיי נפש\u0004 בשעה זו, ואדם מוכן לשלם כל סכום עבורם.","\u0003כשם ש\u0004יש איסור \u0003אונאה במקח וממכר, כך\u0004 יש איסור \u0003אונאה\u0004 (מרמה וצער) \u0003בדברים\u0004 בלבד שאין בהם קנין ומכירה. כגון: \u0003לא יאמר לו\u0004 למוכר \u0003\"בכמה חפץ זה\"? והוא אינו רוצה ליקח\u0004 (לקנות) ונמצא המוכר סבור שעומד לקנות ממנו, ולבסוף מצטער שלא קנה. וסוג אחר של אונאה — \u0003אם היה\u0004 אדם \u0003בעל תשובה, לא יאמר לו \"זכור מעשיך הראשונים\". אם הוא בן גרים, לא יאמר לו \"זכור מעשה אבותיך\", שנאמר: \"וגר לא תונה, ולא תלחצנו\"\u0004 (שמות כב, כ).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \"ו \u0003לא תונו איש את עמיתו\u0004 ויראת מאלהיך כי אני ה' אלהיכם\" (ויקרא כה, יז). ומפרשים: \u0003באונאת דברים הכתוב מדבר.\u0004 ודנים בדבר: \u0003אתה אומר באונאת דברים, או אינו אלא באונאת ממון? כשהוא אומר\u0004 קודם \u0003\"וכי תמכרו ממכר לעמיתך, או קנה מיד עמיתך,\u0004 אל תונו איש את אחיו\u0003\"\u0004 (שם יד) \u0003הרי אונאת ממון אמור\u0004 שם במפורש, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 ומפרש \u0003\"\u0004ו\u0003לא תונו איש את עמיתו\"\u0004 — \u0003באונאת דברים.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 — \u0003אם היה בעל תשובה\u0004 אל יזכיר לו מעשיו הרעים, \u0003אל יאמר לו \"זכור מעשיך הראשונים\". אם היה בן גרים אל יאמר לו \"זכור מעשה אבותיך\". אם היה גר ובא ללמוד תורה, אל יאמר לו \"פה שאכל נבילות וטריפות, שקצים ורמשים, בא ללמוד תורה שנאמרה מפי הגבורה\"?\u0004","וכן, \u0003אם היו יסורין באין עליו,\u0004 או \u0003אם היו חלאים\u0004 (מחלות) \u0003באין עליו, או שהיה מקבר את בניו, אל יאמר לו כדרך שאמרו לו חביריו לאיוב \"הלא יראתך כסלתך תקותך ותם דרכיך. זכר נא מי הוא נקי אבד\"\u0004 (איוב ד' ו–ז), כלומר, בוודאי חטאת, שלולא כן לא היה קורה לך כך. שכל אלה בגדר אונאת דברים הם.","ועוד: \u0003אם היו חמרים מבקשין תבואה\u0004 ממנו ואין לו, \u0003לא יאמר להם \"לכו אצל פלוני שהוא מוכר תבואה\", ויודע בו שלא מכר מעולם,\u0004 ונמצא מצער את החמרים ואותו האיש לחינם. \u0003ר' יהודה אומר: אף לא יתלה עיניו על המקח\u0004 ויתבונן בו כקונה \u0003בשעה שאין לו דמים\u0004 לקנותו. וכל ענייני אונאת דברים הרי אינם גלויים, ולא תמיד אפשר להוכיח שעשה אדם בזדון, \u0003שהרי הדבר מסור ללב\u0004 פעמים רבות, ואי אפשר לדעת אם נתכוון לכך, \u0003וכל דבר המסור ללב נאמר בו,\u0004 כפי שנאמר בכתוב שהובא למעלה \u0003\"ויראת מאלהיך\",\u0004 שהרי ה' בוודאי יודע מה היה בלבו של אדם.","\u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחאי: גדול\u0004 עוון \u0003אונאת דברים, מאונאת ממון, שזה נאמר בו \"ויראת מאלהיך\", וזה לא נאמר בו \"ויראת מאלהיך\". ור' אלעזר אומר\u0004 טעם אחר: \u0003זה\u0004 שבדברים, הרי הוא חוטא ופוגע \u0003בגופו, וזה\u0004 רק \u0003בממונו. ר' שמואל בר' נחמני אמר: זה,\u0004 אונאת ממון, \u0003ניתן להישבון,\u0004 שהרי יכול להחזיר לו את הממון שנטל שלא כדין, \u0003וזה לא ניתן להישבון.\u0004","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן בר יצחק: כל המלבין פני חבירו ברבים כאילו שופך דמים. אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בר יצחק: \u0003שפיר קא אמרת\u0004 \u0005[יפה אמרת],\u0006 \u0003דחזינא ליה דאזיל סומקא ואתי חוורא\u0004 \u0005[שהרי אנו רואים אותו\u0006 את המתבייש שלאחר שהוא מאדים מבושה, \u0005שהולך האודם\u0006 מפניו, \u0005ובא החיורון]\u0006 והרי זה כשופך את דמו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי: במערבא במאי זהירי\u0004 \u0005[בארץ ישראל, במה,\u0006 באיזו מצוה, \u0005נזהרים]\u0006 ביותר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003באחוורי אפי\u0004 \u0005[בהלבנת פנים],\u0006 ש\u0003אמר ר' חנינא: הכל יורדין לגיהנם חוץ משלשה.\u0004","ולפני שנגמר הדבר שואלים: \u0003הכל סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר, וכי אין אנשים שאינם יורדים לגיהנם? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003כל היורדין לגיהנם עולים, חוץ משלשה שיורדין ואין עולין\u0004 מפני רוע מעשיהם. \u0003ואלו הן: הבא על אשת איש,\u0004 שחוטא גם לשמים וגם לבריות חטא חמור מאד, \u0003והמלבין פני חבירו ברבים, והמכנה שם רע לחבירו.\u0004 ושואלים: \u0003מכנה היינו\u0004 \u0005[הריהו]\u0006 \u0003מלבין,\u0004 ומה ההבדל ביניהם, שהרי גם הוא ממלביני הפנים! ומשיבים: \u0003אף על גב דדש ביה בשמיה\u0004 \u0005[אף על פי שהוא רגיל בו בשמו]\u0006 והכל רגילים לקרוא לו כך, מכל מקום כיון שמתכון לכנותו בשם רע, עונשו גדול מאד.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004"],["\u0003נוח לו לאדם שיבוא על ספק אשת איש ואל ילבין פני חבירו ברבים.\u0004 ושואלים: \u0003מנא לן\u0004 \u0005[מנין לנו\u0006 דבר זה\u0005]?\u0006 ומשיבים: \u0003מדדרש\u0004 \u0005[ממה שדרש]\u0006 \u0003רבא, דדרש רבא\u0004 שדרש: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ובצלעי שמחו ונאספו... קרעו ולא דמו\"\u0004 (תהילים לה, טו) — \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם! גלוי וידוע לפניך שאם היו מקרעים בשרי לא היה דמי שותת לארץ\u0004 (\"קרעו ולא דמו\") שמפני רוב התעניות כחש בשרו עליו,","\u0003ולא עוד אלא,\u0004 כמה מציקים לי שונאי, \u0003אפילו בשעה שעוסקין\u0004 בזמן הלימוד בציבור \u0003בנגעים ואהלות,\u0004 שהם מהלכות טומאה וטהרה, \u0003אומרים לי\u0004 בשאלה שאיננה כלל מן הענין: \u0003דוד, הבא על אשת איש מיתתו במה?\u0004 כדי להזכיר לו שחטא באשת איש, באשת אוריה החתי. \u0003ואני אומר להם:\u0004 הבא על אשת איש \u0003מיתתו בחנק\u0004 (אם היו עדים והתראה) אבל \u0003יש לו חלק לעולם הבא, אבל המלבין את פני חבירו ברבים אין לו חלק לעולם הבא.\u0004 ומכאן שגדול עונש מביישי דוד, מחטאו של דוד עצמו.","\u0003אמר מר זוטרא בר טוביה אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב חנא בר ביזנא אמר ר' שמעון חסידא,\u0004 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחאי: נוח לו לאדם שיפיל עצמו לכבשן האש\u0004 וישרף בו, \u0003ואל ילבין פני חבירו ברבים. מנא לן\u0004 \u0005[מנין לנו\u0006 דברים אלה\u0005]\u0006 — \u0003מתמר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ויאמר יהודה הוציאוה ותשרף \u0003היא מוצאת והיא שלחה אל חמיה\u0004 לאמור לאיש אשר אלה לו אנכי הרה\" (בראשית לח, כד–כה), שגם כאשר הוליכוה להישרף לא הודיעה לרבים שיהודה הוא שבא עליה, אלא רק רמזה לו שהוא עצמו יחליט בדבר, הרי שהיתה מוכנה ללכת לכבשן האש ולא להלבין את פניו.","ועוד בהלכות אונאה, \u0003אמר רב חננא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ולא תונו איש את עמיתו\"\u0004 (ויקרא כה, יז) לשון זו, \"עמיתו\", משמעה עם שאתו, \u0003עם שאתך בתורה ובמצוות, אל תוניהו\u0004 אדם השומר תורה ומצוותיה אל תצער אותו. \u0003אמר רב: לעולם יהא אדם זהיר באונאת אשתו\u0004 ואל תצער אותה, \u0003שמתוך שדמעתה מצויה\u0004 והיא בוכה מיד, \u0003אונאתה\u0004 (עונש על אונאתה) \u0003קרובה.\u0004","\u0003אמר ר' אלעזר: מיום שנחרב בית המקדש ננעלו שערי תפילה,\u0004 ואין תפילתו של אדם נשמעת עוד כמקודם, \u0003שנאמר: \"גם כי אזעק ואשוע שתם תפילתי\"\u0004 (איכה ג, ח). ואולם \u0003אף על פי ששערי תפילה ננעלו\u0004 — \u0003שערי דמעות לא ננעלו\u0004, \u0003שנאמר: \"שמעה תפלתי ה' ושועתי האזינה אל דמעתי אל תחרש\"\u0004 (תהלים לט, יג) — אינו מבקש שה' ישמע לדמעותיו, אלא מובטח לו שכן יהא.","\u0003ואמר רב\u0004 כעין השלמה למה שאמר קודם: ומכל מקום \u0003כל ההולך בעצת אשתו נופל בגיהנם שנאמר: \"רק לא היה כאחאב\u0004 אשר התמכר לעשות הרע בעיני ה' אשר הסתה אותו איזבל אשתו (מלכים א' כא, כה). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: והא אמרי אינשי\u0004 \u0005[והרי אומרים אנשים]\u0006 כפתגם מקובל: אם \u0003איתתך גוצא\u0004 \u0005[אשתך נמוכה]\u0006 \u0003— גחין ותלחוש\u0004 \u0005[גחון ולחש]\u0006 \u0003לה\u0004 והתייעץ עמה, משמע שראוי ללכת בעצת אשתו! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 — \u0003הא במילי דעלמא\u0004 \u0005[זה בענייני העולם]\u0006 אין ראוי לשמוע בעצתה, \u0003והא במילי דביתא\u0004 \u0005[וזה בענייני הבית]\u0006 כדאי להתייעץ עמה. \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 \u0003הא במילי דשמיא\u0004 \u0005[זה בענייני שמים]\u0006 אין ללכת בעצתה, \u0003והא במילי דעלמא\u0004 \u0005[וזה בענייני העולם]\u0006 ראוי להתייעץ איתה.","\u0003אמר רב חסדא: כל השערים\u0004 של שמים עשויים להיות \u0003ננעלים, חוץ משערי אונאה,\u0004 שמי שציערוהו שערי שמים פתוחים לצעקתו, \u0003שנאמר: \"\u0004ו\u0003הנה ה' נצב על חומת אנך ובידו אנך\"\u0004 (עמוס ז, ז), כלומר, כלי המידה, האנך, הוא הכלי שכביכול מצוי תמיד בידי ה', לראות אם לא נעשה עוול. ו\u0003אמר ר' אלעזר: הכל,\u0004 כל עבירות שנעשות, \u0003נפרע\u0004 ה' \u0003בידי שליח, חוץ מאונאה, שנאמר: \"ובידו אנך\",\u0004 שה' בעצמו נפרע ממנה.","\u0003אמר ר' אבהו: שלשה\u0004 חטאים \u0003אין הפרגוד\u0004 שבין העולם לשכינה \u0003ננעל בפניהם\u0004 ותמיד מגיעה התלונה על כך, והם: \u0003אונאה, וגזל, ועבודה זרה.\u0004 וראיה לדבר: \u0003אונאה דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובידו אנך\". גזל דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"חמס ושד ישמע בה על פני תמיד\"\u0004 (ירמיהו ו, ז), שתמיד ללא הפסק באה התלונה על חטא זה לפני ה', וכן \u0003עבודה זרה דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"העם המכעסים אתי על פני תמיד\u0004 זובחים בגנות ומקטרים על הלבנים\u0003\"\u0004 (ישעיה סה, ג).","ואגב הדברים שנאמרו ביחסים בין אדם וביתו מביאים מה ש\u0003אמר רב יהודה: לעולם יהא אדם זהיר בתבואה בתוך ביתו,\u0004 שתמיד תהיה תבואה בבית, לפי \u0003שאין מריבה מצויה בתוך ביתו של אדם אלא על עסקי תבואה, שנאמר \"השם גבולך שלום חלב חטים ישביעך\"\u0004 (תהילים קמז, יד), שאם חלב חטים בבית — שלום בו. \u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[הוא שאומרים אנשים]\u0006 כפתגם מקובל: \u0003כמשלם שערי מכדא נקיש ואתי תגרא בביתא\u0004 \u0005[כאשר נגמרים השעורים מן הכד מקישה ובאה התיגרה בבית].\u0006","\u0003ואמר רב חיננא בר פפא: לעולם יהא אדם זהיר\u0004 שתהא \u0003תבואה בתוך ביתו, שלא נקראו ישראל \"דלים\" אלא על עסקי תבואה\u0004 שנלקחה מהם, \u0003שנאמר: \"והיה אם זרע ישראל\u0004 ועלה מדין ועמלק ובני קדם\u0003\"\u0004 (שופטים ו, ג) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויחנו עליהם\u0004 וישחיתו את יבול הארץ\u0003\"\u0004 (שם ד). ונאמר \u0003\"וידל ישראל מאד מפני מדין\"\u0004 (שם ו).","\u0003אמר ר' חלבו: לעולם יהא אדם זהיר בכבוד אשתו, שאין ברכה מצויה בתוך ביתו של אדם אלא בשביל אשתו,\u0004 ורמז לדבר, \u0003שנאמר \"ולאברם הטיב בעבורה\u0004 ויהי לו צאן ובקר\u0003\"\u0004 (בראשית יב, טז). \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא לבני מחוזא\u0004 עירו: \u0003אוקירו לנשייכו, כי היכי דתתעתרו\u0004 \u0005[כבדו את נשיכם כדי שתתעשרו\u0006 בזכות זאת\u0005].\u0006","עוד מעשה שהיה קשור בענייני אונאת דברים. \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 תנור של חרס ש\u0003חתכו חוליות\u0004 חוליות לרוחבו, \u0003ונתן חול בין חוליא לחוליא, ר' אליעזר מטהר,\u0004 שלדעתו כיון שיש הפסק חול בין החוליות אין זה נחשב ככלי שלם, ואיננו מקבל טומאה. \u0003וחכמים מטמאין,\u0004 שהרי בפועל תנור שלם הוא וראוי למלאכה."],["\u0003וזה הוא\u0004 הקרוי \u0003תנור של עכנאי.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005],\u0006 ומדוע קוראים לו \u0003עכנאי\u0004 (נחש)? \u0003אמר רב יהודה אמר שמואל: שהקיפו\u0004 עליו חכמים \u0003דברים כעכנא זו,\u0004 כנחש זה השוכב בעיגול, \u0003וטמאוהו. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 ב\u0003אותו היום\u0004 שדנו בדבר, \u0003השיב ר' אליעזר כל תשובות שבעולם\u0004 להוכיח דעתו \u0003ולא קיבלו\u0004 חכמים \u0003הימנו\u0004 (ממנו), ולא הודו לדבריו.","לבסוף כשלא יכול להוכיח בטענותיו \u0003אמר להם\u0004 לחכמים: \u0003אם הלכה כמותי\u0004 — \u0003חרוב זה יוכיח. נעקר חרוב ממקומו מאה אמה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003ארבע מאות אמה. אמרו לו\u0004 חכמים: \u0003אין מביאין ראיה מן החרוב\u0004 לענין הלכה. \u0003חזר ואמר להם: אם הלכה כמותי\u0004 — \u0003אמת המים\u0004 והמים שבתוכה \u0003יוכיחו. חזרו\u0004 המים אשר ב\u0003אמת המים לאחוריהם\u0004 וזרמו בכיוון ההפוך. \u0003אמרו לו: אין מביאין ראיה מאמת המים.\u0004","\u0003חזר ואמר להם: אם הלכה כמותי\u0004 — \u0003כותלי בית המדרש יוכיחו.\u0004 ואכן \u0003הטו כותלי בית המדרש ליפול. גער בהם ר' יהושע\u0004 בכתלים, \u0003אמר להם: אם תלמידי חכמים מנצחים זה את זה\u0004 (מתווכחים) \u0003בהלכה, אתם מה טיבכם\u0004 בריב זה? מספרים: \u0003לא נפלו\u0004 הכתלים \u0003מפני כבודו של ר' יהושע, ולא זקפו\u0004 לגמרי \u0003מפני כבודו של ר' אליעזר, ועדין מטין ועומדין.\u0004","\u0003חזר\u0004 ר' אליעזר \u0003ואמר להם: אם הלכה כמותי\u0004 — \u0003מן השמים יוכיחו. יצאתה\u0004 (יצאה) \u0003בת קול\u0004 משמים \u0003ואמרה\u0004 להם: \u0003מה לכם אצל ר' אליעזר שהלכה כמותו בכל מקום.\u0004","\u0003עמד ר' יהושע על רגליו ואמר:\u0004 כבר נאמר בתורה: \u0003\"לא בשמים היא\"\u0004 (דברים ל, יב). ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעותו של פסוק זה \u0003\"לא בשמים היא\"\u0004 לענייננו? \u0003אמר ר' ירמיה: שכבר נתנה תורה מהר סיני,\u0004 ועל כן \u0003אין אנו משגיחין בבת קול, שכבר כתבת בהר סיני בתורה \"אחרי רבים להטת\"\u0004 (שמות כג, ב), וכיון שדעת הרבים בניגוד לר' אליעזר, אין הלכה כמותו. מסופר: שנים רבות לאחר אותו מעשה, \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003ר' נתן לאליהו\u0004 הנביא, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי עביד קודשא בריך הוא בההיא שעתא\u0004 \u0005[מה עשה הקדוש ברוך הוא באותה שעה]\u0006 שאמר ר' יהושע מה שאמר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קא חייך\u0004 \u0005[חייך]\u0006 \u0003ואמר: \"נצחוני בני, נצחוני בני\",\u0004 שהרי הביאו ראיה מן התורה.","\u0003אמרו: אותו היום הביאו כל טהרות שטיהר ר' אליעזר\u0004 על ידי תנור זה, \u0003ושרפום באש. ונמנו עליו\u0004 בהצבעה \u0003וברכוהו\u0004 (בלשון נקיה: נידו אותו). \u0003ואמרו: מי ילך ויודיעו\u0004 שהוא מנודה? \u0003אמר להם ר' עקיבא\u0004 שהיה תלמידו ואוהבו: \u0003אני אלך, שמא ילך אדם שאינו הגון\u0004 ויודיעו בדרך מכאיבה ומעליבה, \u0003ונמצא מחריב את כל העולם כולו.\u0004","\u0003מה עשה ר' עקיבא?\u0004 — \u0003לבש\u0004 בגדים \u0003שחורים ונתעטף שחורים\u0004 כביטוי של אבל וצער, \u0003וישב לפניו בריחוק ארבע אמות\u0004 כדרך שמרחיקין מן המנודה. \u0003אמר לו ר' אליעזר: עקיבא מה יום מיומים\u0004 שאתה לבוש ויושב כך? \u0003אמר לו: רבי, כמדומה לי שחבירים בדילים ממך,\u0004 כלומר, אמר בלשון עדינה: שהבדילוך מהם. \u0003אף הוא,\u0004 ר' אליעזר, \u0003קרע בגדיו וחלץ מנעליו\u0004 כדרך שנוהג המנודה, \u0003ונשמט\u0004 מכסאו, \u0003וישב על גבי קרקע.\u0004","מספרים: \u0003זלגו עיניו דמעות, לקה העולם\u0004 כולו: \u0003שליש בזיתים, ושליש בחטים ושליש בשעורים. ויש אומרים: אף בצק שבידי אשה טפח,\u0004 והתקלקל. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 חרון \u0003אף גדול היה באותו היום, שבכל מקום שנתן בו עיניו ר' אליעזר\u0004 היה \u0003נשרף.\u0004","\u0003ואף רבן גמליאל,\u0004 שעמד בראש החכמים ביבנה, ועל פיו עשו מה שעשו, \u0003היה בא בספינה\u0004 באותה שעה, \u0003עמד עליו נחשול\u0004 שבים \u0003לטבעו. אמר: כמדומה לי שאין זה אלא בשביל ר' אליעזר בן הורקנוס,\u0004 שמפני צערו וכאבו מענישים כל מי שפגע בו. \u0003עמד על רגליו ואמר: רבונו של עולם! גלוי וידוע לפניך שלא לכבודי עשיתי\u0004 לנדותו, \u0003ולא לכבוד בית אבא עשיתי, אלא לכבודך, שלא ירבו מחלוקות בישראל.\u0004 ואז \u0003נח הים מזעפו.\u0004","מסופר: \u0003אימא שלום דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003ר' אליעזר אחתיה\u0004 \u0005[אחותו]\u0006 של \u0003רבן גמליאל הואי\u0004 \u0005[היתה].\u0006 \u0003מההוא\u0004 \u0005[מאותו]\u0006 \u0003מעשה ואילך, לא הוה שבקה ליה\u0004 \u0005[לא הניחה לו]\u0006 \u0003לר' אליעזר למיפל על אפיה\u0004 \u0005[ליפול על פניו],\u0006 שבשעת תפילת נפילת אפיים אדם מתחנן תחנונים מיוחדים, ופחדה שאז יתחנן ויבכה על צערו, וייענש אחיה בשל כך. \u0003ההוא יומא ריש ירחא הוה ואיחלף\u0004 \u0005[אותו יום ראש חדש היה, והתחלף]\u0006 \u0003לה בין מלא לחסר,\u0004 שהיא חשבה שיום זה ראש חודש הוא, ואין בו נפילת אפיים, וטעתה, שלא היה זה ראש חדש, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אתא עניא וקאי אבבא, אפיקא ליה ריפתא\u0004 \u0005[שבא עני ועמד על הדלת,\u0006 והיא \u0005הוציאה לו פת],\u0006 מכל מקום, באותה שעה לא השגיחה עליו,","\u0003אשכחתיה דנפל על אנפיה\u0004 \u0005[מצאתו שהוא נופל על פניו\u0006 בתפילה\u0005].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003קום,\u0004 כבר \u0003קטלית לאחי\u0004 \u0005[הרגת את אחי].\u0006 \u0003אדהכי נפק שיפורא\u0004 \u0005[בינתיים יצא\u0006 קול \u0005שופר]\u0006 \u0003מבית רבן גמליאל\u0004 להורות לרבים \u0003דשכיב\u0004 \u0005[שמת]\u0006 הנשיא. \u0003אמר לה: מנא\u0004 \u0005[מנין]\u0006 \u0003ידעת\u0004 שימות? \u0003אמרה לו: כך מקובלני מבית אבי אבא: כל השערים ננעלים חוץ משערי אונאה.\u0004 ואדם שמצערים אותו, כך קורה למצריו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המאנה\u0004 (המצער) \u0003את הגר, עובר בשלשה לאוין\u0004 (מצוות \"לא תעשה\"), \u0003והלוחצו\u0004 (דוחקו) בענייני ממונות, ובדברים אחרים \u0003עובר בשנים.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 דין ה\u0003מאנה, דכתיבי\u0004 \u0005[שנאמרו]\u0006 \u0003שלשה לאוין\u0004 בו: \u0003\"וגר לא תונה\"\u0004 (שמות כב, כ), \u0003\"וכי יגור אתך גר בארצכם לא תונו אתו\"\u0004 (ויקרא יט, לג), \u0003\"ולא תונו איש את עמיתו\"\u0004 (ויקרא כה, יז), \u0003וגר בכלל \"עמיתו\" הוא.\u0004 אם כן שלשה איסורים הם. ואולם \u0003לוחצו נמי\u0004 \u0005[גם כן]\u0006 \u0003שלשה כתיבי\u0004 \u0005[נאמרו]:\u0006 \u0003\"\u0004וגר לא תונה \u0003ולא תלחצנו\"\u0004 (שמות כב, ב), \u0003\"וגר לא תלחץ\"\u0004 (שמות כג, ט), \u0003\"לא תהיה לו כנשה\"\u0004 (שמות כב, כד). ופסוק זה כללי הוא, והרי גר בכלל הוא! \u0003אלא\u0004 כך יש לומר: \u0003אחד זה,\u0004 המאנה את הגר, \u0003ואחד זה,\u0004 הלוחץ אותו, עובר \u0003בשלשה\u0004 לאווין. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006","\u0003ר' אליעזר הגדול אומר: מפני מה הזהירה תורה בשלשים וששה מקומות, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003בארבעים וששה מקומות בגר\u0004 שלא לצער אותו — \u0003מפני שסורו רע,\u0004 שעלול הדבר להחזירו לדרך רעה.","\u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"וגר לא תונה ולא תלחצנו, כי גרים הייתם בארץ מצרים\"\u0004 (שמות כב, כ), \u0003תנינא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר:\u0004 פירוש הכתוב הוא: \u0003מום שבך אל תאמר לחברך,\u0004 שהרי ישראל עצמם גרים היו, וכיצד יכולים הם להעליב גר אחר? \u0003והיינו דאמרי אינשי\u0004 \u0005[והוא שאומרים בני אדם]\u0006 כפתגם מקובל: \u0003דזקיף ליה זקיפא בדיותקיה\u0004 \u0005[מי שיש לו תלוי במשפחתו]\u0006 \u0003לא נימא ליה לחבריה זקיף ביניתא\u0004 \u0005[יאמר לו לחבירו תלה לי דג].\u0006 שעצם לשון \"תליה\" גנאי הוא לאותה משפחה, ואין הם מזכירים לשון זו מפני הבושה.","\u0003אין מערבין פירות בפירות,\u0004 שאם מוכר אדם פירות ממקום מסויים אינו רשאי לערב בהם פירות אחרים, ו\u0003אפילו\u0004 פירות \u0003חדשים בחדשים,\u0004 שאין בכך לכאורה כל הפסד לקונה."],["\u0003ואין צריך לומר\u0004 שאסור לערב \u0003חדשים בישנים\u0004 לפי שהישנים מעולים, ונמצא שהוא מוריד מן הערך.","\u0003באמת אמרו: ביין התירו לערב קשה\u0004 (חזק) \u0003ברך\u0004 (רפה), \u0003מפני שהוא משביחו\u0004 בתערובת זו. ו\u0003אין מערבין שמרי יין ביין\u0004 בכוונה, \u0003אבל נותן לו את שמריו\u0004 של אותו יין ואינו צריך לסנן.","\u0003מי שנתערב מים ביינו,\u0004 במקרה, \u0003לא ימכרנו בחנות\u0004 כיין, \u0003אלא אם כן הודיעו\u0004 לקונה שיידע שיש בו מים. \u0003ולא\u0004 ימכרנו כלל \u0003לתגר\u0004 (סוחר), \u0003אף על פי שהודיעו.\u0004 שאף שהתגר יודע, יש לחשוש \u0003שאינו אלא לרמות בו,\u0004 שמא ימכרנו התגר בתור יין טהור. ואולם \u0003מקום שנהגו להטיל מים ביין,\u0004 והכל יודעים שביין יש מעט מים — \u0003יטילו.\u0004","איסור זה בתערובת פירות נאמר רק בבעל הבית המוכר פירות שדהו, אבל \u0003התגר נוטל מחמש גרנות\u0004 של אנשים שונים, \u0003ונותן לתוך מגורה\u0004 (מחסן) \u0003אחת.\u0004 וכן נוטל \u0003מחמש גתות\u0004 של יין, \u0003ונותן לתוך פיטום\u0004 (כד גדול) \u0003אחד, ובלבד שלא יהא מתכוין לערב\u0004 דבר פחות ערך במשובח.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין צריך לומר\u0004 שאם היו \u0003חדשות מארבע\u0004 סאין בסלע, \u0003וישנות משלש\u0004 סאין, ש\u0003אין מערבין,\u0004 שהרי זו מרמה ממש שמוכר לו דבר זול במחיר דבר יקר. \u0003אלא אפילו חדשות\u0004 הם \u0003משלש, וישנות מארבע, אין מערבין,\u0004 למרות שמחירן גבוה יותר. \u0003מפני שאדם רוצה לישנן\u0004 את החדשות, כי אולי רוצה אותו אדם לשמור את החיטים לזמן ממושך, ולכן חשוב לו שתהיינה חדשות, כדי שיוכל להשאירן למשך זמן רב.","ולכן שנינו במשנה: \u0003באמת אמרו ביין התירו לערב קשה ברך, מפני שהוא משביחו.\u0004 על כן \u0003אמר ר' אלעזר: עדא אמרה\u0004 (זאת אומרת) \u0003כל \"באמת אמרו\" הלכה היא.\u0004 שבביטוי זה מציגים הלכה קבועה ופסוקה, שאין לפקפק בה.","\u0003אמר רב נחמן: ובין הגיתות שנו,\u0004 שתערובת זו של יינות עולה יפה רק כשמערבין יין חדש שעדיין לא תסס כל צרכו, והם מתערבים יפה ותוססים יחד, וטעמם משביח. אבל לאחר מכן אין התערובת עולה תמיד יפה.","ושואלים: \u0003והאידנא דקא מערבי\u0004 \u0005[ועכשיו\u0006 בימינו \u0005שמערבים]\u0006 יין \u0003שלא בין הגיתות,\u0004 על סמך מה עושים כן? \u0003אמר רב פפא: דידעי וקא מחלי\u0004 \u0005[ש\u0006הכל \u0005יודעים ומוחלים]\u0006 על ההפסד שעלול להיגרם. \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003רב אחא היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005].\u0006 \u0003ר' אחא מתיר\u0004 לערב \u0003בדבר הנטעם.\u0004 שאם אפשר להבחין מיד בטעם שיש כאן תערובת, אין איסור בדבר, שהרי אין כאן מרמה.","שנינו במשנה: \u0003אין מערבין שמרי יין ביין, אבל נותן לו את שמריו.\u0004 ותוהים על המשנה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת רישא\u0004 \u0005[בראשה]\u0006 ש\u0003אין מערבין כלל! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נותן לו את שמריו\"\u0004 — \u0003דקא מודע ליה\u0004 \u0005[שמודיע לו]\u0006 שיש ביין שמרים, \u0003הא מדקתני סיפא\u0004 \u0005[הרי ממה ששנה בסוף],\u0006 \u0003לא ימכרנו בחנות, אלא אם כן מודיעו, ולא לתגר אף על פי שמודיעו. מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[שבראשה]\u0006 אין הדבר תלוי בהודעה, אלא \u0003אף על גב דלא מודע ליה\u0004 \u0005[אף על פי שאינו מודיע לו],\u0006 מותר לערב שמריו!","\u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין \u0005:\u0006 \u0003אין מערבין שמרים של אמש,\u0004 מיין שמזג אמש ונשארו בו שמרים, \u0003בשל יום. ולא של יום בשל אמש, אבל נותן לו את שמריו\u0004 של אותו יין עצמו. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003ר' יהודה אומר: השופה יין לחבירו \u0004 (המוזג משקה ומשתדל שישארו החלקים המוצקים בתוך הכלי הראשון, ומוזג רק משקה צלול) — \u0003הרי זה לא יערב של אמש בשל יום, ולא של יום בשל אמש. אבל מערב\u0004 שמרים \u0003של אמש בשל אמש, ושל יום בשל יום.\u0004","עוד שנינו במשנה כי \u0003מי שנתערב מים ביינו, הרי זה לא ימכרנו בחנות, אלא אם כן מודיעו\u0004 לקונה על כך. מסופר: \u0003רבא אייתו ליה חמרא מחנותא\u0004 \u0005[הביאו לו יין מהחנות]\u0006 \u0003מזגיה, טעמיה,\u0004 \u0005[מזג אותו\u0006 במים, \u0005טעם ממנו]\u0006 ו\u0003לא הוה בסים\u0004 \u0005[היה טעים],\u0006 \u0003שדריה לחנותא\u0004 \u0005[שלח אותו\u0006 בחזרה \u0005לחנות]\u0006 שימכרוהו שם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003ולא לתגר, אף על פי שהודיעו.\u0004 ואתה הרי שלחת יין מזוג לתגר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מזגא דידי מידע ידיע\u0004 \u0005[מזיגת היין שלי ניכרת]\u0006 לכל, כיון שאני מוסיף הרבה מים, יותר מן הרגיל. \u0003וכי תימא דטפי, ומחייליה, ומזבין ליה\u0004 \u0005[ואם תאמר ש\u0006הוא \u0005מוסיף\u0006 יין, \u0005וממתיק אותו\u0006 ושוב \u0005מוכר אותו],\u0006 ושוב אין מזיגתו ניכרת, \u0003אם כן\u0004 אתה חושש, הרי \u0003אין לדבר סוף.\u0004 שאסור יהיה למכור לו כל יין, שמא יזייפנו.","שנינו במשנה: \u0003מקום שנהגו להטיל מים ביין\u0004 — \u0003יטילו. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 יטילו \u0003למחצה לשליש ולרביע,\u0004 הכל לפי מנהג המקום. \u0003אמר רב: ובין הגיתות שנו,\u0004 כלומר, לפני שתסס היין. אבל לאחר הגת יש לחשוש שמא תקלקל המהילה את היין כולו.","\u0003ר' יהודה אומר: לא יחלק החנוני קליות\u0004 (חיטין קלויות, שהיו מעדן) \u0003ואגוזין\u0004 במתנה \u0003לתינוקות\u0004 הבאים לקנות, \u0003מפני שהוא מרגילן לבא אצלו,\u0004 והוא מקפח על ידי כך את החנוונים האחרים. \u0003וחכמים מתירין. ולא יפחות את השער\u0004 למכור בפחות מן המחיר המקובל, \u0003וחכמים אומרים:\u0004 אם רצונו לפחות מן המחיר אותו גובים אחרים, הריהו \u0003זכור לטוב.\u0004","ו\u0003לא יבור את הגריסין\u0004 (פול נגרס בריחיים) להוציא מהם את הפסולת, ואחר כך יגבה מחיר גבוה יותר, אלו \u0003דברי אבא שאול\u0004 — שחושש שמא יקח בעד הגריסים הנקיים יותר מכפי ערכם. \u0003וחכמים מתירין. ומודים\u0004 חכמים, \u0003שלא יבור מעל פי מגורה.\u0004 כלומר, רק מן הפירות המצויים בפתחה של המגורה, \u0003שאינו אלא כגונב את העין.\u0004 שהרי נדמה לאנשים שהכל נקי ומבורר, ולבסוף מתברר שהרוב אינו מבורר. \u0003אין מפרכסין\u0004 (מקשטים) \u0003לא את האדם\u0004 — העבד — שמוכרים אותו, \u0003ולא את הבהמה, ולא את הכלים,\u0004 אלא מוכרים אותם כמות שהם, כדי שלא לגרום שיוטעה הקונה.","שואלים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים],\u0006 שמתירים לחלק קליות ואגוזים? ומשיבים: \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 חנווני זה לחבירו הטוען כנגדו על תחרות בלתי הוגנת, \u0003אנא מפליגנא אמגוזי, ואת פליג שיסקי\u0004 \u0005[אני מחלק אגוזים, ואתה חלק שזיפים],\u0006 שהרי גם אתה יכול לעשות דברים למשוך אליך את הקונים.","שנינו במשנה: \u0003ולא יפחות את השער, וחכמים אומרים: זכור לטוב.\u0004 ושואלים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה טעמם של חכמים]?\u0006 לא זו בלבד שאמרו שהדבר מותר, אלא אף הוסיפו לו ברכה: \"זכור לטוב\"?"],["\u0003משום דקא מרווח לתרעא\u0004 \u0005[שהוא מרוויח את השער],\u0006 כלומר, שהוא עשוי לגרום להוריד במקצת את שער הפירות בכל האיזור.","שנינו במשנה: \u0003ולא יבור את הגריסין,\u0004 אלו \u0003דברי אבא שאול. וחכמים מתירין.\u0004 ומעירים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 כאן — \u0003ר' אחא\u0004 הוא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אחא מתיר\u0004 לערב ולברר וכיוצא באלה, \u0003בדבר הנראה.\u0004 וגם כאן אנשים יכולים לראות כמה נברר, וכמה כדאי להם להוסיף על המחיר.","שנינו במשנה: \u0003אין מפרכסין, לא את האדם, ולא את הבהמה, ולא את הכלים. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין משרבטין\u0004 \u0003את הבהמה, ואין נופחים בקרביים\u0004 (במעיים) הנמכרים כבשר, שיראו גדולים יותר, \u0003ואין שורין את הבשר במים\u0004 שישתנה צבעו ויהא נראה כמובחר יותר. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין משרבטין\"? הכא תרגמו\u0004 \u0005[כאן,\u0006 בבבל, \u0005הסבירו],\u0006 שמשקים אותה \u0003מיא דחיזרא\u0004 \u0005[מי חיזרן],\u0006 והם גורמים לה שתתנפח, וניראית שמנה יותר. \u0003זעירי אמר\u0004 בשם \u0003רב כהנא: מזקפתא,\u0004 שמקרצפים ומנקים אותה, והיא נראית יפה יותר.","מסופר: \u0003שמואל שרא למרמא תומי לסרבלא\u0004 \u0005[התיר להטיל גדילים בסרבל].\u0006 \u0003רב יהודה שרא לכסכוסי קרמי\u0004 \u0005[התיר לנקות\u0006 ולקשט \u0005בגדים מצוירים].\u0006 \u0003רבה שרא למידק צרדי\u0004 \u0005[התיר להדק בגדי פשתן]\u0006 שייראו דקים יותר. \u0003רבא שרא לצלומי גירי\u0004 \u0005[התיר לצייר חצים].\u0006 \u0003רב פפא בר שמואל שרא לצלומי דיקולי\u0004 \u0005[לצייר סלים].\u0006 ושואלים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005],\u0006 \u0003אין מפרכסין לא את האדם, ולא את הבהמה, ולא את הכלים!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא בחדתי\u0004 \u0005[זה בחדשים],\u0006 מותר לקשטם, שאינו אלא מיפה אותם. ו\u0003הא בעתיקי\u0004 \u0005[זה בישנים],\u0006 שהקישוט גורם שלא יבחינו במומים ובפגמים שבהם. ושואלים: \u0003פרכוס\u0004 של \u0003אדם מאי היא\u0004 \u0005[מה הוא]?\u0006 ומספרים: \u0003כי הא דההוא עבדא סבא דאזל צבעיה לרישיה ולדיקניה\u0004 \u0005[כמו זה\u0006 שאירע \u0005בעבד אחד שהלך וצבע את ראשו וזקנו]\u0006 בצבע שחור שיראה צעיר. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיבנן\u0004 \u0005[קנה אותי]\u0006 כעבד! \u0003אמר ליה\u0004 \u0005[לו],\u0006 אמרו חכמים: \u0003\"יהיו עניים בני ביתך\"\u0004 וכך אני נוהג. ולמה לי לקנות עבד, כאשר מתהלכים בביתי עניים, שאם אני נזקק לשרות — הם עושים אותו.","\u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב פפא בר שמואל, זבניה\u0004 \u0005[קנה אותו].\u0006 \u0003יומא חד\u0004 \u0005[יום אחד]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לעבד: \u0003אשקיין מיא\u0004 \u0005[השקני מים],\u0006 \u0003אזל חווריה לרישיה ולדיקניה\u0004 \u0005[הלך והלבין,\u0006 הוריד את הצבע, \u0005מראשו ומזקנו].\u0006 \u0003אמר ליה\u0004 העבד לאדוניו: \u0003חזי דאנא קשיש מאבוך\u0004 \u0005[ראה שאני זקן מאביך],\u0006 ואין אני יכול לעשות מלאכה. \u0003קרי אנפשיה\u0004 \u0005[קרא\u0006 רב פפא בר שמואל \u0005על עצמו],\u0006 בשינוי מה, את דברי הכתוב: \u0003\"צדיק מצרה נחלץ, ויבא אחר תחתיו\"\u0004 (משלי יא, ח). שבמקרא נאמר: \"ויבוא רשע תחתיו\", והוא התאים פסוק זה לעניין רבא (שהוא \"צדיק\") נחלץ מצרה זו, ו\"אחר\" — הוא עצמו, נכנס תחתיו.","","","\u0003איזהו נשך ואיזהו תרבית\u0004 שנאסרו בתורה? \u0003איזהו נשך\u0004 — \u0003המלוה סלע,\u0004 שערכו הוא ארבעה דינרים, כדי לקבל \u0003חמשה דינרים.\u0004 או מלוה \u0003סאתים חטין\u0004 כדי לקבל \u0003שלש,\u0004 זה \u0003אסור מפני שהוא נושך,\u0004 שלוקח במפורש סכום גדול יותר ממה שנתן. \u0003ואיזהו תרבית\u0004 — \u0003המרבה בפירות,\u0004 כלומר, עושה עיסקה ועל ידה מרבה לעצמו פירות יתר על מה שהשקיע. עיסקות אלה של ריבית עשויות להיערך בלא שהריבית שבהן מפורשת. \u0003כיצד? לקח הימנו\u0004 (קנה אצלו) \u0003חטין בדינר זהב\u0004 (שהוא עשרים וחמישה דינרי כסף) \u0003הכור, וכן השער\u0004 של החיטים באותה שעה. אחר כך \u0003עמדו חטין בשלשים דינרים,\u0004 חמישה דינרים יותר.","","","\u0003אמר לו\u0004 הקונה: \u0003תן לי\u0004 עכשיו את \u0003חטיי, שאני רוצה למוכרן וליקח\u0004 (לקנות) \u0003בהן יין. אמר לו\u0004 המוכר: כיון שאינך נזקק לחיטים אלא לכסף, \u0003הרי חטיך עשויות עלי\u0004 (נחשבות אצלי) במחירן עכשיו \u0003בשלשים\u0004 דינר, \u0003והרי לך אצלי בהן יין\u0004 במחיר זה \u0003ויין אין לו.\u0004 ואם יעלה מחיר היין נמצא שבסופו של דבר היתה כאן עיסקה של ריבית — שמוסיף על מה שהיה חייב לו מתחילה.","תחילה דנים בגמרא על עיקרי ההגדרות האמורות במשנתנו, ואומרים: \u0003מדשביק\u0004 \u0005[מ\u0006כיון \u0005שהניח]\u0006 דין \u0003ריבית דאורייתא\u0004 \u0005[שמן התורה],\u0006 ולא הביא במשנה עצמה דוגמא ברורה לריבית, \u0003וקא מפרש\u0004 \u0005[ומפרש]\u0006 במשנה לא מקרה של הלוואה, שיש בה תנאי של אחוזי ריבית, והדוגמא שמביא היא מקרה מסובך יותר, שאינו אסור אלא \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003מכלל\u0004 דברים אלה אתה למד כי \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003נשך ותרבית\u0004 — \u0003חדא מלתא היא\u0004 \u0005[דבר אחד הוא],\u0006 ואין הבדל ביניהם להלכה. ומקשים: \u0003והא קראי כתיבי\u0004 \u0005[והרי נאמרו כתובים]\u0006 שמדובר בהם על \u0003נשך כסף וריבית אוכל,\u0004 ומדוע איננו מפרש כך?","ודוחים: \u0003ותיסברא\u0004 \u0005[וכי יכול אתה לסבור,\u0006 להבין כך\u0005],\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003נשך בלא תרבית, ותרבית בלא נשך?\u0004 ומפרטים: \u0003נשך בלא תרבית היכי דמי\u0004 \u0005[כיצד יכול להיות],\u0006 שהרי בהכרח בכל הלוואת ריבית יש גם נשך — שלוקח מן הלווה משהו, וגם תרבית — שמוסיף לעצמו על מה שהלוה.","שכן, \u0003אי דאוזפיה\u0004 \u0005[אם שהלוה לו]\u0006 \u0003מאה\u0004 פרוטות \u0003ב\u0004עד \u0003מאה ועשרים,\u0004 הלא \u0003מעיקרא קיימי\u0004 \u0005[מתחילה\u0006 היו \u0005עומדות]\u0006 \u0003מאה\u0004 פרוטות \u0003בדנקא\u0004 \u0005[במעה\u0006 כסף\u0005],\u0006 \u0003לבסוף קיימי\u0004 \u0005[עומדות]\u0006 \u0003מאה ועשרים\u0004 \u0003בדנקא\u0004 \u0005[במעה\u0006 כסף\u0005],\u0006 שירד ערך הפרוטות, והן שוות רק מאה ועשרים במעה, ואז לכאורה \u0003נשך איכא\u0004 \u0005[יש\u0006 כאן\u0005]\u0006 — \u0003דקא נכית ליה, דקא שקיל מיניה מידי\u0004 \u0005[שהוא נושך אותו, שהוא לוקח ממנו דבר]\u0006 ש\u0003לא יהיב\u0004 \u0005[נתן]\u0006 \u0003ותרבית,\u0004 תוספת, \u0003ליכא, דלית ליה רווחא\u0004 \u0005[אין כאן, שאין לו רווח],\u0006 \u0003דדנקא אוזפיה ודנקא קא שקיל מיניה\u0004 \u0005[שמעה הלווה לו, ומעה לקח ממנו].\u0006","ואולם דבר זה הוא רק לכאורה כי \u0003סוף סוף, אי בתר מעיקרא אזלת\u0004 \u0005[אם אחר,\u0006 לפי, \u0005ההתחלה אתה הולך],\u0006 \u0003הרי נשך והרי תרבית, אי בתר\u0004 \u0005[אם אחר]\u0006 ה\u0003סוף אזלת\u0004 \u0005[אתה הולך]\u0006 \u0003לא נשך איכא\u0004 \u0005[יש],\u0006 \u0003ולא תרבית איכא\u0004 \u0005[יש],\u0006 שהרי מתברר כי לא שילם ולא קיבל יותר מן הערך עכשיו.","\u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003תרבית בלא נשך היכי דמי\u0004 \u0005[כיצד יכול להיות]?\u0006 \u0003אי דאוזיף\u0004 \u0005[אם שהלוה]\u0006 לו \u0003מאה ב\u0004עד ה\u0003מאה,\u0004 אבל \u0003מעיקרא קיימי\u0004 \u0005[מתחילה עמדו,\u0006 היו שוות\u0005]\u0006 \u0003מאה\u0004 פרוטות \u0003בדנקא\u0004 \u0005[במעה],\u0006 \u0003ולבסוף מאה בחומשא\u0004 \u0005[בחמישית\u0006 דינר\u0005],\u0006 בעשרים פרוטות יותר.","אף כאן, \u0003אי בתר מעיקרא אזלת\u0004 \u0005[אם אחר ההתחלה אתה הולך]\u0006 — \u0003לא נשך איכא\u0004 \u0005[יש]\u0006 \u0003ולא תרבית איכא\u0004 \u0005[יש],\u0006 שהרי לא התכוון כלל לריבית. \u0003אי בתר\u0004 \u0005[אם אחר]\u0006 ה\u0003סוף אזלת\u0004 \u0005[אתה הולך]\u0006 \u0003הרי נשך והרי תרבית!\u0004","\u0003אלא אמר רבא: אי\u0004 (אין) \u0003אתה מוצא לא נשך בלא תרבית, ולא תרבית בלא נשך. ולא חלקן הכתוב\u0004 לשני איסורים \u0003אלא\u0004 כדי \u0003לעבור עליו בשני לאוין,\u0004 שבכל פעם שמלוה בריבית עובר משום שני איסורים. בדומה לדברים אלה \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 מדיוק לשון הכתוב \u0003\"את כספך לא תתן לו בנשך ובמרבית לא תתן אכלך\"\u0004 (ויקרא כה, לז), \u0003אין לי\u0004 שקיים איסור \u0003אלא נשך בכסף, ורבית באוכל. נשך באוכל מנין? תלמוד לומר: \"נשך אכל\"\u0004 (דברים כג, כ). \u0003רבית בכסף מנין? תלמוד לומר: \"נשך כסף\"\u0004 (שם),",""],["\u0003אם אינו ענין לנשך כסף\u0004 במובן המצומצם של המונח, \u0003שהרי כבר נאמר \"לא תשיך לאחיך\u0004 נשך כסף נשך אוכל נשך כל דבר אשר ישך\u0003\"\u0004 (דברים כג, כ) — \u0003תנהו ענין לרבית כסף\u0004 שהיא קרובה בעניינה לנשך.","\u0003אין לי\u0004 ראיה מן הכתוב לאיסור זה \u0003אלא בלוה\u0004 שאסור לו לשלם ריבית (\"תשיך\" — תתן לאחר לנשוך), \u0003במלוה מנין\u0004 ראיה לאיסור?","ומשיבים: ש\u0003נאמר\u0004 איסור \u0003\"נשך\" בלוה, ונאמר \"נשך\" במלוה,\u0004 והם למדים זה מזה לגבי תוכנם. \u0003מה \"נשך\" האמור בלוה\u0004 — כבר הוכחנו כי \u0003לא חלקת בו בין בכסף בין באוכל, בין בנשך בין ברבית,\u0004 שהכל אסור. \u0003אף \"נשך\" האמור במלוה לא תחלוק בו בין בכסף בין באוכל, בין בנשך בין ברבית. מנין לרבות כל דבר\u0004 שיש בו מעין ריבית שהוא אסור — \u0003תלמוד לומר: \"נשך כל דבר אשר ישך\"\u0004 (שם).","\u0003רבינא אמר: לא נשך באוכל ולא רבית בכסף צריכי קרא\u0004 \u0005[צריכים כתוב\u0006 מפורש\u0005],\u0006 \u0003דאי כתיב\u0004 \u0005[שאילו נאמר]:\u0006 \u0003\"את כספך לא תתן לו בנשך ואכלך במרבית\"\u0004 — שמחלק הפסוק בין נשך ומרבית, היה הפירוש \u0003כדקאמרת\u0004 \u0005[כפי שאתה אומר],\u0006 ו\u0003השתא דכתיב\u0004 \u0005[ועכשיו שנאמר]:\u0006 \u0003\"את כספך לא תתן לו בנשך ובמרבית לא תתן אכלך\"\u0004 — משמע שאין נשך ומרבית חלוקים, \u0003קרי ביה הכי\u0004 \u0005[קרא בו,\u0006 את הפסוק, \u0005כך]:\u0006 \u0003\"את כספך לא תתן לו בנשך ובמרבית\",\u0004 וכן \u0003\"ובנשך ובמרבית לא תתן אכלך\".\u0004","על הסברו של רבינא מקשים: \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003תנא\u0004 \u0003\"נאמר\" \"נאמר\" קאמר\u0004 \u0005[אמר],\u0006 שנראה שהוא לומד בדרך של גזירה שווה, וכיצד יכול רבינא לפרש בצורה שונה!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך הכוונה\u0005]:\u0006 \u0003אילו לא\u0004 היה \u0003נאמר קרא\u0004 \u0005[הכתוב]\u0006 בסגנון מיוחד זה, \u0003הייתי אומר גזירה שוה, עכשיו שנאמר קרא\u0004 \u0005[הכתוב]\u0006 כך — \u0003גזירה שוה לא צריך.\u0004 ושואלים: אם כן, \u0003אלא גזירה שוה\u0004 זו שבאה להשוות את שני הפסוקים \u0003למה לי?\u0004 ומשיבים: \u0003ל\"נשך כל דבר אשר ישך\"\u0004 (שם) ש\u0003לא כתב\u0004 \u0005[נאמר]\u0006 המקרא בפסוק הנזכר \u0003במלוה\u0004 אלא בלווה בלבד, והגזירה־שווה מלמדתנו שגם במלוה קיים איסור זה.","\u0003אמר רבא: למה לי דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003לאו\u0004 (איסור \"לא תעשה\") גם \u0003ב\u0004איסור \u0003ריבית\u0004 וגם \u0003לאו\u0004 \u0003בגזל\u0004 וגם \u0003לאו\u0004 \u0003באונאה?\u0004","והלא לכאורה כולם הם פרטים של איסור אחד \u0003—\u0004 להזהיר שלא יקח אדם ממון שאינו שייך לו! ומשיבים: \u0003צריכי\u0004 \u0005[צריכים\u0006 הם\u0005]\u0006 להיאמר, \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה]\u0006 רק \u0003לאו ברבית,\u0004 הייתי אומר שאין ללמוד ממנו \u0003משום\u0004 ש\u0003חידוש הוא,\u0004 שיש בדין זה צד חריג משאר דיני התורה — ש\u0003אפילו בלוה אסרה רחמנא\u0004 \u0005[התורה].\u0006 שהרי איסור גזל וגניבה חלים רק על הגזלן, ואילו בריבית חל האיסור גם על הלווה.","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 רק \u0003לאו בגזל\u0004 לא הייתי לומד מכאן, שהייתי סבור שהוא חמור יותר, משום שהוא לוקח ממון מהנגזל \u0003בעל כרחיה\u0004 \u0005[כרחו]\u0006 \u0003אבל אונאה\u0004 שעיקר העיסקה נעשתה ברצון — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהא בכך איסור.","\u0003ו\u0004להיפך, \u0003אי כתב רחמנא\u0004 \u0005[אילו היתה כותבת התורה]\u0006 רק \u0003לאו באונאה,\u0004 הייתי אומר שהוא חמור \u0003משום דלא ידע דמחיל\u0004 \u0005[שאינו יודע\u0006 שרימוהו ולכן אינו \u0005מוחל],\u0006 ואילו בריבית, למשל, שיודע ומוחל, אינו כן.","ומעירים: \u0003חדא מחדא לא אתיא\u0004 \u0005[אחת מאחת אינה באה,\u0006 אינה נלמדת\u0005]\u0006 שאין אפשרות ללמוד איסור אחד מחבירו, ואולם, \u0003תיתי חדא מתרתי\u0004 \u0005[שתבוא,\u0006 תלמד, \u0005אחת משתים\u0006 אחרות\u0005].\u0006 ושואלים: \u0003הי תיתי\u0004 \u0005[איך תבוא]?\u0006 נניח כי \u0003לא לכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003לאו ברבית ותיתי מהנך\u0004 \u0005[ותלמד מאלה]\u0006 מגזל ואונאה, ואולם אפשר לדחות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן שלא מדעת,\u0004 שהרי הם נלקחים שלא מדעת ולא מרצון, \u0003תאמר ברבית דמדעתיה\u0004 \u0005[שמדעתו]\u0006 הוא נותן.","ומצד אחר ש\u0003לא לכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003לאו באונאה ותיתי מהנך\u0004 \u0005[ותלמד מאלה],\u0006 מגזל וריבית, אפשר להקשות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן אין דרך מקח וממכר בכך,\u0004 אבל אונאה הרי היא נעשית בדרך המסחר הרגילה.","\u0003אלא\u0004 נאמר ש\u0003לא לכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003לאו בגזל ותיתי מהנך\u0004 \u0005[ותלמד מאלה];\u0006 \u0003דמאי פרכת\u0004 \u0005[ש\u0006כן \u0005מה תקשה]?\u0006 אם תקשה: \u0003מה לרבית שכן חידוש\u0004 — אפשר לטעון כנגד זה: \u0003אונאה תוכיח\u0004 שאין בה חידוש.","ואם תטען \u0003מה לאונאה שכן לא ידע ומחיל\u0004 \u0005[אינו יודע\u0006 כדי \u0005שימחל]\u0006 — אם כן \u0003רבית תוכיח,\u0004 שהרי יודע ומוחל!","\u0003וחזר הדין,\u0004 כלומר, הטיעון סובב וחוזר מצד זה לצד זה, ועיקרו של דבר אפשר לסכם: \u0003לא ראי זה כראי זה,\u0004 אין דבר זה נראה ודומה לדבר זה, \u0003ולא ראי זה כראי זה, הצד השוה שבהן שכן גוזלו,\u0004 שלוקח מאדם ממון שלא כדין, \u0003אף אני אביא גזל!\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003הכי נמי\u0004 \u0005[אכן, כך הוא גם כן],\u0006 שבאמת לאו זה אינו נחוץ, וניתן היה ללמדו מאחרים. ושואלים: \u0003אלא\u0004 אם כן \u0003לאו בגזל למה לי?\u0004 ומשיבים: איסור זה נצרך לא לגזילה ממש אלא \u0003לכובש שכר שכיר,\u0004 למי שאיננו משלם לשכיר את שכרו, שהוא שונה מגזל אחר שהרי אינו לוקח ממנו בפועל ממש, אף כי אינו משלם לו את חובו.","ומקשים: \u0003כובש שכר שכיר בהדיא כתיב ביה\u0004 \u0005[במפורש כתוב בו]\u0006 \u0003\"לא תעשק שכיר עני ואביון\"\u0004 (שם כד, יד)! ומשיבים: אף על פי כן נצרך גם הלאו שנאמר בגזל כדי \u0003לעבור עליו בשני לאוין,\u0004 שהעושה כך עובר גם משום \"לא תגזול\".","ושואלים: אם כן, \u0003ולוקמה\u0004 \u0005[ושיעמיד,\u0006 שייחס\u0005]\u0006 את הלאו הזה לענין \u0003רבית ואונאה, ולעבור עליו בשני לאוין,\u0004 שהלוקח ריבית או מאנה את רעהו עובר גם משום גזל! ומשיבים: הרי זה \u0003דבר הלמד מעניינו,\u0004 מהקשר הכתובים, שאיסור גזל נוגע ושייך לענין עושק השכיר,"],["\u0003ובעניינא\u0004 \u0005[ובענין]\u0006 ה\u0003שכיר כתיב\u0004 \u0005[נאמר],\u0006 שבסמיכות לדין שכיר נאמר גם דין גזל.","ושואלים עוד: \u0003\"לא תגנבו\"\u0004 (ויקרא יט, יא) \u0003דכתב רחמנא\u0004 \u0005[שתכה התורה]\u0006 \u0003למה לי?\u0004 שהרי זה איסור נוסף על נטילת ממון שלא כדין! ומשיבים: \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"לא תגנב\"\u0004 — הרי זה בא ללמד שהדבר אסור אפילו אם עושה כן \u0003על מנת למיקט\u0004 (לצער), שרוצה רק להקניט את חבירו וגונב ממנו על דעת שיחזיר לו, \u0003\"לא תגנבו\"\u0004 — אפילו \u0003על מנת לשלם תשלומי כפל,\u0004 שרוצה לתת כסף לחבירו במתנה בדרך זו.","ובאותו נושא \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי: לאו\u0004 (איסור \"לא תעשה\") \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003במשקלות\u0004 (\"לא תעשו עוול במשפט במידה...\". שם לה) \u0003למה לי?\u0004 הרי אף זה סוג של גזל! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לטומן משקלותיו במלח\u0004 כדי שאבני המשקל יקלו במשקלן. אמר לו: הלא \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003גזל מעליא הוא\u0004 ובמה שונה הוא משאר גזל? והשיב לו: \u0003לעבור עליו משעת עשייה,\u0004 שאף לפני שמשתמש באבני המשקל המזוייפות, כיון שעושה מעשה הזיוף, כבר עובר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"לא תעשו עול במשפט במדה במשקל ובמשורה\"\u0004 (שם). \u0003\"במדה\"\u0004 — \u0003זו מדידת קרקע,\u0004 כגון \u0003שלא ימדוד לאחד בימות החמה ולאחד בימות הגשמים,\u0004 מפני שחבל המדידה משתנה באורכו בעונות השנה השונות. \u0003\"במשקל\"\u0004 — \u0003שלא יטמין משקלותיו במלח\u0004 כד להקל משקלן. \u0003\"ובמשורה\"\u0004 — \u0003שלא ירתיח,\u0004 שלא ימזוג באופן שיעלו הנוזלים קצף ונמצאת המדה מלאה בפחות משיעורה.","ומוסיפים: \u0003והלא דברים קל וחומר: ומה משורה שהיא\u0004 מדה קטנה ששעורה \u0003אחד משלשים ושלשה בלוג הקפידה עליו תורה\u0004 שלא ירמה בה, \u0003קל וחומר להין\u0004 (שנים עשר לוג), \u0003וחצי הין, ושלישית ההין, ורביעית ההין, ולוג, וחצי לוג, ורביעית הלוג\u0004 שכל אלה גדולים הרבה מן המשורה, שלא ירמו בהם.","\u0003אמר רבא: למה לי דכתב רחמנא\u0004 \u0005[שכתבה תורה]\u0006 והזכירה \u0003יציאת מצרים\u0004 בדיני \u0003רבית\u0004 (\"את כספך לא תתן לו בנשך... אני ה'... אשר הוצאתי אתכם\". ויקרא כה, לז-לח), הזכרת \u0003יציאת מצרים\u0004 ל\u0003גבי ציצית\u0004 (\"ועשו להם ציצית... אני ה'... אשר הוצאתי אתכם...\" במדבר טו, לז-מא), \u0003יציאת מצרים במשקלות\u0004 (\"לא תעשו עוול ... במידה... אני ה' אשר הוצאתי אתכם...","\" ויקרא יט, לה-לו) — כך יש לדרוש, \u0003אמר הקדוש ברוך הוא: אני הוא שהבחנתי במצרים בין טפה\u0004 של זרע \u0003של בכור לטפה שאינה של בכור\u0004 והכיתי רק את הבכורים, \u0003אני הוא שעתיד ליפרע ממי שתולה מעותיו בגוי,\u0004 שאומר שהכסף שהוא מלוה אינו שלו, אלא של גוי, \u0003ומלוה אותו לישראל בריבית.\u0004 שגם אם יוכל להטעות את בית דין, הקדוש ברוך הוא ודאי יודע. \u0003ו\u0004כן \u0003ממי שטומן משקלותיו במלח\u0004 ואיש אינו יכול להוכיח זאת, או \u0003ממי שתולה קלא אילן\u0004 (צמר צבוע בצבע כחול) \u0003בבגדו ואומר תכלת הוא,\u0004 ולכן הוזכרה יציאת מצרים בכל אלה לומר שיזהר העבריין מפני הקדוש ברוך הוא היכול להבחין בעבירות אלה.","מסופר: \u0003רבינא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לסורא דפרת. אמר\u0004 לו \u0003רב חנינא מסורא דפרת לרבינא: יציאת מצרים דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003גבי שרצים\u0004 (\"אל תשקצו את נפשותיכם בכל השרץ השורץ... כי אני ה' המעלה אתכם מארץ מצרים\". ויקרא יא, מג. שם מה) \u0003למה לי? אמר\u0004 לו: \u0003אמר הקדוש ברוך הוא: אני הוא שהבחנתי בין טפה של בכור לטפה שאינה של בכור\u0004 ביציאתכם ממצרים, \u0003אני עתיד ליפרע ממי שמערב קרבי דגים טמאין בקרבי דגים טהורין ומוכרן לישראל,\u0004 והם אינם יכולים להבחין בדבר.","\u0003אמר\u0004 \u0003ליה\u0004 \u0005[לו]:\u0006 אין בעייתי ביחס להזכרת יציאת מצרים, אלא \u0003אנא\u0004 \u0005[אני]\u0006 לשון הכתוב \u0003\"המעלה\" קא קשיא\u0004 \u0005[קשה]\u0006 \u0003לי;\u0004 \u0003מאי שנא הכא\u0004 \u0005[מה,\u0006 מדוע \u0005שונה כאן]\u0006 \u0003\"המעלה\u0004 אתכם מארץ מצרים \u0003\" דכתב רחמנא\u0004 \u0005[שכתבה תורה]\u0006 ולא כרגיל \"המוציא אתכם\"?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לכדתנא דבי\u0004 \u0005[כמו ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, דתנא דבי רבי ישמעאל :\u0004 \u0003אמר הקדוש ברוך הוא: אילמלא\u0004 (אילו לא) \u0003(לא) העליתי את ישראל ממצרים אלא בשביל דבר זה, שאין מטמאין בשרצים\u0004 — \u0003דיי.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ומי נפיש אגרייהו טפי\u0004 \u0005[והאם גדול שכרם\u0006 של המקפידים על כך \u0005יותר]\u0006 \u0003מ\u0004המקפידים ב\u0003רבית ומציצית וממשקלות?\u0004 ומדוע לא נאמר בהן \"העליתי\"? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף על גב דלא נפיש אגרייהו טפי\u0004 \u0005[אף על פי שאין שכרם מרובה יותר],\u0006 מכל מקום \u0003מאיסי למכלינהו\u0004 \u0005[מאוסים\u0006 הם על ישראל יותר \u0005לאכול מהם]\u0006 ולכן שבחם ומעלתם (\"המעלה\") של ישראל הוא שמתרחקים מדברים אלה.","שנינו במשנה: \u0003ואיזהו תרבית המרבה בפירות, כיצד לקח הימנו חטים בדינר זהב\u0004 וכו' והוא מחליף מידי פעם ומעלה את המחיר, שעל ידי הדחייה משלם יותר. ושואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל הני דאמרינן\u0004 \u0005[אלה שאמרנו]\u0006 \u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003רבית הוא\u0004 \u0005[הם]\u0006 ורק מקרה זה הוא הריבית?!","\u0003אמר ר' אבהו:\u0004 להיפך, \u0003עד כאן\u0004 דובר במשנה על ריבית \u0003של תורה, מכאן ואילך\u0004 ריבית \u0003של דבריהם\u0004 (מדברי חכמים). שאם איננו מוסיף במפורש כסף על מה שהוא חייב אינו ריבית מן התורה, אף כי אסרו חכמים לעשות כן. \u0003וכן אמר רבא: עד כאן\u0004 — \u0003של תורה, מכאן ואילך\u0004 — \u0003של דבריהם.\u0004","ועוד: \u0003עד כאן\u0004 מתקיים \u0003\"יכין רשע וילבש צדיק\"\u0004 (ראה איוב כז, יז) המתפרש שאם האב הרשע לקח ריבית — אין הבן, אף שהוא צדיק, חייב להחזיר לבעלי החובות. ותוהים: \u0003עד כאן ותו לא\u0004 \u0005[ולא עוד],\u0006 הלא הסברה היא הפוכה: שאם בריבית האסורה מן התורה — כך, בריבית של דברי סופרים לא כל שכן! \u0003אלא\u0004 יש לשנות את הלשון ולומר: \u0003אפילו עד כאן \"יכין רשע וילבש צדיק\".\u0004","ועוד: \u0003עד כאן\u0004 מדובר ב\u0003רבית קצוצה\u0004 (קצובה) האסורה מן התורה, \u0003מכאן ואילך\u0004 מדובר ב\u0003אבק רבית,\u0004 שאין כאן סכום קצוב וברור המשולם בריבית.","\u0003אמר ר' אלעזר: רבית קצוצה\u0004 — \u0003יוצאה בדיינין.\u0004 כלומר, מי שנתן ריבית יכול לתבוע בבית הדין ולקבל בחזרה את הריבית ששילם. \u0003אבק רבית\u0004 שאיסורה רק מדברי חכמים — \u0003אינה יוצאה בדיינין,\u0004 ואילו \u0003ר' יוחנן אמר: אפילו רבית קצוצה נמי\u0004 \u0005[גם כן]\u0006 \u0003אינה יוצאה בדיינין.\u0004","\u0003אמר ר' יצחק: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוחנן\u0004 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בנשך נתן ותרבית לקח וחי לא יחיה את כל התועבות האלה עשה\u0004 מות יומת דמיו בו יהיה\u0003\"\u0004 (יחזקאל יח, יג), ומלמדנו הכתוב: \u0003למיתה ניתן,\u0004 שכן הוא נענש בידי שמים, אבל \u0003לא להשבון,\u0004 שאין בית דין יכולים לחייבו להשיב הכסף. \u0003רב אדא בר אהבה אמר\u0004 ראיה אחרת, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אל תקח מאתו נשך ותרבית ויראת מאלהיך\u0004 וחי אחיך עמך\u0003\"\u0004 (ויקרא כה, לו), ללמדנו: \u0003למורא ניתן,\u0004 שהעובר על כך פרק מעליו מורא שמים, \u0003ולא להשבון\u0004 בידי אדם.","\u0003רבא אמר: מגופיה דקרא שמיע ליה\u0004 \u0005[מגופו של הכתוב\u0006 ביחזקאל \u0005נלמד לו]\u0006 ולא רק מדיוק הלשון, שהרי נאמר בו \u0003\"מות יומת דמיו בו יהיה\"\u0004 (יחזקאל שם) — \u0003הוקשו\u0004 (הושוו) בפסוק \u0003מלוי רבית לשופכי דמים\u0004 וכשם שלמדים לענין חומרת העבירה כך נלמד כי \u0003מה שופכי דמים לא ניתנו\u0004 אותם דמים \u0003להשבון\u0004 — \u0003אף מלוי רבית לא נתנו\u0004 מעות הריבית \u0003להשבון.\u0004","\u0003אמר רב נחמן בר יצחק: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעזר\u0004 שאומר שריבית מן התורה יוצאה בדיינים וניתנת איפוא להשבון — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006"]]};
